def docx_body_pages_text(path):
    document = Document(str(path))
    pages = [[]]
    for child in document.element.body.iterchildren():
        if child.tag == qn("w:p"):
            text = "".join(node.text or "" for node in child.iter(qn("w:t")))
            if text:
                pages[-1].append(text)
            if any(node.get(qn("w:type")) == "page" for node in child.iter(qn("w:br"))):
                pages.append([])
        elif child.tag == qn("w:tbl"):
            text = "\n".join(node.text or "" for node in child.iter(qn("w:t")) if node.text)
            if text:
                pages[-1].append(text)
    return ["\n".join(page).strip() for page in pages]


def docx_first_page_tables(path):
    document = Document(str(path))
    tables = []
    for child in document.element.body.iterchildren():
        if child.tag == qn("w:tbl"):
            for table in document.tables:
                if table._tbl is child:
                    tables.append(table)
                    break
        elif child.tag == qn("w:p") and any(node.get(qn("w:type")) == "page" for node in child.iter(qn("w:br"))):
            break
    return tables


def docx_tables_text(path):
    document = Document(str(path))
    tables = []
    for table in document.tables:
        rows = []
        for row in table.rows:
            rows.append([cell.text.strip() for cell in row.cells])
        tables.append(rows)
    return tables


def docx_inline_shape_alt_texts(path):
    document = Document(str(path))
    values = []
    for shape in document.inline_shapes:
        doc_pr = shape._inline.docPr
        values.append(" ".join(
            part for part in (doc_pr.get("title"), doc_pr.get("descr")) if part
        ))
    return values


def assert_isolated_handler_environment(temp_root, storage_root, nas_root):
    temp_root = Path(temp_root).resolve()
    resolved = {
        "database": Path(app_module.db.path).resolve(),
        "storage": Path(storage_root).resolve(),
        "nas": Path(nas_root).resolve(),
    }
    forbidden = (
        Path("database/aaie_crm.db").resolve(),
        Path("storage").resolve(),
        Path("/Volumes/Server/Students").resolve(),
    )
    for label, path in resolved.items():
        if path == temp_root or temp_root not in path.parents:
            raise AssertionError(f"Isolated {label} path is outside the temporary root: {path}")
        if any(path == blocked or blocked in path.parents for blocked in forbidden):
            raise AssertionError(f"Isolated {label} path resolves to a protected production location: {path}")
    return {label: str(path) for label, path in resolved.items()}


def install_synthetic_visa_lifecycle_schema(
    database, student_id, *, cycle_id=1, cycle_type="transfer", stamp
):
    """Bring legacy Database.initialize fixtures up to Lifecycle 023/030 shape."""

    database.execute(
        """CREATE TABLE application_cycles(
             id INTEGER PRIMARY KEY,cycle_uid TEXT NOT NULL,
             student_id TEXT,parent_form_token TEXT,source_student_case_id INTEGER,
             cycle_type TEXT NOT NULL,education_stream TEXT NOT NULL,
             sequence_no INTEGER NOT NULL,status TEXT NOT NULL,outcome TEXT,
             opened_at TEXT NOT NULL,closed_at TEXT,created_by_user_id INTEGER,
             created_by_name TEXT,created_at TEXT,updated_by_user_id INTEGER,
             updated_by_name TEXT,updated_at TEXT
           )"""
    )
    database.execute(
        """INSERT INTO application_cycles(
             id,cycle_uid,student_id,source_student_case_id,cycle_type,
             education_stream,sequence_no,status,opened_at,created_at,updated_at
           ) VALUES(?,?,?,?,?,'school_education',1,'active',?,?,?)""",
        (
            int(cycle_id), f"synthetic-visa-{student_id}", student_id,
            9000 + int(cycle_id) if cycle_type in {"transfer", "progression"} else None,
            cycle_type, stamp, stamp, stamp,
        ),
    )
    database.execute(
        """CREATE TABLE lifecycle_module_disposition_events(
             id INTEGER PRIMARY KEY,event_uid TEXT NOT NULL UNIQUE,
             application_cycle_id INTEGER NOT NULL,module_key TEXT NOT NULL,
             disposition TEXT NOT NULL,reason TEXT,source_record_type TEXT,
             source_record_id INTEGER,actor_user_id INTEGER NOT NULL,
             occurred_at TEXT NOT NULL,created_at TEXT NOT NULL
           )"""
    )
    visa_case_columns = {
        row["name"] for row in database.all("PRAGMA table_info(visa_cases)")
    }
    if "legacy_visa_id" not in visa_case_columns:
        database.execute("ALTER TABLE visa_cases ADD COLUMN legacy_visa_id INTEGER")
    if "application_cycle_id" not in visa_case_columns:
        database.execute("ALTER TABLE visa_cases ADD COLUMN application_cycle_id INTEGER")
    database.execute(
        """CREATE TABLE visa_decision_events(
             id INTEGER PRIMARY KEY,application_cycle_id INTEGER NOT NULL UNIQUE,
             student_id TEXT NOT NULL,visa_case_id INTEGER NOT NULL,
             student_document_id INTEGER UNIQUE,visa_record_id INTEGER UNIQUE,
             decision_type TEXT NOT NULL,decision_date TEXT,confirmed_at TEXT NOT NULL,
             evidence_uploaded_at TEXT,decision_source TEXT NOT NULL,
             idempotency_key TEXT NOT NULL UNIQUE,recorded_by_user_id INTEGER,
             recorded_by_name TEXT,created_at TEXT NOT NULL
           )"""
    )
    return int(cycle_id)


