class SyntheticUploadReviewNas:
    def __init__(self, root):
        self.root = Path(root).resolve()

    def status(self):
        return {"ready": True, "root": str(self.root), "mode": "test"}

    def student_folder(self, student):
        return ensure_within(Path(student["folder_path"]), self.root)

    def category_folder(self, student, category):
        folder = ensure_within(self.student_folder(student) / category, self.student_folder(student))
        folder.mkdir(parents=True, exist_ok=True)
        return folder

    def safe_zip_members(self, zip_path, max_files=100, max_total=200 * 1024 * 1024):
        with zipfile.ZipFile(zip_path) as archive:
            members = [item for item in archive.infolist() if not item.is_dir()]
            if len(members) > max_files or sum(item.file_size for item in members) > max_total:
                raise NasSafetyError("Unsafe ZIP upload")
            if any(Path(item.filename).is_absolute() or ".." in Path(item.filename).parts for item in members):
                raise NasSafetyError("Unsafe ZIP path rejected")
            return members


