@contextmanager
def isolated_content_extract_sync_regression_environment(group_name):
    base_root = Path("tmp/content-centre-extract-sync-safebox124-phase2").resolve()
    base_root.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=f"{group_name}-", dir=base_root) as folder:
        root = Path(folder).resolve()
        paths = {
            "database": root / "database" / "regression.db",
            "storage": root / "storage",
            "upload": root / "upload",
            "media": root / "media",
            "ocr": root / "ocr-work",
            "whisper": root / "whisper-work",
            "ffmpeg": root / "ffmpeg-work",
            "nas": root / "synthetic-nas",
            "logs": root / "logs",
            "reports": root / "reports",
            "scripts": root / "synced-scripts",
        }
        for path in paths.values():
            (path.parent if path.suffix else path).mkdir(parents=True, exist_ok=True)

        old_values = {
            "db": app_module.db,
            "nas": app_module.nas,
            "content_dir": app_module.CONTENT_EXTRACTION_DIR,
            "runtime_dir": app_module.CONTENT_EXTRACTION_RUNTIME_DIR,
            "report_dir": app_module.CONTENT_REPORT_DIR,
            "script_dir": app_module.REDBOOK_SCRIPT_DOC_DIR,
            "log_dir": app_module.LOG_DIR,
        }
        old_environment = {
            key: os.environ.get(key)
            for key in ("PADDLE_PDX_CACHE_HOME", "HF_HOME", "HF_HUB_CACHE", "XDG_CACHE_HOME")
        }

        temp_db = Database(paths["database"])
        app_module.db = temp_db
        app_module.nas = SyntheticContentExtractSyncNas(paths["nas"])
        app_module.CONTENT_EXTRACTION_DIR = paths["upload"]
        app_module.CONTENT_EXTRACTION_RUNTIME_DIR = paths["media"]
        app_module.CONTENT_REPORT_DIR = paths["reports"]
        app_module.REDBOOK_SCRIPT_DOC_DIR = paths["scripts"]
        app_module.LOG_DIR = paths["logs"]
        os.environ["PADDLE_PDX_CACHE_HOME"] = str(paths["ocr"])
        os.environ["HF_HOME"] = str(paths["whisper"])
        os.environ["HF_HUB_CACHE"] = str(paths["whisper"] / "hub")
        os.environ["XDG_CACHE_HOME"] = str(paths["ffmpeg"])

        resolved = assert_isolated_content_extract_sync_environment(
            root,
            database_path=app_module.db.path,
            storage_root=paths["storage"],
            upload_root=app_module.CONTENT_EXTRACTION_DIR,
            media_root=app_module.CONTENT_EXTRACTION_RUNTIME_DIR,
            ocr_root=os.environ["PADDLE_PDX_CACHE_HOME"],
            whisper_root=os.environ["HF_HOME"],
            ffmpeg_root=os.environ["XDG_CACHE_HOME"],
            nas_root=app_module.nas.root,
        )
        if Path(app_module.db.path).resolve() != paths["database"].resolve():
            raise AssertionError("app.db.path was not bound before Content Extract/Sync initialization")

        temp_db.initialize()
        stamp = "2026-07-23T15:00:00+10:00"
        role_ids = {
            row["name"]: row["id"]
            for row in temp_db.all("SELECT id,name FROM roles")
        }
        temp_db.execute("DELETE FROM sessions")
        temp_db.execute("DELETE FROM users")
        user_specs = {
            "admin": (901, "admin", "Admin"),
            "sonnyz": (902, "sonnyz", "Admin"),
            "other_admin": (903, "other-admin-124", "Admin"),
            "manager": (904, "manager-124", "Manager"),
            "consultant": (905, "consultant-124", "Consultant"),
            "visa": (906, "visa-124", "Visa Officer"),
            "view_only": (907, "view-only-124", "View Only"),
        }
        users = {}
        for key, (user_id, username, role_name) in user_specs.items():
            temp_db.execute(
                """INSERT INTO users(
                       id,username,display_name,password_hash,role_id,is_active,must_change_password,created_at
                   ) VALUES(?,?,?,?,?,1,0,?)""",
                (user_id, username, f"Synthetic {role_name}", "isolated-hash", role_ids[role_name], stamp),
            )
            token = f"content-124-{key}"
            csrf = f"csrf-content-124-{key}"
            temp_db.execute(
                """INSERT INTO sessions(token,user_id,csrf_token,expires_at,created_at,last_seen_at)
                   VALUES(?,?,?,'2099-01-01T00:00:00+10:00',?,?)""",
                (token, user_id, csrf, stamp, stamp),
            )
            users[key] = {
                "id": user_id,
                "username": username,
                "role_name": role_name,
                "token": token,
                "csrf": csrf,
            }

        try:
            yield {
                "root": root,
                "paths": paths,
                "resolved": resolved,
                "db": temp_db,
                "users": users,
            }
        finally:
            for key, value in old_environment.items():
                if value is None:
                    os.environ.pop(key, None)
                else:
                    os.environ[key] = value
            app_module.LOG_DIR = old_values["log_dir"]
            app_module.REDBOOK_SCRIPT_DOC_DIR = old_values["script_dir"]
            app_module.CONTENT_REPORT_DIR = old_values["report_dir"]
            app_module.CONTENT_EXTRACTION_RUNTIME_DIR = old_values["runtime_dir"]
            app_module.CONTENT_EXTRACTION_DIR = old_values["content_dir"]
            app_module.nas = old_values["nas"]
            app_module.db = old_values["db"]
    try:
        base_root.rmdir()
    except OSError:
        pass


