class SyntheticContentDuplicateScriptNas:
    def __init__(self, root):
        self.root = Path(root).resolve()

    def status(self):
        return {
            "mounted": True,
            "mode": "test",
            "production_enabled": False,
            "production_locked": True,
            "root": str(self.root),
            "root_error": "",
            "ready": True,
        }


class FailingSqlConnection:
    def __init__(self, connection, needle, occurrence=1):
        self.connection = connection
        self.needle = " ".join(str(needle).split()).lower()
        self.occurrence = occurrence
        self.matches = 0

    def execute(self, sql, params=()):
        normalized = " ".join(str(sql).split()).lower()
        if self.needle in normalized:
            self.matches += 1
            if self.matches == self.occurrence:
                raise sqlite3.OperationalError(f"synthetic SQL failure: {self.needle}")
        return self.connection.execute(sql, params)

    def __getattr__(self, name):
        return getattr(self.connection, name)


def failing_transaction(database, needle, occurrence=1):
    @contextmanager
    def transaction():
        connection = database.connect()
        try:
            connection.execute("BEGIN IMMEDIATE")
            yield FailingSqlConnection(connection, needle, occurrence)
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()

    return transaction


