    def test_document_preview_returns_fallback_when_source_missing(self):
        class FakeNas:
            def student_folder(self, student):
                return Path(student["folder_path"]).resolve()

        old_db = app_module.db
        old_nas = app_module.nas
        old_preview_dir = app_module.PREVIEW_DIR
        old_append_service_log = app_module.append_service_log
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas = FakeNas()
                app_module.PREVIEW_DIR = root / "previews"
                logged = []
                app_module.append_service_log = lambda service, event, message="", **details: logged.append((service, event, message, details))
                stamp = "2026-07-03T10:00:00+10:00"
                student_folder = root / "Missing Source"
                student_folder.mkdir(parents=True)
                missing_path = student_folder / "Applications" / "Missing.pdf"
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,folder_path,form_data_json)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    ("TPREVMISS", "Source", "Missing", "New", stamp, stamp, str(student_folder), "{}"),
                )
                document_id = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,version,file_size,uploaded_at,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TPREVMISS", "Applications", "StudentPassport", missing_path.name, missing_path.name, str(missing_path), 1, 0, stamp, 1),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.query = {"size": ["large"], "page": ["1"]}
                handler.require = lambda permission: True
                handler.send_response = lambda status: setattr(handler, "response_status", status)
                handler.headers_sent = []
                handler.send_header = lambda key, value: handler.headers_sent.append((key, value))
                handler.end_headers = lambda: None
                handler.wfile = io.BytesIO()

                handler.document_preview("GET", str(document_id))

                headers = dict(handler.headers_sent)
                self.assertEqual(handler.response_status, 200)
                self.assertEqual(headers["X-Preview-Status"], "error")
                self.assertEqual(headers["X-Preview-Error-Code"], "source_missing")
                self.assertEqual(headers["X-Preview-Fallback"], "download_original")
                self.assertEqual(headers["X-Preview-Fallback-Reason"], "source_missing")
                self.assertIn("文件不存在", app_module.preview_error_message(headers["X-Preview-Fallback-Reason"]))
                self.assertTrue(any(event == "document_preview_fallback" for _, event, _, _ in logged))
                fallback_log = next(details for _, event, _, details in logged if event == "document_preview_fallback")
                self.assertEqual(fallback_log["reason"], "source_missing")
                self.assertEqual(fallback_log["filename"], "Missing.pdf")
                self.assertIn("path_summary", fallback_log)
                self.assertNotIn(str(root), str(fallback_log))
                self.assertGreater(len(handler.wfile.getvalue()), 0)
        finally:
            app_module.db = old_db
            app_module.nas = old_nas
            app_module.PREVIEW_DIR = old_preview_dir
            app_module.append_service_log = old_append_service_log

