    def _assert_school_plan_report_workspace_asset_contract(self):
        script = Path("assets/app.js").read_text(encoding="utf-8")
        ui_source = Path("ui.py").read_text(encoding="utf-8")

        self.assertIn("school-plan-report-workspace.css", ui_source)
        self.assertIn("school-plan-report-workspace.js", ui_source)
        self.assertIn('"data-school-plan-report-workspace" in body', ui_source)
        self.assertNotIn("refreshSchoolPlanLive", script)
        self.assertNotIn("[data-live-school-plan-list]", script)
        self.assertIn("[data-live-school-plan-detail]", script)

        workspace_css_path = Path("assets/school-plan-report-workspace.css")
        self.assertTrue(
            workspace_css_path.is_file(),
            "School Plan Report workspace CSS module is missing",
        )
        workspace_css = workspace_css_path.read_text(encoding="utf-8")
        root_selector = "[data-school-plan-report-workspace]"
        stack = []
        token = ""
        for character in workspace_css:
            if character == "{":
                header = token.strip()
                token = ""
                if header.startswith("@media"):
                    stack.append("media")
                elif header.startswith("@keyframes"):
                    stack.append("keyframes")
                elif stack and stack[-1] in {"keyframes", "keyframe-step"}:
                    stack.append("keyframe-step")
                else:
                    selectors = [item.strip() for item in header.split(",")]
                    self.assertTrue(selectors and all(selectors))
                    for selector in selectors:
                        self.assertTrue(
                            selector.startswith(root_selector),
                            f"Unscoped School Plan workspace selector: {selector}",
                        )
                    stack.append("selector")
            elif character == "}":
                token = ""
                if stack:
                    stack.pop()
            else:
                token += character

        from ui import page

        marked = page(
            "School Plan workspace",
            '<section data-school-plan-report-workspace></section>',
            asset_version="contract",
        )
        ordinary = page("Ordinary", "<section></section>", asset_version="contract")
        self.assertIn("/assets/school-plan-report-workspace.css?v=contract", marked)
        self.assertIn("/assets/school-plan-report-workspace.js?v=contract", marked)
        self.assertNotIn("school-plan-report-workspace.css", ordinary)
        self.assertNotIn("school-plan-report-workspace.js", ordinary)

