    def test_student_soft_delete_and_restore_are_admin_manager_only(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                manager_role = db.one("SELECT id FROM roles WHERE name='Manager'")
                consultant_role = db.one("SELECT id FROM roles WHERE name='Consultant'")
                manager_id = db.execute(
                    "INSERT INTO users(username,display_name,password_hash,role_id,is_active,created_at) VALUES(?,?,?,?,1,?)",
                    ("manager-delete", "Manager Delete", "x", manager_role["id"], "2026-07-03T00:00:00+10:00"),
                )
                consultant_id = db.execute(
                    "INSERT INTO users(username,display_name,password_hash,role_id,is_active,created_at) VALUES(?,?,?,?,1,?)",
                    ("consultant-delete", "Consultant Delete", "x", consultant_role["id"], "2026-07-03T00:00:00+10:00"),
                )
                manager = {"id": manager_id, "username": "manager-delete", "display_name": "Manager Delete", "role_name": "Manager", "module_permissions_json": json.dumps(["students"])}
                consultant = {"id": consultant_id, "username": "consultant-delete", "display_name": "Consultant Delete", "role_name": "Consultant", "module_permissions_json": json.dumps(["students"])}
                stamp = "2026-07-03T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,current_status,
                       created_date,updated_at,form_data_json
                    ) VALUES(?,?,?,?,?,?,?)""",
                    ("260001", "Delete", "Student", "New", stamp, stamp, "{}"),
                )

                self.assertTrue(app_module.can_delete_student_record(manager))
                self.assertFalse(app_module.can_delete_student_record(consultant))

                handler = object.__new__(app_module.CRMHandler)
                handler.user = manager
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}

                self.assertTrue(handler.soft_delete_student_record("260001"))
                deleted = db.one("SELECT deleted_at,deleted_by FROM students WHERE student_id='260001'")
                self.assertIsNotNone(deleted["deleted_at"])
                self.assertEqual(deleted["deleted_by"], manager["id"])

                self.assertTrue(handler.restore_student_record("260001"))
                restored = db.one("SELECT deleted_at,deleted_by FROM students WHERE student_id='260001'")
                self.assertIsNone(restored["deleted_at"])
                self.assertIsNone(restored["deleted_by"])
            finally:
                app_module.db = old_db

    def test_student_bulk_soft_delete_marks_only_active_selected_records(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                manager_role = db.one("SELECT id FROM roles WHERE name='Manager'")
                manager_id = db.execute(
                    "INSERT INTO users(username,display_name,password_hash,role_id,is_active,created_at) VALUES(?,?,?,?,1,?)",
                    ("manager-bulk-delete", "Manager Bulk Delete", "x", manager_role["id"], "2026-07-03T00:00:00+10:00"),
                )
                manager = {"id": manager_id, "username": "manager-bulk-delete", "display_name": "Manager Bulk Delete", "role_name": "Manager", "module_permissions_json": json.dumps(["students"])}
                stamp = "2026-07-03T10:00:00+10:00"
                for student_id, deleted_at in (("260010", None), ("260011", None), ("260012", stamp)):
                    db.execute(
                        """INSERT INTO students(
                           student_id,passport_last_name,passport_first_name,current_status,
                           created_date,updated_at,deleted_at,deleted_by,form_data_json
                        ) VALUES(?,?,?,?,?,?,?,?,?)""",
                        (student_id, "Bulk", student_id, "New", stamp, stamp, deleted_at, manager_id if deleted_at else None, "{}"),
                    )

                handler = object.__new__(app_module.CRMHandler)
                handler.user = manager
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}

                changed = handler.bulk_soft_delete_student_records(["260010", "260011", "260012", "999999", "260010"])

                self.assertEqual(changed, ["260010", "260011"])
                rows = {
                    row["student_id"]: row
                    for row in db.all("SELECT student_id,deleted_at,deleted_by FROM students ORDER BY student_id")
                }
                self.assertIsNotNone(rows["260010"]["deleted_at"])
                self.assertEqual(rows["260010"]["deleted_by"], manager_id)
                self.assertIsNotNone(rows["260011"]["deleted_at"])
                self.assertEqual(rows["260011"]["deleted_by"], manager_id)
                self.assertEqual(rows["260012"]["deleted_at"], stamp)
            finally:
                app_module.db = old_db

