    def test_dashboard_recent_student_visual_contract(self):
        css = Path("assets/style.css").read_text(encoding="utf-8")
        premium = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")

        recent_start = css.index(".dashboard-recent-table {")
        recent_end = css.index(".school-filter-bar", recent_start)
        recent_table_css = css[recent_start:recent_end]
        mobile_start = css.index("@media (max-width: 767px)")
        mobile_end = css.index(".documents-table", mobile_start)
        mobile_recent_table_css = css[mobile_start:mobile_end]
        premium_selector = (
            ".ui-premium-v2 .main:has(.dashboard-recent-table):has("
            "#dashboard-workflow-distribution-chart) .dashboard-recent-table a {"
        )
        premium_start = premium.index(premium_selector)
        premium_end = premium.index("}", premium_start) + 1
        premium_recent_link_rule = premium[premium_start:premium_end]
        final_premium_start = premium.index(
            "/* Phase 11 Premium V2 Dashboard Stable Baseline Polish */"
        )
        final_premium_end = premium.index(
            "/* Phase 11B-1 Dashboard Recent Workflow Completion Visibility */",
            final_premium_start,
        )
        final_premium_recent_table_css = premium[
            final_premium_start:final_premium_end
        ]

        self.assertIn("min-width: 760px", recent_table_css)
        for column, width in enumerate(("14%", "20%", "21%", "21%"), 1):
            self.assertIn(
                f".dashboard-recent-table th:nth-child({column}),\n"
                f".dashboard-recent-table td:nth-child({column}) {{\n"
                f"  width: {width};\n"
                "}",
                recent_table_css,
            )
        self.assertIn(
            ".dashboard-recent-table th:nth-child(5),\n"
            ".dashboard-recent-table td:nth-child(5),\n"
            ".dashboard-recent-table th:nth-child(6),\n"
            ".dashboard-recent-table td:nth-child(6) {\n"
            "  width: 12%;\n"
            "}",
            recent_table_css,
        )
        self.assertIn(".dashboard-recent-table td {", recent_table_css)
        self.assertIn("font-size: 13px", recent_table_css)
        self.assertIn("font-weight: 600", recent_table_css)
        self.assertIn(".dashboard-recent-created-date", recent_table_css)
        self.assertIn("white-space: nowrap", recent_table_css)
        self.assertIn("font-variant-numeric: tabular-nums", recent_table_css)
        self.assertNotIn("font-family:", recent_table_css)

        self.assertIn(
            ".dashboard-recent-table td:nth-child(6) {\n"
            "    grid-column: 2;\n"
            "    grid-row: 2;",
            mobile_recent_table_css,
        )

        self.assertIn("font-weight: 700", premium_recent_link_rule)
        self.assertNotIn("font-weight: 850", premium_recent_link_rule)
        self.assertIn(
            ".dashboard-recent-table {\n"
            "  min-width: 760px;\n"
            "}",
            final_premium_recent_table_css,
        )
        self.assertIn(
            ".dashboard-recent-table thead th {\n"
            "  color: #58677f;\n"
            "  font-size: 12px;",
            final_premium_recent_table_css,
        )
        self.assertIn(
            ".dashboard-recent-table td:nth-child(2) strong {\n"
            "  overflow-wrap: anywhere;\n"
            "  font-weight: 700;\n"
            "}",
            final_premium_recent_table_css,
        )
        self.assertIn(
            ".dashboard-recent-table td:nth-child(2) small {\n"
            "  overflow-wrap: anywhere;\n"
            "}",
            final_premium_recent_table_css,
        )
        self.assertNotIn(
            ".dashboard-recent-table td:nth-child(2) small {\n"
            "  overflow-wrap: anywhere;\n"
            "  font-weight: 700;",
            final_premium_recent_table_css,
        )

