    def test_dashboard_keeps_six_kpi_cards_with_confirmed_titles(self):
        kpis = app_module.DashboardKpis(
            in_progress_students=52,
            signed_this_week=3,
            signed_this_month=5,
            visa_granted_this_week=1,
            visa_granted_this_month=2,
            offers_uploaded_this_week=4,
            week_start=datetime(2026, 8, 3).date(),
            week_end=datetime(2026, 8, 10).date(),
            month_start=datetime(2026, 8, 1).date(),
            next_month=datetime(2026, 9, 1).date(),
        )

        html = app_module.dashboard_kpi_cards_html(kpis)

        self.assertIn('<section class="metrics dashboard-metrics dashboard-kpi-grid">', html)
        self.assertEqual(html.count('<div class="metric">'), 6)
        for title in ("在办流程", "本周签约", "本月签约", "本周下签", "本月下签", "本周 OFFER"):
            self.assertIn(f"<span>{title}</span>", html)
        self.assertNotIn("在办学生", html)
        for retired in ("本周新增", "材料待审核", "等待家长", "本月获签"):
            self.assertNotIn(f"<span>{retired}</span>", html)
        for value in (52, 3, 5, 1, 2, 4):
            self.assertIn(f"<strong>{value}</strong>", html)
        self.assertIn('/students?sort=stage', html)
        self.assertEqual(html.count('/contracts?view=list'), 2)
        self.assertEqual(html.count('/students?sort=visa_expiry'), 2)
        self.assertIn('/students?sort=offer_expiry', html)

    def test_dashboard_business_trend_periods_use_melbourne_week_and_month_boundaries(self):
        today = datetime(2026, 7, 18).date()
        weekly = app_module.dashboard_business_trend_periods("weekly", today)
        self.assertEqual(len(weekly), 8)
        self.assertEqual(weekly[0]["start"], datetime(2026, 5, 25).date())
        self.assertEqual(weekly[-1]["start"], datetime(2026, 7, 13).date())
        self.assertEqual(weekly[-1]["end"], datetime(2026, 7, 19).date())
