    def test_dashboard_key_items_30day_grouping_key_priority_and_fallback(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-18T09:00:00+10:00"
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,current_status,
                       created_date,updated_at,form_data_json
                    ) VALUES(?,?,?,?,?,?,?)""",
                    ("RK1", "Key", "Rules", "建档", stamp, stamp, "{}"),
                )
                rows = [
                    # Same related record must group even when source differs.
                    ("RK1", "offer_expiry", "Alpha", "2026-08-02", "offer", "601", "offer", "A"),
                    ("RK1", "offer_expiry", "Beta", "2026-08-02", "offer", "601", "offer", "B"),
                    # Different related records on same student/day/type must stay separate.
                    ("RK1", "offer_expiry", "Gamma", "2026-08-02", "offer", "602", "offer", "602"),
                    # Source is second priority when related is missing.
                    ("RK1", "manual", "Source one", "2026-08-03", "", "", "task", "701"),
                    ("RK1", "manual", "Source two", "2026-08-03", "", "", "task", "701"),
                    # Fallback groups by student/type/due date only, not title.
                    ("RK1", "visa_expiry", "Different title A", "2026-08-04", "", "", "", ""),
                    ("RK1", "visa_expiry", "Different title B", "2026-08-04", "", "", "", ""),
                ]
                for row in rows:
                    db.execute(
                        """INSERT INTO reminders(
                           student_id,reminder_type,title,due_date,due_datetime,status,
                           related_module,related_record_id,source_type,source_record_id,created_at
                        ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                        (row[0], row[1], row[2], row[3], f"{row[3]}T17:00:00", "Pending", row[4], row[5], row[6], row[7], stamp),
                    )

                data = app_module.dashboard_key_items_30day_data(datetime(2026, 7, 18).date())
                items = data["windows"][2]["items"]
                keys = [item["aggregation_key"] for item in items]

                self.assertEqual(data["total"], 4)
                self.assertIn("related:offer:601", keys)
                self.assertIn("related:offer:602", keys)
                self.assertIn("source:task:701", keys)
                self.assertIn("fallback:RK1:visa_expiry:2026-08-04", keys)
                grouped = {item["aggregation_key"]: item["reminder_node_count"] for item in items}
                self.assertEqual(grouped["related:offer:601"], 2)
                self.assertEqual(grouped["related:offer:602"], 1)
                self.assertEqual(grouped["source:task:701"], 2)
                self.assertEqual(grouped["fallback:RK1:visa_expiry:2026-08-04"], 2)
            finally:
                app_module.db = old_db

