    def test_signedoffer_institution_mapping_loader_is_reviewed_and_read_only(self):
        with tempfile.TemporaryDirectory() as folder:
            mapping_path = Path(folder) / "signedoffer_mapping.json"
            mapping = {
                "institution_mappings": [
                    {
                        "source_name": "Avalon College",
                        "institution_type": "private_language_school",
                        "metropolitan_area": "Melbourne",
                        "reviewed": True,
                        "match_method": "reviewed_manual_mapping",
                    },
                    {
                        "source_name": "Keyword College",
                        "institution_type": "k12_private",
                        "metropolitan_area": "Sydney",
                        "reviewed": False,
                        "match_method": "keyword_guess",
                    },
                    {
                        "source_name": "NSW Public School",
                        "institution_type": "k12_public",
                        "metropolitan_area": "Sydney",
                        "reviewed": True,
                        "match_method": "reviewed_system_level_mapping",
                    },
                ],
            }
            mapping_path.write_text(json.dumps(mapping), encoding="utf-8")
            before = mapping_path.read_text(encoding="utf-8")

            loaded = app_module.load_signedoffer_institution_mapping_baseline(mapping_path)

            self.assertIn("avalon college", loaded["institution_mappings"])
            self.assertIn("nsw public school", loaded["institution_mappings"])
            self.assertNotIn("keyword college", loaded["institution_mappings"])
            self.assertEqual(loaded["institution_mappings"]["avalon college"]["institution_type"], "private_language_school")
            self.assertEqual(loaded["institution_mappings"]["nsw public school"]["metropolitan_area"], "Sydney")
            self.assertEqual(mapping_path.read_text(encoding="utf-8"), before)

    def test_signedoffer_mapping_loader_caches_unchanged_file_by_mtime(self):
        with tempfile.TemporaryDirectory() as folder:
            mapping_path = Path(folder) / "signedoffer_mapping.json"
            mapping_path.write_text(
                json.dumps({
                    "institution_mappings": [
                        {
                            "source_name": "Avalon College",
                            "institution_type": "private_language_school",
                            "metropolitan_area": "Melbourne",
                            "reviewed": True,
                            "match_method": "reviewed_manual_mapping",
                        }
                    ]
                }),
                encoding="utf-8",
            )
            app_module.clear_signedoffer_institution_mapping_cache()
            read_count = 0
            original_read_text = Path.read_text

            def counted_read_text(path_obj, *args, **kwargs):
                nonlocal read_count
                if Path(path_obj) == mapping_path:
                    read_count += 1
                return original_read_text(path_obj, *args, **kwargs)

            try:
                with mock.patch.object(Path, "read_text", counted_read_text):
                    first = app_module.load_signedoffer_institution_mapping_baseline(mapping_path)
                    second = app_module.load_signedoffer_institution_mapping_baseline(mapping_path)
                self.assertEqual(read_count, 1)
                self.assertIs(first, second)
            finally:
                app_module.clear_signedoffer_institution_mapping_cache()

