    def test_signedoffer_institution_mapping_confirmation_writes_atomic_fixture_backup_audit_and_cache(self):
        old_db = app_module.db
        formal_mapping_path = Path("config/signedoffer_institution_reviewed_mappings_v1.json")
        formal_before = formal_mapping_path.read_bytes()
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            mapping_path = root / "config" / "signedoffer_mapping.json"
            backup_dir = root / "backups"
            mapping_path.parent.mkdir()
            payload = {
                "version": "v1",
                "scope": {"name": "fixture", "keep": True},
                "read_only_notice": "preserve",
                "institution_mappings": [
                    {
                        "source_name": "Existing School",
                        "institution_type": "k12_private",
                        "metropolitan_area": "Sydney",
                        "reviewed": True,
                        "match_method": "reviewed_manual_mapping",
                        "notes": "existing",
                    }
                ],
                "event_counting_rules": ["preserve-order"],
            }
            before_bytes = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8") + b"\n"
            mapping_path.write_bytes(before_bytes)
            before_hash = hashlib.sha256(before_bytes).hexdigest()
            db = Database(root / "aaie_crm.db")
            db.initialize()
            stamp = "2026-07-20T10:00:00+10:00"
            try:
                app_module.db = db
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TEST001", "Student", "Fixture", "Active", stamp, stamp, "{}"),
                )
                db.execute(
                    """INSERT INTO offers(id,student_id,school_name,document_type,offer_status,original_filename,uploaded_at,created_at)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    (901, "TEST001", "Laburnum Primary School", "SignedOffer", "signed", "fixture.pdf", stamp, stamp),
                )
                student_before = dict(db.one("SELECT * FROM students WHERE student_id='TEST001'"))
                offer_before = dict(db.one("SELECT * FROM offers WHERE id=901"))
                school_count_before = db.one("SELECT COUNT(*) AS count FROM schools")["count"]
                app_module.clear_signedoffer_institution_mapping_cache()
                app_module.load_signedoffer_institution_mapping_baseline(mapping_path)
                self.assertTrue(app_module.SIGNEDOFFER_INSTITUTION_MAPPING_CACHE)

                result = app_module.confirm_signedoffer_institution_mapping(
                    mapping_path=mapping_path,
                    backup_dir=backup_dir,
                    source_name="Laburnum Primary School",
                    normalized_key="laburnum primary school",
                    baseline_sha256=before_hash,
                    institution_type="k12_public",
                    metropolitan_area="Melbourne",
                    notes="  Reviewed against source PDF.  ",
                    confirmed=True,
                    user={"id": 1, "username": "admin", "role_name": "Admin"},
                    source_route="/data-updates/signedoffer-institution-mappings/review",
                    ip="127.0.0.1",
                    device="unit-test",
                )

                updated = json.loads(mapping_path.read_text(encoding="utf-8"))
                self.assertEqual(updated["scope"], payload["scope"])
                self.assertEqual(updated["event_counting_rules"], payload["event_counting_rules"])
                self.assertEqual(updated["institution_mappings"][:-1], payload["institution_mappings"])
                self.assertEqual(updated["institution_mappings"][-1], {
                    "source_name": "Laburnum Primary School",
                    "institution_type": "k12_public",
                    "metropolitan_area": "Melbourne",
                    "reviewed": True,
                    "match_method": "reviewed_manual_mapping",
                    "notes": "Reviewed against source PDF.",
                })
                self.assertTrue(mapping_path.read_bytes().endswith(b"\n"))
                backups = list(backup_dir.glob("signedoffer_institution_reviewed_mappings_v1.before-*.json"))
                self.assertEqual(len(backups), 1)
                self.assertEqual(backups[0].read_bytes(), before_bytes)
                self.assertRegex(backups[0].name, rf"before-\d{{8}}T\d{{6}}[+-]\d{{4}}-{before_hash[:8]}\.json$")
                self.assertEqual(result["old_hash"], before_hash)
                self.assertEqual(result["offer_ids"], [901])
                self.assertEqual(result["remaining_unmatched_count"], 0)
                self.assertNotEqual(result["new_hash"], before_hash)
                loaded = app_module.load_signedoffer_institution_mapping_baseline(mapping_path)
                self.assertEqual(loaded["institution_mappings"]["laburnum primary school"]["institution_type"], "k12_public")
                audit = db.one("SELECT * FROM audit_logs WHERE action_type='signedoffer_institution_mapping_reviewed'")
                self.assertEqual(audit["status"], "success")
                self.assertEqual(audit["module_name"], "data_update_centre")
                self.assertEqual(audit["record_id"], "laburnum primary school")
                self.assertEqual(audit["file_path"], str(mapping_path))
                old_value = json.loads(audit["old_value"])
                new_value = json.loads(audit["new_value"])
                self.assertEqual(old_value["old_hash"], before_hash)
                self.assertEqual(old_value["offer_ids"], [901])
                self.assertEqual(new_value["mapping"]["reviewed"], True)
                self.assertEqual(new_value["mapping"]["match_method"], "reviewed_manual_mapping")
                self.assertEqual(new_value["source_route"], "/data-updates/signedoffer-institution-mappings/review")
                self.assertEqual(new_value["new_hash"], result["new_hash"])
                self.assertEqual(dict(db.one("SELECT * FROM students WHERE student_id='TEST001'")), student_before)
                self.assertEqual(dict(db.one("SELECT * FROM offers WHERE id=901")), offer_before)
                self.assertEqual(db.one("SELECT COUNT(*) AS count FROM schools")["count"], school_count_before)
            finally:
                app_module.clear_signedoffer_institution_mapping_cache()
                app_module.db = old_db
                self.assertEqual(formal_mapping_path.read_bytes(), formal_before)

    def test_signedoffer_institution_mapping_confirmation_rejects_invalid_or_stale_requests_and_audits_failures(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            mapping_path = root / "mapping.json"
            backup_dir = root / "backups"
            payload = {
                "version": "v1",
                "institution_mappings": [
                    {
                        "source_name": "Existing School",
                        "institution_type": "k12_private",
                        "metropolitan_area": "Sydney",
                        "reviewed": True,
                        "match_method": "reviewed_manual_mapping",
                        "notes": "",
                    }
                ],
            }
            original = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8") + b"\n"
            mapping_path.write_bytes(original)
            baseline_hash = hashlib.sha256(original).hexdigest()
            db = Database(root / "aaie_crm.db")
            db.initialize()
            stamp = "2026-07-20T10:00:00+10:00"
            try:
                app_module.db = db
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TEST001", "Student", "Fixture", "Active", stamp, stamp, "{}"),
                )
                for offer_id, school_name in ((901, "Laburnum Primary School"), (902, "待确认学校"), (903, "Existing School")):
                    db.execute(
                        """INSERT INTO offers(id,student_id,school_name,document_type,offer_status,original_filename,uploaded_at,created_at)
                           VALUES(?,?,?,?,?,?,?,?)""",
                        (offer_id, "TEST001", school_name, "SignedOffer", "signed", f"{offer_id}.pdf", stamp, stamp),
                    )

                base = {
                    "mapping_path": mapping_path,
                    "backup_dir": backup_dir,
                    "source_name": "Laburnum Primary School",
                    "normalized_key": "laburnum primary school",
                    "baseline_sha256": baseline_hash,
                    "institution_type": "k12_public",
                    "metropolitan_area": "Melbourne",
                    "notes": "reviewed",
                    "confirmed": True,
                    "user": {"id": 1, "username": "admin", "role_name": "Admin"},
                    "source_route": "/data-updates/signedoffer-institution-mappings/review",
                }
                cases = (
                    ("stale_hash", {"baseline_sha256": "0" * 64}, HTTPStatus.CONFLICT),
                    ("bad_type", {"institution_type": "guessed_private"}, HTTPStatus.BAD_REQUEST),
                    ("bad_city", {"metropolitan_area": "Hobart"}, HTTPStatus.BAD_REQUEST),
                    ("unchecked", {"confirmed": False}, HTTPStatus.BAD_REQUEST),
                    ("empty_name", {"source_name": "", "normalized_key": ""}, HTTPStatus.BAD_REQUEST),
                    ("long_name", {"source_name": "A" * 301, "normalized_key": "a" * 301}, HTTPStatus.BAD_REQUEST),
                    ("long_notes", {"notes": "N" * 501}, HTTPStatus.BAD_REQUEST),
                    ("tampered_key", {"normalized_key": "different school"}, HTTPStatus.BAD_REQUEST),
                    ("not_unmatched", {"source_name": "Unknown School", "normalized_key": "unknown school"}, HTTPStatus.BAD_REQUEST),
                    ("existing", {"source_name": "Existing School", "normalized_key": "existing school"}, HTTPStatus.CONFLICT),
                    ("placeholder", {"source_name": "待确认学校", "normalized_key": "待确认学校"}, HTTPStatus.BAD_REQUEST),
                )
                for label, overrides, expected_status in cases:
                    with self.subTest(case=label):
                        values = {**base, **overrides}
                        with self.assertRaises(app_module.SignedOfferInstitutionMappingReviewError) as caught:
                            app_module.confirm_signedoffer_institution_mapping(**values)
                        self.assertEqual(caught.exception.status, expected_status)
                        self.assertEqual(mapping_path.read_bytes(), original)

                failed = db.all("SELECT * FROM audit_logs WHERE action_type='signedoffer_institution_mapping_reviewed' AND status='failed'")
                self.assertEqual(len(failed), len(cases))
                self.assertTrue(all(row["error_message"] for row in failed))
                self.assertFalse(backup_dir.exists())
            finally:
                app_module.clear_signedoffer_institution_mapping_cache()
                app_module.db = old_db

    def test_signedoffer_institution_mapping_confirmation_restores_original_when_replace_fails(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            mapping_path = root / "mapping.json"
            backup_dir = root / "backups"
            original = json.dumps({"version": "v1", "institution_mappings": []}, indent=2).encode("utf-8") + b"\n"
            mapping_path.write_bytes(original)
            before_hash = hashlib.sha256(original).hexdigest()
            db = Database(root / "aaie_crm.db")
            db.initialize()
            stamp = "2026-07-20T10:00:00+10:00"
            try:
                app_module.db = db
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TEST001", "Student", "Fixture", "Active", stamp, stamp, "{}"),
                )
                db.execute(
                    """INSERT INTO offers(id,student_id,school_name,document_type,offer_status,original_filename,uploaded_at,created_at)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    (901, "TEST001", "Laburnum Primary School", "SignedOffer", "signed", "fixture.pdf", stamp, stamp),
                )
                with mock.patch.object(app_module.os, "replace", side_effect=OSError("replace failed")):
                    with self.assertRaises(app_module.SignedOfferInstitutionMappingReviewError):
                        app_module.confirm_signedoffer_institution_mapping(
                            mapping_path=mapping_path,
                            backup_dir=backup_dir,
                            source_name="Laburnum Primary School",
                            normalized_key="laburnum primary school",
                            baseline_sha256=before_hash,
                            institution_type="k12_public",
                            metropolitan_area="Melbourne",
                            notes="",
                            confirmed=True,
                            user={"id": 1, "username": "admin", "role_name": "Admin"},
                            source_route="/data-updates/signedoffer-institution-mappings/review",
                        )
                self.assertEqual(mapping_path.read_bytes(), original)
                backups = list(backup_dir.glob("*.json"))
                self.assertEqual(len(backups), 1)
                self.assertEqual(backups[0].read_bytes(), original)
                audit = db.one("SELECT * FROM audit_logs WHERE status='failed' ORDER BY id DESC LIMIT 1")
                self.assertIn("replace failed", audit["error_message"])
            finally:
                app_module.clear_signedoffer_institution_mapping_cache()
                app_module.db = old_db

