    def test_signedoffer_institution_mapping_confirm_handler_enforces_admin_csrf_and_prg(self):
        handler = object.__new__(app_module.CRMHandler)
        handler.user = {
            "id": 1,
            "username": "admin",
            "role_name": "Admin",
            "module_permissions_json": json.dumps(["data_update_centre"]),
        }
        handler.csrf = "csrf-token"
        handler.form = {
            "csrf": "csrf-token",
            "source_name": "Laburnum Primary School",
            "normalized_key": "laburnum primary school",
            "baseline_sha256": "a" * 64,
            "institution_type": "k12_public",
            "metropolitan_area": "Melbourne",
            "notes": "Reviewed",
            "confirmed": "1",
        }
        handler.client_address = ("127.0.0.1", 1234)
        handler.headers = {"User-Agent": "unit-test"}
        redirects = []
        handler.flash_redirect = lambda location, message, kind="success": redirects.append((location, message, kind))
        handler.error_page = lambda message, status=400: redirects.append((status, message, "error"))
        result = {
            "source_name": "Laburnum Primary School",
            "institution_type_label": "公立学校",
            "metropolitan_area": "Melbourne",
            "old_hash": "a" * 64,
            "new_hash": "b" * 64,
            "remaining_unmatched_count": 2,
        }
        with mock.patch.object(app_module, "confirm_signedoffer_institution_mapping", return_value=result) as confirm:
            handler.signedoffer_institution_mapping_review_confirm("POST")
        confirm.assert_called_once()
        self.assertEqual(redirects[0][0], "/data-updates/signedoffer-institution-mappings/review")
        self.assertIn("Laburnum Primary School", redirects[0][1])
        self.assertIn("公立学校", redirects[0][1])
        self.assertIn("Melbourne", redirects[0][1])
        self.assertIn("剩余未匹配 2 项", redirects[0][1])

        denied = []
        handler.user = {**handler.user, "role_name": "Manager"}
        handler.error_page = lambda message, status=400: denied.append((status, message))
        handler.signedoffer_institution_mapping_review_confirm("POST")
        self.assertEqual(denied[0][0], HTTPStatus.FORBIDDEN)

        csrf_denied = []
        handler.user = {**handler.user, "role_name": "Admin"}
        handler.form = {**handler.form, "csrf": "wrong"}
        handler.error_page = lambda message, status=400: csrf_denied.append((status, message))
        handler.signedoffer_institution_mapping_review_confirm("POST")
        self.assertEqual(csrf_denied[0][0], HTTPStatus.FORBIDDEN)

        prohibited = []
        handler.form = {**handler.form, "csrf": "csrf-token", "reviewed": "true"}
        handler.error_page = lambda message, status=400: prohibited.append((status, message))
        with mock.patch.object(app_module, "_signedoffer_mapping_audit_failure") as failed_audit:
            handler.signedoffer_institution_mapping_review_confirm("POST")
        self.assertEqual(prohibited[0][0], HTTPStatus.BAD_REQUEST)
        self.assertIn("reviewed", prohibited[0][1])
        failed_audit.assert_called_once()

        app_text = Path("app.py").read_text(encoding="utf-8")
        self.assertIn(r'r"^/data-updates/signedoffer-institution-mappings/review/confirm$"', app_text)
        self.assertIn('method == "POST" and self.parsed.path != "/login" and not self.check_csrf()', app_text)

