    def test_school_soft_delete_and_restore_are_admin_manager_only(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                admin = db.one("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'")
                visa_role = db.one("SELECT id FROM roles WHERE name='Visa Officer'")
                visa_id = db.execute(
                    "INSERT INTO users(username,display_name,password_hash,role_id,is_active,created_at) VALUES(?,?,?,?,1,?)",
                    ("visa-delete", "Visa Delete", "x", visa_role["id"], "2026-07-03T00:00:00+10:00"),
                )
                admin = dict(admin)
                admin["module_permissions_json"] = json.dumps(["school_library"])
                visa = {"id": visa_id, "username": "visa-delete", "display_name": "Visa Delete", "role_name": "Visa Officer", "module_permissions_json": json.dumps(["school_library"])}
                stamp = "2026-07-03T10:00:00+10:00"
                school_id = db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Soft Delete College", "VIC", "private", "Private", stamp, stamp),
                )

                self.assertTrue(app_module.can_delete_school_record(admin))
                self.assertFalse(app_module.can_delete_school_record(visa))

                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}

                self.assertTrue(handler.soft_delete_school_record(str(school_id)))
                deleted = db.one("SELECT deleted_at,deleted_by FROM schools WHERE id=?", (school_id,))
                self.assertIsNotNone(deleted["deleted_at"])
                self.assertEqual(deleted["deleted_by"], admin["id"])

                self.assertTrue(handler.restore_school_record(str(school_id)))
                restored = db.one("SELECT deleted_at,deleted_by FROM schools WHERE id=?", (school_id,))
                self.assertIsNone(restored["deleted_at"])
                self.assertIsNone(restored["deleted_by"])
            finally:
                app_module.db = old_db

    def test_school_bulk_soft_delete_marks_only_active_selected_records(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                admin = dict(db.one("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"))
                admin["module_permissions_json"] = json.dumps(["school_library"])
                stamp = "2026-07-03T10:00:00+10:00"
                school_ids = []
                for name, deleted_at in (("Bulk Delete One", None), ("Bulk Delete Two", None), ("Bulk Delete Already", stamp)):
                    school_id = db.execute(
                        """INSERT INTO schools(
                           school_name,state,sector_key,school_type,created_at,updated_at,deleted_at,deleted_by
                        ) VALUES(?,?,?,?,?,?,?,?)""",
                        (name, "VIC", "private", "Private", stamp, stamp, deleted_at, admin["id"] if deleted_at else None),
                    )
                    school_ids.append(school_id)

                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}

                changed = handler.bulk_soft_delete_school_records([str(school_ids[0]), str(school_ids[1]), str(school_ids[2]), "999999", str(school_ids[0])])

                self.assertEqual(changed, [str(school_ids[0]), str(school_ids[1])])
                rows = {
                    str(row["id"]): row
                    for row in db.all("SELECT id,deleted_at,deleted_by FROM schools WHERE id IN (?,?,?) ORDER BY id", tuple(school_ids))
                }
                self.assertIsNotNone(rows[str(school_ids[0])]["deleted_at"])
                self.assertEqual(rows[str(school_ids[0])]["deleted_by"], admin["id"])
                self.assertIsNotNone(rows[str(school_ids[1])]["deleted_at"])
                self.assertEqual(rows[str(school_ids[1])]["deleted_by"], admin["id"])
                self.assertEqual(rows[str(school_ids[2])]["deleted_at"], stamp)
            finally:
                app_module.db = old_db

