    def test_crime_summary_refresh_includes_non_vic_schools(self):
        class FakeDb:
            def all(self, sql, params=()):
                if "UPPER(COALESCE(state,''))='VIC'" in sql:
                    return [{"id": 1}]
                return [{"id": 1}, {"id": 2}]

            def one(self, sql, params=()):
                school_id = params[0]
                if "FROM schools" in sql:
                    return {
                        "id": school_id,
                        "state": "VIC" if school_id == 1 else "NSW",
                        "suburb": "Melbourne" if school_id == 1 else "Sydney",
                        "postcode": "3000" if school_id == 1 else "2000",
                    }
                return {
                    "id": school_id,
                    "data_level": "suburb" if school_id == 1 else "lga",
                    "suburb": "Melbourne" if school_id == 1 else "Sydney",
                    "postcode": "3000" if school_id == 1 else "2000",
                    "lga_name": "Melbourne" if school_id == 1 else "Sydney",
                    "total_recorded_offences": 10,
                    "offence_rate_per_100000": 100.0,
                    "trend_1_year_percent": None,
                    "data_year_ending": "March 2026",
                    "crimes_against_person": 1,
                    "property_and_deception_offences": 2,
                    "drug_offences": 0,
                    "public_order_and_security_offences": 0,
                    "justice_procedures_offences": 0,
                    "other_offences": 0,
                }

        refreshed_school_ids = []
        old_living = app_module.refresh_school_living_cost_summary
        old_profile = app_module.refresh_school_area_crime_profile
        old_upsert_area = app_module.data_update_upsert_school_area_crime_summary
        old_upsert_radius = app_module.data_update_upsert_radius_crime_summary
        try:
            app_module.refresh_school_living_cost_summary = lambda db, school_id: None
            app_module.refresh_school_area_crime_profile = lambda db, school_id: school_id
            app_module.data_update_upsert_school_area_crime_summary = lambda db, school_id, profile: refreshed_school_ids.append(school_id)
            app_module.data_update_upsert_radius_crime_summary = lambda db, school, radius: None

            report = app_module.data_update_refresh_crime_summaries(FakeDb())

            self.assertEqual(report["records_found"], 2)
            self.assertEqual(report["records_updated"], 2)
            self.assertEqual(refreshed_school_ids, [1, 2])
        finally:
            app_module.refresh_school_living_cost_summary = old_living
            app_module.refresh_school_area_crime_profile = old_profile
            app_module.data_update_upsert_school_area_crime_summary = old_upsert_area
            app_module.data_update_upsert_radius_crime_summary = old_upsert_radius

