    def test_school_plan_secure_share_regenerate_revokes_old_and_expired_blocks(self):
        old_db = app_module.db
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                stamp = "2026-07-03T10:00:00+10:00"
                db.execute(
                    "INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json) VALUES(?,?,?,?,?,?,?)",
                    ("TSEC004", "Link", "Regenerate", "Active", stamp, stamp, "{}"),
                )
                report_id = db.execute(
                    """INSERT INTO school_plan_reports(student_id,application_id,report_version,file_name,file_path,status,selected_school_ids,created_at,updated_at,snapshot_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TSEC004", "TSEC004", 1, "secure.pdf", str(root / "secure.pdf"), "generated", "[]", stamp, stamp, "{}"),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "display_name": "Admin", "username": "admin", "role_name": "Admin"}
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}

                first = handler.school_plan_create_share_link(report_id, regenerate=True, days=7)
                second = handler.school_plan_create_share_link(report_id, regenerate=True, days=7)

                old_link = db.one("SELECT * FROM school_plan_report_links WHERE id=?", (first["id"],))
                new_link = db.one("SELECT * FROM school_plan_report_links WHERE id=?", (second["id"],))
                self.assertEqual(old_link["status"], "revoked")
                self.assertEqual(old_link["invalidated_reason"], "regenerated")
                self.assertEqual(new_link["status"], "active")
                self.assertEqual(db.one("SELECT COUNT(*) count FROM school_plan_report_links WHERE report_id=? AND status='active'", (report_id,))["count"], 1)
                title, message, status = handler.school_plan_share_status_problem(old_link)
                self.assertEqual(status, 410)
                self.assertIn("已失效", message)
                title, message, status = handler.school_plan_share_status_problem(new_link)
                self.assertEqual(status, 200)

                db.execute("UPDATE school_plan_report_links SET status='expired',expires_at=?,invalidated_at=?,invalidated_reason=? WHERE id=?", (stamp, stamp, "expired_for_testing", second["id"]))
                expired_link = db.one("SELECT * FROM school_plan_report_links WHERE id=?", (second["id"],))
                title, message, status = handler.school_plan_share_status_problem(expired_link)
                self.assertEqual(status, 410)
                self.assertIn("已过期", message)
        finally:
            app_module.db = old_db

