    def test_school_plan_new_version_supersedes_previous_report_and_all_links(self):
        old_db = app_module.db
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                stamp = "2026-07-03T10:00:00+10:00"
                db.execute(
                    "INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json) VALUES(?,?,?,?,?,?,?)",
                    ("TSEC009", "Version", "Supersede", "Active", stamp, stamp, "{}"),
                )
                old_report_id = db.execute(
                    """INSERT INTO school_plan_reports(student_id,application_id,report_version,file_name,file_path,status,selected_school_ids,created_at,updated_at,snapshot_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TSEC009", "TSEC009", 1, "v1.pdf", str(root / "v1.pdf"), "active", "[]", stamp, stamp, "{}"),
                )
                new_report_id = db.execute(
                    """INSERT INTO school_plan_reports(student_id,application_id,report_version,file_name,file_path,status,selected_school_ids,created_at,updated_at,snapshot_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TSEC009", "TSEC009", 2, "v2.pdf", str(root / "v2.pdf"), "generated", "[]", stamp, stamp, "{}"),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "display_name": "Admin", "username": "admin", "role_name": "Admin"}
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}
                mother = handler.school_plan_create_report_viewer(old_report_id, "Mother", "Mum", "", "", can_confirm=True, is_primary=True)
                father = handler.school_plan_create_report_viewer(old_report_id, "Father", "Dad", "", "", can_confirm=False, is_primary=False)
                mother_link = handler.school_plan_create_share_link(old_report_id, regenerate=True, days=7, viewer_id=mother["id"])
                father_link = handler.school_plan_create_share_link(old_report_id, regenerate=True, days=7, viewer_id=father["id"])

                handler.school_plan_supersede_previous_versions("TSEC009", "TSEC009", new_report_id)

                old_report = db.one("SELECT * FROM school_plan_reports WHERE id=?", (old_report_id,))
                new_report = db.one("SELECT * FROM school_plan_reports WHERE id=?", (new_report_id,))
                old_links = db.all("SELECT * FROM school_plan_report_links WHERE report_id=? ORDER BY id", (old_report_id,))
                self.assertEqual(old_report["status"], "superseded")
                self.assertEqual(new_report["status"], "active")
                self.assertEqual([row["status"] for row in old_links], ["superseded", "superseded"])
                self.assertTrue(all(row["invalidated_reason"] == "newer_report_version" for row in old_links))
                title, message, status = handler.school_plan_share_status_problem(db.one("SELECT * FROM school_plan_report_links WHERE id=?", (mother_link["id"],)))
                self.assertEqual(status, 410)
                self.assertIn("新版本替代", message)
                title, message, status = handler.school_plan_share_status_problem(db.one("SELECT * FROM school_plan_report_links WHERE id=?", (father_link["id"],)))
                self.assertEqual(status, 410)
                self.assertIn("新版本替代", message)
        finally:
            app_module.db = old_db

