                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}
                link = handler.school_plan_create_share_link(report_id, regenerate=True, days=7)
                stored = db.one("SELECT * FROM school_plan_report_links WHERE id=?", (link["id"],))
                self.assertFalse(handler.school_plan_share_cookie_valid(stored))

                db.execute(
                    "UPDATE school_plan_report_links SET bound_wechat_openid=?,bound_wechat_nickname=?,bound_wechat_at=? WHERE id=?",
                    ("openid_one", "Parent One", stamp, link["id"]),
                )
                stored = db.one("SELECT * FROM school_plan_report_links WHERE id=?", (link["id"],))
                handler.headers = {"Cookie": f"{handler.school_plan_share_cookie_name(link['id'])}={handler.school_plan_share_cookie_value(stored, 'openid_two')}"}
                self.assertFalse(handler.school_plan_share_cookie_valid(stored))
                handler.headers = {"Cookie": f"{handler.school_plan_share_cookie_name(link['id'])}={handler.school_plan_share_cookie_value(stored, 'openid_one')}"}
                self.assertTrue(handler.school_plan_share_cookie_valid(stored))
