    def test_school_plan_confirmation_archive_is_idempotent_for_same_confirmation(self):
        old_db = app_module.db
        old_nas = app_module.nas
        old_confirmation_dir = app_module.SCHOOL_PLAN_CONFIRMATION_DIR

        class FakeNas:
            def __init__(self, root):
                self.root = Path(root)

            def student_folder(self, student):
                return Path(student["folder_path"]).resolve()

            def category_folder(self, student, category):
                folder = self.student_folder(student) / category
                folder.mkdir(parents=True, exist_ok=True)
                return folder

        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas = FakeNas(root)
                app_module.SCHOOL_PLAN_CONFIRMATION_DIR = root / "reports" / "confirmations"
                stamp = "2026-07-03T10:00:00+10:00"
                student_folder = root / "Yunxi Tian"
                (student_folder / "Applications").mkdir(parents=True)
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,folder_path,form_data_json)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    ("TSEC004", "Tian", "Yunxi", "Active", stamp, stamp, str(student_folder), "{}"),
                )
                report_pdf = root / "Yunxi_Tian_School_Plan_v1.pdf"
                c = canvas.Canvas(str(report_pdf), pagesize=(612, 792))
                c.drawString(72, 720, "Final school plan")
                c.save()
                snapshot = {
                    "student": {"student_id": "TSEC004", "passport_first_name": "Yunxi", "passport_last_name": "Tian"},
                    "schools": [{"basic_info": {"id": 10, "school_name": "First Confirm School"}}],
                    "report_version": 1,
                }
                report_id = db.execute(
                    """INSERT INTO school_plan_reports(student_id,application_id,report_version,file_name,file_path,status,selected_school_ids,created_at,updated_at,snapshot_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TSEC004", "TSEC004", 1, report_pdf.name, str(report_pdf), "shared", "[10]", stamp, stamp, json.dumps(snapshot)),
                )
                viewer_id = db.execute(
                    """INSERT INTO school_plan_report_viewers(report_id,student_id,application_id,viewer_role,viewer_name,can_confirm,is_primary,status,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (report_id, "TSEC004", "TSEC004", "Mother", "Mum", 1, 1, "active", stamp, stamp),
                )
                link_id = db.execute(
                    """INSERT INTO school_plan_report_links(report_id,viewer_id,student_id,application_id,token_hash,token_last_4,share_url,status,expires_at,created_at,bound_wechat_openid,bound_wechat_nickname)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (report_id, viewer_id, "TSEC004", "TSEC004", "hash", "hash", "http://127.0.0.1:8781/school-plan-share/test", "active", stamp, stamp, "openid123456", "张妈妈"),
                )
                signature = root / "signature.png"
                image = Image.new("RGB", (360, 120), "white")
                image.save(signature)
                confirmation_id = db.execute(
                    """INSERT INTO school_plan_report_confirmations(report_id,viewer_id,student_id,application_id,link_id,confirmed_at,confirmed_ip,user_agent,wechat_openid,wechat_nickname,signature_image_path,confirmation_statement,status,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (report_id, viewer_id, "TSEC004", "TSEC004", link_id, stamp, "127.0.0.1", "UnitTest", "openid123456", "张妈妈", str(signature), "confirmed", "confirmed", stamp, stamp),
                )
                db.execute(
                    """INSERT INTO school_plan_report_school_rankings(confirmation_id,report_id,school_id,school_name,rank_order,created_at)
                       VALUES(?,?,?,?,?,?)""",
                    (confirmation_id, report_id, 10, "First Confirm School", 1, stamp),
                )
                handler = object.__new__(app_module.CRMHandler)

                first = handler.school_plan_archive_confirmation_documents(confirmation_id)
                second = handler.school_plan_archive_confirmation_documents(confirmation_id)

                docs = db.all(
                    """SELECT document_type,original_name,stored_name,version,file_path FROM student_documents
                       WHERE student_id='TSEC004' AND folder_category='Applications'
                       ORDER BY id"""
                )
                self.assertEqual([row["document_type"] for row in docs], [
                    "FinalConfirmedSchoolPlan",
                    "ParentSignaturePage",
                ])
                self.assertEqual([row["version"] for row in docs], [1, 1])
                for row in docs:
                    archived_name = Path(row["file_path"]).name
                    self.assertEqual(row["original_name"], archived_name)
                    self.assertEqual(row["stored_name"], archived_name)
                self.assertTrue(Path(first["final_document_path"]).is_file())
                self.assertTrue(Path(first["signature_document_path"]).is_file())
                self.assertTrue(Path(second["final_document_path"]).is_file())
                self.assertEqual(first["final_document_id"], second["final_document_id"])
                self.assertEqual(first["signature_document_id"], second["signature_document_id"])
                self.assertEqual(first["final_document_path"], second["final_document_path"])
                self.assertEqual(first["signature_document_path"], second["signature_document_path"])
                final_reader = app_module.PdfReader(str(first["final_document_path"]))
                self.assertEqual(len(final_reader.pages), 2)
                final_text = "\n".join(page.extract_text() or "" for page in final_reader.pages)
                self.assertIn("AAIE 客户专属报告", final_text)
                self.assertIn("张妈妈", final_text)
        finally:
            app_module.db = old_db
            app_module.nas = old_nas
            app_module.SCHOOL_PLAN_CONFIRMATION_DIR = old_confirmation_dir

