    def test_school_plan_brochure_route_returns_same_domain_html_not_raw_pdf(self):
        old_db = app_module.db
        old_preview_dir = app_module.PREVIEW_DIR
        old_render_pdf_page = app_module.render_pdf_page
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.PREVIEW_DIR = root / "previews"
                stamp = "2026-07-07T15:00:00+10:00"
                db.execute(
                    "INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json) VALUES(?,?,?,?,?,?,?)",
                    ("TSEC011", "Brochure", "Route", "Active", stamp, stamp, "{}"),
                )
                school_id = db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Internal Brochure College", "VIC", "government", "Government", stamp, stamp),
                )
                brochure_pdf = root / "Internal Brochure College.pdf"
                pdf_canvas = canvas.Canvas(str(brochure_pdf))
                pdf_canvas.drawString(72, 720, "Internal Brochure College page 1")
                pdf_canvas.showPage()
                pdf_canvas.save()
                document_id = db.execute(
                    """INSERT INTO school_documents(school_id,document_type,original_filename,stored_filename,file_path,file_size,source_url,notes,uploaded_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (
                        school_id,
                        "School Brochure",
                        "Internal Brochure College.pdf",
                        "Internal Brochure College.pdf",
                        str(brochure_pdf),
                        brochure_pdf.stat().st_size,
                        "https://example.edu/internal-brochure.pdf",
                        "2026 School Brochure",
                        stamp,
                    ),
                )
                snapshot = {
                    "student": {"student_id": "TSEC011", "passport_first_name": "Route", "passport_last_name": "Brochure"},
                    "schools": [{"basic_info": {"id": school_id, "school_name": "Internal Brochure College"}}],
                    "report_year": "2026",
                    "report_version": 1,
                }
                report_id = db.execute(
                    """INSERT INTO school_plan_reports(student_id,application_id,report_version,file_name,file_path,status,selected_school_ids,created_at,updated_at,snapshot_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TSEC011", "TSEC011", 1, "secure.pdf", str(root / "secure.pdf"), "generated", json.dumps([school_id]), stamp, stamp, json.dumps(snapshot)),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "display_name": "Admin", "username": "admin", "role_name": "Admin"}
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}
                viewer = handler.school_plan_create_report_viewer(report_id, "Primary Parent", "Parent", "", "", can_confirm=True, is_primary=True)
                link = handler.school_plan_create_share_link(report_id, regenerate=True, days=7, viewer_id=viewer["id"])
                db.execute(
                    "UPDATE school_plan_report_links SET bound_wechat_openid=?,bound_wechat_nickname=?,bound_wechat_at=? WHERE id=?",
                    ("android_openid", "安卓家长", stamp, link["id"]),
                )
                stored = handler.school_plan_share_row_by_token(link["plain_token"])
                handler.headers = {
                    "Cookie": f"{handler.school_plan_share_cookie_name(link['id'])}={handler.school_plan_share_cookie_value(stored, 'android_openid')}",
                    "User-Agent": "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 MicroMessenger/8.0",
                }
                handler.send_html = lambda html, *args, **kwargs: html
                def fake_render(_data, page_number=1):
                    image = Image.new("RGB", (80, 120), "white")
                    draw = ImageDraw.Draw(image)
                    draw.text((10, 48), f"Page {page_number}", fill="black")
                    return image
                app_module.render_pdf_page = fake_render

                html = handler.school_plan_share_brochure_file("GET", link["plain_token"], str(document_id))

                self.assertIsInstance(html, str)
                self.assertIn("学校官方介绍资料", html)
                self.assertIn("AAIE 安全查看模式", html)
                self.assertIn("Internal Brochure College", html)
                self.assertIn("brochure-preview-pages", html)
                self.assertIn(f'/school-plan-share/{link["plain_token"]}/brochures/{document_id}/preview?page=1', html)
                self.assertIn('alt="Internal Brochure College 学校官方 Brochure 第 1 页"', html)
                self.assertNotIn("application/pdf", html)
                self.assertNotIn("Content-Disposition", html)
                self.assertNotIn("https://example.edu/internal-brochure.pdf", html)
                self.assertNotIn("<iframe", html.lower())
                self.assertNotIn("<embed", html.lower())
                self.assertNotIn("<object", html.lower())
                self.assertNotIn('target="_blank"', html)
                self.assertNotIn("window.open", html)

                handler.query = {"page": ["1"]}
                handler.send_response = lambda status: setattr(handler, "response_status", status)
                handler.headers_sent = []
                handler.send_header = lambda key, value: handler.headers_sent.append((key, value))
                handler.end_headers = lambda: None
                handler.wfile = io.BytesIO()

                handler.school_plan_share_brochure_preview("GET", link["plain_token"], str(document_id))

                headers = dict(handler.headers_sent)
                self.assertEqual(handler.response_status, 200)
                self.assertEqual(headers["Content-Type"], "image/png")
                self.assertEqual(headers["X-Preview-Page"], "1")
                self.assertGreater(len(handler.wfile.getvalue()), 0)
                self.assertNotEqual(handler.wfile.getvalue()[:4], b"%PDF")
        finally:
            app_module.db = old_db
            app_module.PREVIEW_DIR = old_preview_dir
            app_module.render_pdf_page = old_render_pdf_page

    def test_school_plan_brochure_pdf_is_appended_without_reformatting(self):
        old_db = app_module.db
        old_report_dir = app_module.SCHOOL_PLAN_REPORT_DIR
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.SCHOOL_PLAN_REPORT_DIR = root / "reports" / "school_plan_reports"
                stamp = "2026-07-02T10:00:00+10:00"
                school_id = db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Codex Report College", "VIC", "private", "Private", stamp, stamp),
                )
                generated_pdf = root / "generated.pdf"
                brochure_pdf = root / "Codex Report College 2026 School Brochure.pdf"
                final_pdf = root / "final.pdf"
                for path, title in ((generated_pdf, "CRM generated report"), (brochure_pdf, "Original school brochure")):
                    c = canvas.Canvas(str(path), pagesize=(612, 792))
                    c.drawString(72, 720, title)
                    if path == generated_pdf:
                        c.drawString(72, 690, "AAIE Confidential")
                    c.save()
                db.execute(
                    """INSERT INTO school_documents(school_id,document_type,original_filename,stored_filename,file_path,file_size,source_url,notes,uploaded_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (
                        school_id,
                        "School Brochure",
                        brochure_pdf.name,
                        brochure_pdf.name,
                        str(brochure_pdf),
                        brochure_pdf.stat().st_size,
                        "",
                        "2026 School Brochure",
                        stamp,
                    ),
                )

                attachments = app_module.school_plan_append_school_brochures(
                    generated_pdf,
                    final_pdf,
                    [str(school_id)],
                    "2026",
                )

                self.assertEqual([item["document_type"] for item in attachments], ["School Brochure"])
                self.assertEqual(len(app_module.PdfReader(str(generated_pdf)).pages), 1)
                self.assertEqual(len(app_module.PdfReader(str(brochure_pdf)).pages), 1)
                final_reader = app_module.PdfReader(str(final_pdf))
                self.assertEqual(len(final_reader.pages), 3)
                self.assertIn("AAIE Confidential", final_reader.pages[0].extract_text())
                self.assertIn("AAIE Confidential", final_reader.pages[1].extract_text())
                self.assertIn("Original school brochure", final_reader.pages[2].extract_text())
                self.assertNotIn("AAIE Confidential", final_reader.pages[2].extract_text())
        finally:
            app_module.db = old_db
            app_module.SCHOOL_PLAN_REPORT_DIR = old_report_dir

