    def test_school_plan_final_baseline_static_map_ignores_area_context(self):
        handler = object.__new__(app_module.CRMHandler)
        school = {
            "school_name": "McKinnon Secondary College",
            "suburb": "McKinnon",
            "state": "VIC",
            "latitude": "-37.9109",
            "longitude": "145.0399",
        }
        tile = Image.new("RGB", (256, 256), "#dbeafe")
        draw = ImageDraw.Draw(tile)
        draw.rectangle((0, 0, 127, 127), fill="#bfdbfe")
        draw.rectangle((128, 0, 255, 127), fill="#dcfce7")
        draw.rectangle((0, 128, 127, 255), fill="#fef3c7")
        draw.rectangle((128, 128, 255, 255), fill="#f1f5f9")
        tile_buffer = io.BytesIO()
        tile.save(tile_buffer, format="PNG")
        tile_payload = tile_buffer.getvalue()

        class FakeTileResponse:
            def __enter__(self):
                return self

            def __exit__(self, exc_type, exc, tb):
                return False

            def read(self):
                return tile_payload

        with tempfile.TemporaryDirectory() as folder:
            with mock.patch.object(app_module, "APP_DIR", Path(folder)), mock.patch.object(
                app_module.urllib.request,
                "urlopen",
                return_value=FakeTileResponse(),
            ) as fake_urlopen:
                first = handler.school_plan_snapshot_static_map_data_uri(
                    school,
                    {"latitude": "-37.9090", "longitude": "145.0380", "sa2_name": "McKinnon - Ormond"},
                )
                second = handler.school_plan_snapshot_static_map_data_uri(
                    school,
                    {"latitude": "-33.8688", "longitude": "151.2093", "sa2_name": "Sydney"},
                )

        self.assertTrue(first.startswith("data:image/png;base64,"))
        self.assertEqual(first, second)
        self.assertGreater(fake_urlopen.call_count, 0)
        source = Path("app.py").read_text(encoding="utf-8")
        map_source = source[
            source.index("def school_plan_snapshot_static_map_data_uri"):
            source.index("def school_plan_build_snapshot")
        ]
        self.assertNotIn('("area",', map_source)
        self.assertNotIn("area_distance", map_source)
        self.assertNotIn("area_xy", map_source)
        self.assertNotIn("所在区", map_source)

    def test_school_plan_final_baseline_readonly_samples_parent_fixture_and_formal_state(self):
        handler = object.__new__(app_module.CRMHandler)

        def database_digest():
            connection = sqlite3.connect(f"file:{Path('database/aaie_crm.db').resolve()}?mode=ro", uri=True)
            connection.row_factory = sqlite3.Row
            try:
                tables = (
                    "school_plan_reports",
                    "school_plan_report_links",
                    "school_plan_report_confirmations",
                    "school_plan_report_events",
                    "school_plan_report_view_logs",
                    "school_plan_report_viewers",
                )
                payload = []
                for table in tables:
                    payload.append((table, [dict(row) for row in connection.execute(f"SELECT * FROM {table} ORDER BY 1")]))
                return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest()
            finally:
                connection.close()

        def report_tree_digest():
            root = Path("reports/school_plan_reports")
            rows = []
            for path in sorted((item for item in root.rglob("*") if item.is_file()), key=lambda item: str(item)):
                rows.append((str(path.relative_to(root)), path.stat().st_size, hashlib.sha256(path.read_bytes()).hexdigest()))
            return hashlib.sha256(json.dumps(rows, separators=(",", ":")).encode()).hexdigest()

        before_database = database_digest()
        before_files = report_tree_digest()
        rendered = {}
        snapshots = {}
        for report_id in (5, 94, 101):
            report = app_module.db.one("SELECT * FROM school_plan_reports WHERE id=?", (report_id,))
            self.assertIsNotNone(report)
            snapshot = handler.school_plan_snapshot(report)
            snapshots[report_id] = snapshot
            rendered[report_id] = handler.school_plan_snapshot_report_html(snapshot, report)

        self.assertIn("地图截图暂时无法生成", rendered[5])
        self.assertNotIn("report-cbd-location-map-svg", rendered[5])
        for report_id in (94, 101):
            self.assertIn('class="report-city-cbd-map-photo"', rendered[report_id])
            self.assertNotIn("report-cbd-location-map-svg", rendered[report_id])
            self.assertIn("学校到 CBD", rendered[report_id])
            self.assertNotIn("所在区到 CBD", rendered[report_id])

        link = {
            "id": 999999,
            "report_id": 101,
            "report_version": 1,
            "snapshot_json": json.dumps(snapshots[101], ensure_ascii=False),
            "bound_wechat_nickname": "Fixture Parent",
            "bound_wechat_openid": "fixture-openid",
            "viewer_role": "Primary Parent",
            "viewer_name": "Fixture Parent",
            "student_id": "FIXTURE101",
        }
        handler.path = "/school-plan-share/fixture-token"
        handler.send_html = lambda content, *args, **kwargs: content
        handler.school_plan_share_can_confirm = lambda _link: False
        with mock.patch.object(app_module, "school_plan_find_school_brochure_document", return_value=None), mock.patch.object(
            app_module.db,
            "one",
            return_value=None,
        ):
            parent_html = handler.school_plan_share_viewer_html("fixture-token", link)
        self.assertIn("school-plan-secure-body", parent_html)
        self.assertIn('class="report-city-cbd-map-photo"', parent_html)
        self.assertNotIn("report-cbd-location-map-svg", parent_html)

        self.assertEqual(before_database, database_digest())
        self.assertEqual(before_files, report_tree_digest())

