    def test_approve_school_area_profile_updates_profile_suburb_data_and_school(self):
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            stamp = "2026-06-29T09:00:00+10:00"
            role_id = db.execute(
                "INSERT INTO roles(name,permissions_json) VALUES(?,?)",
                ("Test Role", "{}"),
            )
            user_id = db.execute(
                "INSERT INTO users(username,display_name,password_hash,role_id,created_at) VALUES(?,?,?,?,?)",
                ("area-reviewer", "Area Reviewer", "hash", role_id, stamp),
            )
            school_id = db.execute(
                """INSERT INTO schools(school_name,state,sector_key,school_type,suburb,postcode,suburb_data_status,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                ("Needs Review School", "VIC", "government", "Public", "Kenny", "2911", "Needs Review", stamp, stamp),
            )
            suburb_id = db.execute(
                """INSERT INTO school_suburbs(suburb,state,postcode,country,normalized_suburb_name,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?)""",
                ("Kenny", "ACT", "2911", "Australia", "kenny", stamp, stamp),
            )
            profile_id = db.execute(
                """INSERT INTO school_area_profiles(
                     school_id,suburb,postcode,state,sa2_code,sa2_name,data_year,source,source_url,last_checked_at,review_status,created_at,updated_at
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (school_id, "Kenny", "2911", "ACT", "801041119", "Kenny", "2021", "ABS Census 2021 SA2 Data API", "https://data.api.abs.gov.au/rest/data/example", stamp, "Needs Review", stamp, stamp),
            )
            db.execute(
                """INSERT INTO school_area_profile_metrics(profile_id,metric_key,metric_label,metric_value,metric_unit,data_year,source,source_url,raw_json,notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (profile_id, "total_population", "人口总数", 1234, "count", "2021", "ABS Census 2021 SA2 Data API", "", "", "", stamp, stamp),
            )
            suburb_data_id = db.execute(
                """INSERT INTO school_suburb_data(
                     suburb_id,data_year,source_name,source_url,source_type,fetched_at,reviewed_status,other_indicators_json,created_at,updated_at
                   ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (suburb_id, "2021", "ABS ASGS Area Profile", "https://data.api.abs.gov.au/rest/data/example", "ABS", stamp, "Needs Review", json.dumps({"school_area_profile_id": profile_id}), stamp, stamp),
            )
            db.execute(
                "UPDATE schools SET suburb_id=?,zone_data_json=? WHERE id=?",
                (suburb_id, json.dumps({"school_area_profile_id": profile_id, "suburb_data_id": suburb_data_id}), school_id),
            )

            updated = app_module.approve_school_area_profile(db, school_id, user_id=user_id)

            self.assertEqual(updated["profile_id"], profile_id)
            self.assertEqual(db.one("SELECT review_status FROM school_area_profiles WHERE id=?", (profile_id,))["review_status"], "Approved")
            self.assertEqual(db.one("SELECT reviewed_status,reviewed_by FROM school_suburb_data WHERE id=?", (suburb_data_id,))["reviewed_status"], "Approved")
            self.assertEqual(db.one("SELECT reviewed_by FROM school_suburb_data WHERE id=?", (suburb_data_id,))["reviewed_by"], user_id)
            self.assertEqual(db.one("SELECT suburb_data_status FROM schools WHERE id=?", (school_id,))["suburb_data_status"], "Approved")

