    def test_bettereducation_pdf_uses_rows_after_official_header_and_keeps_locality(self):
        class FakeAdPage:
            def extract_text(self):
                return "EOFY Prepaid $220 SIM for 365 days There are plenty of easy ways to recharge"

            def extract_tables(self):
                return [[["220", "Prepaid SIM", "Trend / Compare", "Cremorne,NSW,2090"]]]

        class FakeRankingPage:
            def extract_text(self):
                return "Better Education Rank School % Students Exams DA BE Percentile Trend /Compare Category Region Locality"

            def extract_tables(self):
                return [[
                    ["106", None, "106", "Redlands", "17.6%", "75", "416", None, None, "73", "", "Trend /\nCompare", "Non-\ngovernment", "Metro", "Cremorne,NSW,2090"],
                    ["122", None, "122", "Carlingford High School", "15.9%", "264", "1380", None, None, "219", "", "Trend /\nCompare", "Government", "Metro", "Carlingford,NSW,2118"],
                ]]

        class FakePdf:
            pages = [FakeAdPage(), FakeRankingPage()]

            def __enter__(self):
                return self

            def __exit__(self, *_args):
                return False

        class FakePdfPlumber:
            @staticmethod
            def open(*_args, **_kwargs):
                return FakePdf()

        old_pdfplumber = sys.modules.get("pdfplumber")
        sys.modules["pdfplumber"] = FakePdfPlumber
        try:
            handler = object.__new__(app_module.CRMHandler)
            upload = Upload("source_file", "HSC.pdf", "application/pdf", b"%PDF fake")
            rows = handler.school_ranking_parse_pdf(upload)
        finally:
            if old_pdfplumber is None:
                sys.modules.pop("pdfplumber", None)
            else:
                sys.modules["pdfplumber"] = old_pdfplumber

        canonical = [handler.school_ranking_canonical_row(row) for row in rows]
        self.assertEqual(len(canonical), 2)
        self.assertEqual(canonical[0]["rank"], "106")
        self.assertEqual(canonical[0]["school_name_raw"], "Redlands")
        self.assertEqual(canonical[0]["locality"], "Cremorne")
        self.assertEqual(canonical[0]["matching_name"], "Redlands, Cremorne")
        self.assertEqual(canonical[1]["rank"], "122")
        self.assertEqual(canonical[1]["school_name_raw"], "Carlingford High School")
        self.assertEqual(canonical[1]["locality"], "Carlingford")

