    def test_bettereducation_matching_requires_same_state_and_high_confidence(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                handler = object.__new__(app_module.CRMHandler)
                now = "2026-06-27T12:00:00"
                mosman_id = db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Codex Mosman High School", "NSW", "public", "Public", now, now),
                )
                db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Codex South Sydney High School", "NSW", "public", "Public", now, now),
                )
                db.execute(
                    "INSERT INTO schools(school_name,state,sector_key,school_type,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                    ("Codex Melbourne Grammar School", "VIC", "private", "Private", now, now),
                )

                exact_id, exact_name, exact_score, exact_status = handler.school_ranking_match_school("Codex Mosman High School", "NSW")
                fuzzy_id, fuzzy_name, fuzzy_score, fuzzy_status = handler.school_ranking_match_school("Codex North Sydney Boys High School", "NSW")
                cross_state_id, _name, _score, cross_state_status = handler.school_ranking_match_school("Codex Melbourne Grammar School", "NSW")

                self.assertEqual(exact_id, mosman_id)
                self.assertEqual(exact_name, "Codex Mosman High School")
                self.assertEqual(exact_score, 1.0)
                self.assertEqual(exact_status, "Matched")
                self.assertIsNone(fuzzy_id)
                self.assertNotEqual(fuzzy_status, "Matched")
                self.assertIsNone(cross_state_id)
                self.assertNotEqual(cross_state_status, "Matched")
            finally:
                app_module.db = old_db

