    def test_school_data_year_level_parser_handles_common_ranges(self):
        handler = object.__new__(app_module.CRMHandler)
        cases = {
            "7-12": ("Year 7", "Year 12", ["Year 7", "Year 8", "Year 9", "Year 10", "Year 11", "Year 12"]),
            "K-9": ("Prep / Foundation", "Year 9", ["Prep / Foundation", "Year 1", "Year 2", "Year 3", "Year 4", "Year 5", "Year 6", "Year 7", "Year 8", "Year 9"]),
            "P-9": ("Prep / Foundation", "Year 9", ["Prep / Foundation", "Year 1", "Year 2", "Year 3", "Year 4", "Year 5", "Year 6", "Year 7", "Year 8", "Year 9"]),
            "P-12": ("Prep / Foundation", "Year 12", ["Prep / Foundation", "Year 1", "Year 2", "Year 3", "Year 4", "Year 5", "Year 6", "Year 7", "Year 8", "Year 9", "Year 10", "Year 11", "Year 12"]),
            "K-12": ("Prep / Foundation", "Year 12", ["Prep / Foundation", "Year 1", "Year 2", "Year 3", "Year 4", "Year 5", "Year 6", "Year 7", "Year 8", "Year 9", "Year 10", "Year 11", "Year 12"]),
            "10-12": ("Year 10", "Year 12", ["Year 10", "Year 11", "Year 12"]),
            "7, 8, 9, 10, 11, 12": ("Year 7", "Year 12", ["Year 7", "Year 8", "Year 9", "Year 10", "Year 11", "Year 12"]),
        }
        for raw, expected in cases.items():
            with self.subTest(raw=raw):
                parsed = handler.school_data_parse_year_levels(raw)
                self.assertEqual(parsed["min_level"], expected[0])
                self.assertEqual(parsed["max_level"], expected[1])
                self.assertEqual(parsed["levels"], expected[2])
                self.assertFalse(parsed["review_required"])
        self.assertEqual(handler.school_data_parse_year_levels("1-12")["pattern"], "AllYears")

