                self.assertEqual(address["input_type"], "address")
                self.assertEqual(address["geocode_status"], "Resolved")
                self.assertEqual(address["display_label"], "搜索中心：36 Somerville Street, Doncaster VIC")
                self.assertIn("以输入地址计算", address["cbd_distance_text"])
                self.assertGreater(address["cbd_distance_km"], 0)

                stamp = "2026-06-29T18:20:00+10:00"
