    def test_school_radius_uses_nominatim_when_free_geocoding_provider_is_enabled(self):
        old_db = app_module.db
        old_method = getattr(app_module.CRMHandler, "school_radius_fetch_nominatim_geocode", None)
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                db.set_setting("geocoding_provider", "osm_nominatim")
                calls = []

                def fake_nominatim(handler, raw_input, state, input_type):
                    calls.append((raw_input, state, input_type))
                    return handler.school_radius_store_geocode_cache(
                        raw_input,
                        state,
                        input_type,
                        {
                            "formatted_address": "Testville suburb centre NSW",
                            "state": "NSW",
                            "suburb": "Testville",
                            "postcode": "2999",
                            "latitude": -33.8,
                            "longitude": 151.2,
                        },
                        source="OpenStreetMap Nominatim",
                    ), ""

                app_module.CRMHandler.school_radius_fetch_nominatim_geocode = fake_nominatim
                handler = object.__new__(app_module.CRMHandler)
                resolved = handler.school_radius_resolve_center("Testville NSW", "NSW")

                self.assertEqual(resolved["geocode_status"], "Resolved")
                self.assertEqual(resolved["geocode_source"], "OpenStreetMap Nominatim")
                self.assertEqual(calls, [("Testville", "NSW", "suburb")])
            finally:
                app_module.db = old_db
                if old_method is None:
                    delattr(app_module.CRMHandler, "school_radius_fetch_nominatim_geocode")
                else:
                    app_module.CRMHandler.school_radius_fetch_nominatim_geocode = old_method

