                self.assertIn(("Content-Type", "application/msword; charset=utf-8"), download_capture["headers"])
                self.assertTrue(any(key == "Content-Disposition" and "attachment" in value and ".doc" in value for key, value in download_capture["headers"]))
                self.assertIn("500/590/485 签证申请信息表", download_text)
                self.assertIn("申请人 / Applicants", download_text)
                self.assertIn("家庭成员表", download_text)
                self.assertIn("Submitted", download_text)

                submitted_capture = {}
