                self.assertIn("保存本页", submitted_capture["html"])
                public_handler.form = {
                    "aic_action": "save_section",
                    "home_address": "Updated by parent after submitted",
                }
                public_handler.visa_information_collection_form_wizard(
                    "POST", respondent["token"], "visa_application_info_500_590_485", "applicants"
                )
                parent_edited_assignment = db.one("SELECT * FROM visa_form_assignments WHERE id=?", (assignment["id"],))
                parent_edited_respondent = db.one("SELECT * FROM visa_information_collection_respondents WHERE id=?", (respondent["id"],))
                parent_edited_payload = json.loads(db.one("SELECT draft_json FROM visa_form_drafts WHERE assignment_id=?", (assignment["id"],))["draft_json"])
                self.assertEqual(parent_edited_assignment["status"], "Submitted")
                self.assertEqual(parent_edited_respondent["status"], "In Progress")
                self.assertEqual(parent_edited_assignment["progress_percent"], 100)
                self.assertEqual(parent_edited_payload["sections"]["applicants"]["home_address"], "Updated by parent after submitted")

                edit_capture = {}
                handler.send_html = lambda html, *args, **kwargs: edit_capture.setdefault("html", html)
                handler.student_visa_case_information_assignment_edit(
                    "GET", "260970", str(case["id"]), str(respondent["id"]), str(assignment["id"])
                )
                self.assertIn("后台修改 500/590/485 签证申请信息表", edit_capture["html"])
                self.assertIn("该表单已由家长提交，后台修改会更新当前系统记录。", edit_capture["html"])
                self.assertIn("申请人 / Applicants", edit_capture["html"])
                self.assertIn('name="applicants__home_address"', edit_capture["html"])
                handler.form = {
                    "applicants__home_address": "Updated by CRM",
                }
                edit_redirects = []
                handler.redirect = lambda location, *args, **kwargs: edit_redirects.append(location)
                handler.student_visa_case_information_assignment_edit(
                    "POST", "260970", str(case["id"]), str(respondent["id"]), str(assignment["id"])
                )
                edited_assignment = db.one("SELECT * FROM visa_form_assignments WHERE id=?", (assignment["id"],))
                edited_respondent = db.one("SELECT * FROM visa_information_collection_respondents WHERE id=?", (respondent["id"],))
                edited_payload = json.loads(db.one("SELECT draft_json FROM visa_form_drafts WHERE assignment_id=?", (assignment["id"],))["draft_json"])
                self.assertEqual(edited_assignment["status"], "Submitted")
                self.assertEqual(edited_respondent["status"], "In Progress")
                self.assertEqual(edited_payload["sections"]["applicants"]["home_address"], "Updated by CRM")
                self.assertIn("toast_message=", edit_redirects[-1])
