                handler.user = {
                    "id": 1, "username": "admin", "display_name": "Consultant A",
                    "role_name": "Admin", "permissions_json": '["*"]',
                }
                handler.csrf = "csrf"
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {"User-Agent": "unit-test"}
                redirects = []
                handler.flash_redirect = lambda url, message, kind="ok": redirects.append((url, message, kind))

                handler.form = {"actual_lodgement_date": ""}
                handler.student_visa_case_lodgement_submit("POST", "260990", str(case_id))
                self.assertEqual(redirects[-1][2], "error")
                self.assertIsNone(db.one("SELECT lodgement_recorded_at FROM visa_cases WHERE id=?", (case_id,))["lodgement_recorded_at"])

                handler.form = {"actual_lodgement_date": "2026-08-07"}
