                self.assertEqual(case["status"], "Lodged")

                handler.form = {"actual_lodgement_date": "2026-08-08"}
                handler.student_visa_case_lodgement_submit("POST", "260990", str(case_id))
                case = db.one("SELECT * FROM visa_cases WHERE id=?", (case_id,))
                self.assertEqual(case["actual_lodgement_date"], "2026-08-07")
                self.assertEqual(redirects[-1][2], "error")

                detail_capture = {}
