                item_payloads = [
                    ("Deposit", "本人", "100000", "RMB", "One-off", "0", "中国", "是", "存款证明和银行流水", "Deposit item"),
                    ("Salary", "爸爸", "10000", "RMB", "Monthly", "120000", "中国", "是", "工资流水和税单", "Salary item"),
                    ("Rental Income", "妈妈", "2000", "RMB", "Monthly", "24000", "中国", "部分", "租赁合同", "Rental item"),
                    ("Business Income", "公司", "30000", "RMB", "Annual", "30000", "中国", "待确认", "公司流水", "Business item"),
                    ("Dividend", "爸爸", "10000", "RMB", "Annual", "10000", "中国", "是", "分红证明", "Dividend item"),
                    ("Bonus", "妈妈", "5000", "RMB", "Annual", "5000", "中国", "是", "奖金证明", "Bonus item"),
                    ("Investment Return", "爷爷", "6000", "RMB", "Annual", "6000", "中国", "否", "理财收益说明", "Investment item"),
                    ("Stock Return", "奶奶", "7000", "RMB", "Annual", "7000", "香港", "部分", "股票收益截图", "Stock item"),
                    ("Other", "其他", "8000", "AUD", "Irregular", "8000", "澳洲", "待确认", "其他收入说明", "Other item"),
                ]
                for item_type, provider, amount, currency, frequency, annualized, country, evidence, evidence_notes, notes in item_payloads:
                    handler.form = {
                        "item_type": item_type,
                        "provider": provider,
                        "amount": amount,
                        "currency": currency,
                        "frequency": frequency,
                        "annualized_amount": annualized,
                        "source_country": country,
                        "evidence_available": evidence,
                        "evidence_notes": evidence_notes,
                        "notes": notes,
                    }
