                self.assertIn("本人", {row["provider"] for row in rows})
                self.assertIn("AUD", {row["currency"] for row in rows})
                self.assertIn("Irregular", {row["frequency"] for row in rows})
                self.assertIn("待确认", {row["evidence_available"] for row in rows})
