    def test_contract_center_action_card_preserves_existing_forms(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-08-09T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,current_status,
                       date_of_birth,created_date,updated_at,form_data_json
                    ) VALUES(?,?,?,?,?,?,?,?)""",
                    ("TACT001", "Action", "Card", "Active", "2010-01-01", stamp, stamp, "{}"),
                )
                contract_id = db.execute(
                    """INSERT INTO contracts(
                       student_id,contract_uid,contract_category,contract_type,contract_title,
                       contract_status,service_scope_json,generated_by,updated_at
                    ) VALUES(?,?,?,?,?,?,?,?,?)""",
                    ("TACT001", "TACT001-CONTRACT", "留学合同", "StudyAbroadContract", "AAIE 留学合同", "Draft", "[]", 1, stamp),
                )
                admin = dict(
                    db.one(
                        """SELECT u.*, r.name role_name
                           FROM users u JOIN roles r ON r.id=u.role_id
                           WHERE u.username='admin'"""
                    )
                )
                admin["permissions_json"] = json.dumps(["*"])
                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "action-card-csrf"
                handler.query = {}

                html = handler.contract_center_table("合同列表")

                self.assertEqual(html.count('data-contract-action-card'), 1)
                self.assertIn('data-contract-signed-upload', html)
                self.assertIn(f'action="/contracts/{contract_id}/signed-upload"', html)
                self.assertIn('method="post"', html)
                self.assertIn('enctype="multipart/form-data"', html)
                self.assertIn('name="csrf" value="action-card-csrf"', html)
                self.assertIn('data-contract-signed-file', html)
                self.assertIn('name="file"', html)
                self.assertIn('accept=".pdf"', html)
                self.assertIn('required', html)
                self.assertIn('data-contract-file-name', html)
                self.assertIn('尚未选择文件', html)
                self.assertIn('上传签署版 PDF', html)
                self.assertIn('选择 PDF', html)
                self.assertIn('<details class="contract-action-more">', html)
                self.assertIn('name="contract_status"', html)
                self.assertIn('data-contract-delete-form', html)
                self.assertIn('name="delete_reason_code"', html)
                self.assertIn('name="delete_reason"', html)
                self.assertIn(f'action="/contracts/{contract_id}/status"', html)
                self.assertIn(f'action="/contracts/{contract_id}/delete"', html)
                self.assertIn(
                    'data-confirm-message="确定要删除这份合同吗？删除后该合同链接将失效，家长不能再访问或签署。"',
                    html,
                )
                handler.user = {
                    "id": 99, "username": "readonly", "display_name": "Readonly",
                    "role_name": "Consultant", "permissions_json": "[]",
                }
                readonly_html = handler.contract_center_table("合同列表")
                self.assertNotIn('data-contract-signed-upload', readonly_html)
                self.assertNotIn('data-contract-delete-form', readonly_html)
            finally:
                app_module.db = old_db

