    def test_contract_management_phase1_file_picker_css_has_button_box_and_focus_feedback(self):
        css_source = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        marker = "/* Premium V2 Contract Management Phase 1 Visual Map */"
        end_marker = "/* End Premium V2 Contract Management Phase 1 Visual Map */"
        phase_css = css_source.split(marker, 1)[1].split(end_marker, 1)[0]
        list_root = (
            ".ui-premium-v2 .contract-center:has(> #contracts-section)"
        )
        picker_button_selector = (
            f"{list_root} > #contracts-section .contract-file-picker-button"
        )
        picker_button_match = re.search(
            rf"(?m)^{re.escape(picker_button_selector)}\s*\{{(?P<body>[^}}]+)\}}",
            phase_css,
        )
        self.assertIsNotNone(picker_button_match)
        picker_button_css = picker_button_match.group("body")
        for declaration in (
            "display: inline-flex;",
            "align-items: center;",
            "justify-content: center;",
            "min-height: 30px;",
            "padding: 5px 8px;",
            "border: 1px solid var(--contract-center-border);",
            "border-radius: 8px;",
            "cursor: pointer;",
        ):
            self.assertIn(declaration, picker_button_css)
        focus_selector = (
            f"{list_root} > #contracts-section "
            ".contract-signed-file-input:focus-visible + .contract-file-picker-button"
        )
        focus_match = re.search(
            rf"(?m)^{re.escape(focus_selector)}\s*\{{(?P<body>[^}}]+)\}}",
            phase_css,
        )
        self.assertIsNotNone(focus_match)
        focus_css = focus_match.group("body")
        self.assertRegex(focus_css, r"\boutline:\s*(?!none\b)[^;]+;")
        self.assertIn("outline-offset:", focus_css)

