    def test_visa_document_linking_dry_run_validates_without_writing(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-06T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TVISA003", "Dryrun", "Daisy", "Active", stamp, stamp, "{}"),
                )
                case_id = db.execute(
                    """INSERT INTO visa_cases(student_id,case_type,status,visa_subclass,decision_status,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TVISA003", "Student Visa", "Draft", "500", "Pending", stamp, stamp),
                )
                document_id = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,file_size,uploaded_at,document_status,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TVISA003", "APPLICATION", "Passport", "passport-dryrun.pdf", "passport-dryrun.pdf", "/safe/passport-dryrun.pdf", 2048, stamp, "active", 1),
                )
                db.execute(
                    "INSERT INTO workflow_status(student_id,current_stage) VALUES(?,?)",
                    ("TVISA003", "建档"),
                )
                db.execute(
                    "INSERT INTO reminders(student_id,reminder_type,due_date,notes,created_at) VALUES(?,?,?,?,?)",
                    ("TVISA003", "manual", "2026-07-20", "Keep unchanged", stamp),
                )
                before = {
                    "links": db.one("SELECT COUNT(*) total FROM visa_case_document_links")["total"],
                    "docs": db.one("SELECT COUNT(*) total FROM student_documents")["total"],
                    "active_docs": db.one("SELECT COUNT(*) total FROM student_documents WHERE is_active=1")["total"],
                    "workflow": db.one("SELECT COUNT(*) total FROM workflow_status")["total"],
                    "reminders": db.one("SELECT COUNT(*) total FROM reminders")["total"],
                }
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                handler.csrf = "csrf"
                handler.form = {"student_document_id": str(document_id), "document_role": "Passport", "notes": "Dry-run only"}
                handler.query = {}
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {"Accept": "application/json"}
                captured = {}
                handler.json_response = lambda value, status=200: captured.setdefault("response", (status, value))

                handler.visa_document_linking_dry_run("POST", str(case_id))

                status, payload = captured["response"]
                self.assertEqual(status, 200)
                self.assertTrue(payload["ok"])
                self.assertTrue(payload["dry_run"])
                self.assertTrue(payload["can_confirm"])
                self.assertEqual(payload["intent"], "visa_document_linking_dry_run")
                self.assertEqual(payload["case"]["id"], case_id)
                self.assertEqual(payload["case"]["student_id"], "TVISA003")
                self.assertEqual(payload["document"]["id"], document_id)
                self.assertEqual(payload["document"]["original_name"], "passport-dryrun.pdf")
                self.assertEqual(payload["link"]["document_role"], "Passport")
                self.assertIn("不会写入数据库", " ".join(payload["warnings"]))
                after = {
                    "links": db.one("SELECT COUNT(*) total FROM visa_case_document_links")["total"],
                    "docs": db.one("SELECT COUNT(*) total FROM student_documents")["total"],
                    "active_docs": db.one("SELECT COUNT(*) total FROM student_documents WHERE is_active=1")["total"],
                    "workflow": db.one("SELECT COUNT(*) total FROM workflow_status")["total"],
                    "reminders": db.one("SELECT COUNT(*) total FROM reminders")["total"],
                }
                self.assertEqual(after, before)
                document = db.one("SELECT * FROM student_documents WHERE id=?", (document_id,))
                self.assertEqual(document["is_active"], 1)
                self.assertEqual(document["document_status"], "active")

                app_source = Path("app.py").read_text(encoding="utf-8")
                self.assertIn('r"^/visa-management/cases/(\\d+)/documents/link-existing/dry-run$"', app_source)
            finally:
                app_module.db = old_db

    def test_visa_document_linking_dry_run_rejects_invalid_inputs_without_writing(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-06T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TVISA004", "Reject", "Rita", "Active", stamp, stamp, "{}"),
                )
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TVISA005", "Other", "Olive", "Active", stamp, stamp, "{}"),
                )
                case_id = db.execute(
                    """INSERT INTO visa_cases(student_id,case_type,status,visa_subclass,decision_status,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TVISA004", "Student Visa", "Draft", "500", "Pending", stamp, stamp),
                )
                archived_case_id = db.execute(
                    """INSERT INTO visa_cases(student_id,case_type,status,visa_subclass,decision_status,created_at,updated_at,archived_at)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    ("TVISA004", "Student Visa", "Draft", "500", "Pending", stamp, stamp, stamp),
                )
                valid_doc = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,file_size,uploaded_at,document_status,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TVISA004", "VISA", "Passport", "valid.pdf", "valid.pdf", "/safe/valid.pdf", 100, stamp, "active", 1),
                )
                other_doc = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,file_size,uploaded_at,document_status,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TVISA005", "VISA", "Passport", "other.pdf", "other.pdf", "/safe/other.pdf", 100, stamp, "active", 1),
                )
                inactive_doc = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,file_size,uploaded_at,document_status,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("TVISA004", "VISA", "Passport", "deleted.pdf", "deleted.pdf", "/safe/deleted.pdf", 100, stamp, "deleted", 0),
                )
                db.execute(
                    """INSERT INTO visa_case_document_links(visa_case_id,student_document_id,document_role,status,notes,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?)""",
                    (case_id, valid_doc, "Passport", "Linked", "Existing", stamp, stamp),
                )

                def run(case_value, document_value, role="Passport"):
                    handler = object.__new__(app_module.CRMHandler)
                    handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                    handler.csrf = "csrf"
                    handler.form = {"student_document_id": str(document_value), "document_role": role, "notes": "No write"}
                    handler.query = {}
                    handler.client_address = ("127.0.0.1", 12345)
                    handler.headers = {"Accept": "application/json"}
                    captured = {}
                    handler.json_response = lambda value, status=200: captured.setdefault("response", (status, value))
                    handler.visa_document_linking_dry_run("POST", str(case_value))
                    return captured["response"]

                before_links = db.one("SELECT COUNT(*) total FROM visa_case_document_links")["total"]
                cases = [
                    ("missing_case", 999999, valid_doc, "Visa case 不存在"),
                    ("missing_document", case_id, 999999, "student_document 不存在"),
                    ("wrong_student", case_id, other_doc, "不属于该 Visa case 的学生"),
                    ("archived_case", archived_case_id, valid_doc, "已归档"),
                    ("deleted_document", case_id, inactive_doc, "不可关联"),
                    ("duplicate", case_id, valid_doc, "已存在"),
                ]
                for label, case_value, document_value, expected in cases:
                    status, payload = run(case_value, document_value)
                    self.assertIn(status, {400, 404})
                    self.assertFalse(payload["ok"], label)
                    self.assertTrue(payload["dry_run"], label)
                    self.assertFalse(payload["can_confirm"], label)
                    self.assertIn(expected, payload["message"], label)
                    self.assertEqual(db.one("SELECT COUNT(*) total FROM visa_case_document_links")["total"], before_links, label)
                self.assertEqual(db.one("SELECT COUNT(*) total FROM student_documents WHERE is_active=0")["total"], 1)
                self.assertFalse(db.one("SELECT COUNT(*) total FROM workflow_status")["total"])
                self.assertFalse(db.one("SELECT COUNT(*) total FROM reminders")["total"])
            finally:
                app_module.db = old_db

