        self.assertIn('r"^/data-updates/logs$', app_text)
        self.assertIn('r"^/data-updates/rollback$', app_text)
        self.assertIn('r"^/data-updates/jobs/(\\d+)/confirm$"', app_text)
        self.assertIn('r"^/data-updates/academic-results/run-auto$"', app_text)
