    def test_global_toast_assistant_overlay_collision_uses_expanded_state_offsets_only(self):
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        script = Path("assets/app.js").read_text(encoding="utf-8")
        start_marker = "/* Premium V2 Toast Assistant Overlay Collision Fix */"
        end_marker = "/* End Premium V2 Toast Assistant Overlay Collision Fix */"

        self.assertIn(start_marker, css)
        self.assertIn(end_marker, css)
        collision_css = css.split(start_marker, 1)[1].split(end_marker, 1)[0]
        expanded_state = '[data-assistant-toggle][aria-expanded="true"]'
        desktop_scope = (
            ".ui-premium-v2:has("
            f"{expanded_state}) .global-reminder-toast"
        )
        assistant_scope = (
            ".ui-premium-v2:has(.global-reminder-toast):has("
            f"{expanded_state}) .assistant-widget-isolated__panel"
        )
        assistant_prompts_scope = (
            ".ui-premium-v2:has(.global-reminder-toast):has("
            f"{expanded_state}) .assistant-widget-isolated__quick-prompts"
        )
        assistant_input_scope = (
            ".ui-premium-v2:has(.global-reminder-toast):has("
            f"{expanded_state}) .assistant-widget-isolated__input"
        )
        popup_scope = (
            ".ui-premium-v2:has(.reminders-page > .reminder-popup):has("
            f"{expanded_state}) .global-reminder-toast"
        )
        triple_state = (
            ".ui-premium-v2:has(.reminders-page > .reminder-popup):has("
            ".global-reminder-toast):has("
            f"{expanded_state})"
        )
        triple_popup_scope = f"{triple_state} .reminders-page > .reminder-popup"
        triple_toast_scope = f"{triple_state} .global-reminder-toast"
        triple_assistant_scope = f"{triple_state} .assistant-widget-isolated__panel"

        for selector in (
            desktop_scope,
            assistant_scope,
            assistant_prompts_scope,
            assistant_input_scope,
            popup_scope,
            triple_popup_scope,
            triple_toast_scope,
            triple_assistant_scope,
        ):
            self.assertIn(selector, collision_css)
        for declaration in (
            "@media (min-width: 900px)",
            "right: 424px",
            "@media (max-width: 899px)",
            "top: 14px",
            "bottom: auto",
            "max-height: min(280px, 34vh)",
            "max-height: min(420px, calc(66vh - 128px))",
            "@media (max-width: 640px)",
            "max-height: min(180px, 24vh)",
            "top: calc(min(180px, 24vh) + 32px)",
            "max-height: min(140px, 18vh)",
            "max-height: min(300px, 34vh)",
            "grid-template-rows: auto minmax(0, 1fr) auto auto auto",
            "overflow: hidden",
            "grid-template-columns: minmax(0, 1fr) auto",
            "max-height: min(62px, 8vh)",
            "overscroll-behavior: contain",
        ):
            self.assertIn(declaration, collision_css)
        self.assertGreater(
            collision_css.index("@media (max-width: 640px)"),
            collision_css.index("@media (max-width: 899px)"),
        )
        for forbidden in (
            "z-index:",
            "display: none",
            "visibility: hidden",
            "opacity: 0",
            "overflow-x: hidden",
            "pointer-events: none",
        ):
            self.assertNotIn(forbidden, collision_css)
        for selector in ("body", "html", ".main", ".panel", ".card", "dialog"):
            self.assertNotRegex(collision_css, rf"\n\s*{re.escape(selector)}\s*{{")

        assistant_script = script.split("const initAssistantWidgetIsolated", 1)[-1]
        self.assertIn(
            'toggle.setAttribute("aria-expanded", open ? "true" : "false")',
            assistant_script,
        )
        self.assertNotIn("toast-assistant-overlay", script)

