    def test_assistant_readonly_api_returns_student_summary_without_writes(self):
        import assistant_nlp

        old_db = app_module.db
        old_env = os.environ.pop("OPENAI_API_KEY", None)
        with tempfile.TemporaryDirectory() as folder:
            try:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                stamp = "2026-07-06T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("20269991", "Long", "Yinuo", "Active", stamp, stamp, "{}"),
                )
                before_counts = {
                    table: db.one(f"SELECT COUNT(*) count FROM {table}")["count"]
                    for table in ("students", "student_documents", "offers", "coe_oshc", "data_update_jobs")
                }
                original_execute = db.execute

                def fail_write(*_args, **_kwargs):
                    raise AssertionError("assistant readonly API must not write to the database")

                db.execute = fail_write
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                handler.query = {"q": ["查询学生 20269991 基本信息"]}
                handler.headers = {}
                payload = {}
                handler.json_response = lambda value, status=200: payload.setdefault("response", (status, value))

                handler.api_assistant_query("GET")

                status, body = payload["response"]
                db.execute = original_execute
                after_counts = {
                    table: db.one(f"SELECT COUNT(*) count FROM {table}")["count"]
                    for table in ("students", "student_documents", "offers", "coe_oshc", "data_update_jobs")
                }
                self.assertEqual(status, 200)
                self.assertTrue(body["ok"])
                self.assertTrue(body["readonly"])
                self.assertEqual(body["intent"], "student_basic")
                self.assertEqual(body["data"]["student"]["student_id"], "20269991")
                self.assertIn("Yinuo Long", body["answer"])
                self.assertEqual(before_counts, after_counts)
                self.assertFalse(os.environ.get("OPENAI_API_KEY"))
                self.assertEqual(assistant_nlp.parse_assistant_query("查询学生 20269991 基本信息")["intent"], "student_basic")
            finally:
                app_module.db = old_db
                if old_env is not None:
                    os.environ["OPENAI_API_KEY"] = old_env

    def test_assistant_readonly_api_rejects_write_and_sql_injection_intents(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            try:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                handler.headers = {}

                payload = {}
                handler.query = {"q": ["删除学生 20269991"]}
                handler.json_response = lambda value, status=200: payload.setdefault("write", (status, value))
                handler.api_assistant_query("GET")
                write_status, write_body = payload["write"]
                self.assertEqual(write_status, 400)
                self.assertFalse(write_body["ok"])
                self.assertTrue(write_body["readonly"])
                self.assertEqual(write_body["intent"], "rejected_write")

                payload = {}
                handler.query = {"q": ["查询 20269991; DROP TABLE students; --"]}
                handler.json_response = lambda value, status=200: payload.setdefault("injection", (status, value))
                handler.api_assistant_query("GET")
                injection_status, injection_body = payload["injection"]
                self.assertEqual(injection_status, 400)
                self.assertFalse(injection_body["ok"])
                self.assertEqual(injection_body["intent"], "rejected_unsafe_input")
            finally:
                app_module.db = old_db

