    def test_assistant_widget_transparent_wrapper_does_not_intercept_page_controls(self):
        css = Path("assets/style.css").read_text(encoding="utf-8")

        def declarations(selector):
            match = re.search(rf"(?m)^{re.escape(selector)}\s*\{{([^}}]*)\}}", css)
            self.assertIsNotNone(match, msg=f"Missing assistant selector: {selector}")
            return match.group(1)

        self.assertIn("pointer-events: none;", declarations(".assistant-widget-isolated"))
        self.assertIn("pointer-events: auto;", declarations(".assistant-widget-isolated__button"))
        self.assertIn("pointer-events: auto;", declarations(".assistant-widget-isolated__panel"))

