    def test_crm_scoped_component_css_is_opt_in_only(self):
        css = Path("assets/style.css").read_text(encoding="utf-8")
        start_marker = "/* CRM scoped component styles v1 */"
        end_marker = "/* End CRM scoped component styles v1 */"
        self.assertIn(start_marker, css)
        self.assertIn(end_marker, css)
        component_css = css.split(start_marker, 1)[1].split(end_marker, 1)[0]

        required_selectors = (
            ".crm-component-card",
            ".crm-component-card__header",
            ".crm-component-card__title",
            ".crm-component-card__meta",
            ".crm-component-toolbar",
            ".crm-component-toolbar__group",
            ".crm-component-stat",
            ".crm-component-stat__label",
            ".crm-component-stat__value",
            ".crm-component-status",
            ".crm-component-empty-state",
            ".crm-component-action-row",
            ".crm-component-table-shell",
        )
        for selector in required_selectors:
            self.assertRegex(component_css, rf"(?m)^\s*{re.escape(selector)}\s*{{")

        self.assertNotIn("crm-page-shell", component_css)
        self.assertNotIn("crm-system-page", component_css)
        self.assertNotIn(":has(", component_css)

        forbidden_selectors = (
            "body",
            "html",
            ".main",
            ".panel",
            ".card",
            ".grid",
            ".btn",
            "button",
            "a",
            "input",
            "table",
            ".table-wrap",
            ".crm-data-table",
            "topbar",
            "sidebar",
        )
        for line in component_css.splitlines():
            stripped = line.strip()
            if not stripped.endswith("{"):
                continue
            selector = stripped[:-1].strip()
            self.assertTrue(selector.startswith(".crm-component-"), selector)
            for forbidden in forbidden_selectors:
                self.assertNotRegex(selector, rf"(^|[\s>+~]){re.escape(forbidden)}($|[\s.#:>+~])")

    def test_academic_results_manual_upload_creates_update_job_and_version(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            try:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                stamp = "2026-06-30T10:00:00+10:00"
                school_id = db.execute(
                    """INSERT INTO schools(school_name,state,sector_key,school_type,suburb,postcode,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    ("Academic Results Test College", "VIC", "public", "Public", "Balwyn", "3103", stamp, stamp),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                handler.csrf = "token"
                handler.query = {}
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "unit-test"}
                handler.form = {
                    "state": "VIC",
                    "data_year": "2025",
                    "data_source": "VCAA SSCAI",
                    "source_url": "https://example.edu/vcaa-sscai",
                    "update_policy": "save_as_new_version",
                    "ranking_system": "VCE",
                    "notes": "Unit test upload",
                }
                upload = app_module.Upload("source_file", "vcaa.csv", "text/csv", b"Rank,School,Locality\n1,Academic Results Test College,Balwyn\n")
                handler.files = [upload]
                captured = {}
                handler.flash_redirect = lambda url, message, kind="success": captured.update({"url": url, "message": message, "kind": kind}) or None

                handler.academic_results_manual_update("POST")

                job = db.one("SELECT * FROM data_update_jobs WHERE job_type='academic_results' ORDER BY id DESC LIMIT 1")
                self.assertEqual(job["status"], "Review required")
                self.assertEqual(job["state"], "VIC")
                self.assertEqual(job["data_year"], "2025")
                self.assertEqual(job["source_name"], "VCAA SSCAI")
                self.assertEqual(job["update_policy"], "save_as_new_version")
                self.assertEqual(job["records_found"], 1)
                self.assertEqual(job["needs_manual_confirmation_count"], 0)
                import_row = db.one("SELECT * FROM school_ranking_imports WHERE data_update_job_id=?", (job["id"],))
                self.assertEqual(import_row["source_name"], "VCAA SSCAI")
                self.assertEqual(import_row["version_key"], "academic_results_vic_2025_v1")
                version = db.one("SELECT * FROM academic_results_versions WHERE update_job_id=?", (job["id"],))
                self.assertEqual(version["version_key"], "academic_results_vic_2025_v1")
                self.assertEqual(version["status"], "Review required")
                self.assertIn("import_id=", captured["url"])
                self.assertIn(str(school_id), str(db.one("SELECT suggested_school_id FROM school_ranking_import_rows WHERE import_id=?", (import_row["id"],))["suggested_school_id"]))
            finally:
                app_module.db = old_db

