    def test_data_update_crime_staging_uses_bulk_existing_lookup(self):
        class GuardedDatabase(Database):
            def one(self, query, params=()):
                if "SELECT id FROM crime_statistics" in str(query):
                    raise AssertionError("crime staging should not query existing rows one record at a time")
                return super().one(query, params)

        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            db = GuardedDatabase(root / "aaie_crm.db")
            db.initialize()
            source = root / "Recorded_offences_by_LGA_-_Year_Ending_Mar_2026.xlsx"
            workbook = Workbook()
