            sheet.append([2026, "March", "1 North West Metro", " Banyule", 10904, 8182.138537947])
            sheet.append([2026, "March", "1 North West Metro", " Brimbank", 18784, 9442.949047788])
            workbook.save(source)
            workbook.close()

            job_id = app_module.run_data_update_action(db, "crime_statistics", user_id=None, source_paths={"crime_file": source})

            job = db.one("SELECT * FROM data_update_jobs WHERE id=?", (job_id,))
            self.assertEqual(job["status"], "Needs Confirmation")
            self.assertEqual(job["records_found"], 2)

