    def test_cross_state_school_living_cost_import_script_parses_nsw_official_sales_export(self):
        from scripts.import_cross_state_school_living_costs import (
            NSW_PROPERTY_SALES_SOURCE_NAME,
            import_nsw_property_sales_market,
            parse_nsw_property_sales_rows,
        )

        with tempfile.TemporaryDirectory() as folder:
            sales_path = Path(folder) / "nsw_official_sales_export.csv"
            sales_path.write_text(
                "\n".join([
                    "Contract Date,Suburb,Postcode,Property Type,Purchase Price",
                    "2025-10-03,MOSMAN,2088,Residence,3000000",
                    "2025-11-09,Mosman,2088,House,3200000",
                    "2025-12-12,Mosman,2088,Apartment,1100000",
                    "2025-12-20,Mosman,2088,Unit,1300000",
                    "2025-10-18,Cremorne,2090,Residence,2500000",
                    "2025-07-01,Mosman,2088,House,9999999",
                ]),
                encoding="utf-8",
            )

            rows = parse_nsw_property_sales_rows(sales_path)

            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            conn = db.connect()
            try:
                result = import_nsw_property_sales_market(conn, sales_path, apply=True)
                conn.commit()
                written = db.all(
                    """SELECT suburb, property_type, median_sale_price, period, sales_count, source
                       FROM property_market
                       WHERE state='NSW'
                       ORDER BY suburb, property_type"""
                )
            finally:
                conn.close()

        self.assertIn({
            "suburb": "Mosman",
            "property_type": "House",
            "median_sale_price": 3100000,
            "period": "Oct-Dec 2025",
            "sales_count": 2,
        }, rows)
        self.assertIn({
            "suburb": "Mosman",
            "property_type": "Unit",
            "median_sale_price": 1200000,
            "period": "Oct-Dec 2025",
            "sales_count": 2,
        }, rows)
        self.assertNotIn(9999999, [row["median_sale_price"] for row in rows])
        self.assertEqual(result["source"], NSW_PROPERTY_SALES_SOURCE_NAME)
        self.assertEqual(result["period"], "Oct-Dec 2025")
        self.assertEqual(result["changed"], 3)
        self.assertEqual(written[2]["suburb"], "Mosman")
        self.assertEqual(written[2]["property_type"], "Unit")
        self.assertEqual(written[2]["median_sale_price"], 1200000)
        self.assertEqual(written[2]["source"], NSW_PROPERTY_SALES_SOURCE_NAME)

