    def test_cross_state_school_living_cost_import_script_parses_nsw_psi_dat_zip(self):
        from scripts.import_cross_state_school_living_costs import parse_nsw_property_sales_rows

        def psi_row(locality, contract_date, price, unit="", strata="", percent_interest=""):
            fields = [
                "B", "001", "PROP123", "1", "20260629", "", unit, "10", "TEST STREET",
                locality, "2088", "650", "M", contract_date, "20260115", str(price),
                "R2", "R", "Residence", strata, "", "", percent_interest, "DP123456",
            ]
            return ";".join(fields) + ";"

        with tempfile.TemporaryDirectory() as folder:
            zip_path = Path(folder) / "20260629.zip"
            dat_text = "\n".join([
                psi_row("MOSMAN", "20251201", 3000000),
                psi_row("Mosman", "20251212", 3200000),
                psi_row("Mosman", "20251218", 1100000, unit="2", strata="12"),
                psi_row("Mosman", "20251220", 1300000, unit="3", strata="13"),
                psi_row("Mosman", "20250701", 9999999),
                psi_row("Mosman", "20251222", 500000, percent_interest="50"),
                "C;ignored;record;",
            ])
            with zipfile.ZipFile(zip_path, "w") as zf:
                zf.writestr("MOSMAN.DAT", dat_text)

            rows = parse_nsw_property_sales_rows(zip_path)

        self.assertIn({
            "suburb": "Mosman",
            "property_type": "House",
            "median_sale_price": 3100000,
            "period": "Oct-Dec 2025",
            "sales_count": 2,
        }, rows)
        self.assertIn({
            "suburb": "Mosman",
            "property_type": "Unit",
            "median_sale_price": 1200000,
            "period": "Oct-Dec 2025",
            "sales_count": 2,
        }, rows)
        self.assertNotIn(9999999, [row["median_sale_price"] for row in rows])
        self.assertNotIn(500000, [row["median_sale_price"] for row in rows])

