    def test_vpsr_download_retries_forbidden_excel_with_range_request(self):
        import urllib.error
        from unittest.mock import patch
        from scripts.import_vic_school_living_costs import download_resource

        class FakeResponse:
            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

            def read(self):
                return b"house xls bytes"

        seen_ranges = []

        def fake_urlopen(request, timeout=0):
            seen_ranges.append(request.headers.get("Range"))
            if len(seen_ranges) == 1:
                raise urllib.error.HTTPError(request.full_url, 403, "Forbidden", hdrs=None, fp=None)
            return FakeResponse()

        with tempfile.TemporaryDirectory() as folder, patch("urllib.request.urlopen", side_effect=fake_urlopen):
            target = download_resource("https://www.land.vic.gov.au/__data/assets/excel_doc/0030/773742/median-house-q4-2025.xls", Path(folder))
            target_bytes = target.read_bytes()

        self.assertEqual(target_bytes, b"house xls bytes")
        self.assertEqual(seen_ranges, [None, "bytes=0-"])

