    def test_account_password_premium_v2_phase1_render_contract_is_isolated(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            temp_root = Path(folder).resolve()
            database_path = temp_root / "database" / "account-password.db"
            storage_root = temp_root / "storage"
            nas_root = temp_root / "synthetic-nas"
            database_path.parent.mkdir(parents=True)
            storage_root.mkdir()
            nas_root.mkdir()
            temp_db = Database(database_path)
            try:
                app_module.db = temp_db
                isolated = assert_isolated_handler_environment(
                    temp_root,
                    storage_root,
                    nas_root,
                )
                self.assertEqual(isolated["database"], str(database_path))
                self.assertEqual(isolated["storage"], str(storage_root))
                self.assertEqual(isolated["nas"], str(nas_root))
                temp_db.initialize()
                user = dict(temp_db.one(
                    """SELECT u.*,r.name role_name,r.permissions_json
                       FROM users u JOIN roles r ON r.id=u.role_id
                       WHERE u.username='admin'"""
                ))
                user["module_permissions_json"] = app_module.modules_json_for_user(user["id"])

                handler = object.__new__(app_module.CRMHandler)
                handler.user = user
                handler.csrf = "account-password-phase1-csrf"
                handler.query = {}
                handler.client_address = ("127.0.0.1", 13001)
                handler.headers = {"User-Agent": "account-password-phase1-test"}
                captured = {}
                handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)

                with mock.patch.object(app_module.nas, "status", return_value={}):
                    handler.account_password("GET")

                html = captured["html"]
                self.assertEqual(html.count('class="account-password-page"'), 1)
                page_match = re.search(
                    r'<div class="account-password-page">(?P<body>.*?)</div>\s*</main>',
                    html,
                    flags=re.S,
                )
                self.assertIsNotNone(page_match)
                page_html = page_match.group("body")
                for class_name in (
                    "account-password-header",
                    "account-password-intro",
                    "account-password-card",
                    "account-password-form",
                    "account-password-field",
                    "account-password-guidance",
                    "account-password-actions",
                    "account-password-primary-action",
                    "account-password-secondary-action",
                ):
                    self.assertIn(class_name, page_html)

                forms = re.findall(r"<form\b.*?</form>", page_html, flags=re.S)
                self.assertEqual(len(forms), 1)
                form_html = forms[0]
                self.assertIn('method="post"', form_html)
                self.assertIn('action="/account/password"', form_html)
                self.assertNotIn('method="get"', page_html)
                self.assertEqual(form_html.count('name="csrf"'), 1)
                controls = re.findall(r"<input\b[^>]*>", form_html)
                visible_controls = [
                    control
                    for control in controls
                    if 'type="hidden"' not in control
                ]
                self.assertEqual(len(visible_controls), 3)
                self.assertTrue(all('type="password"' in control for control in visible_controls))
                self.assertEqual(sum(" required" in control for control in visible_controls), 3)
                self.assertEqual(form_html.count("<button"), 1)
                self.assertEqual(form_html.count('href="/"'), 1)
                self.assertIn(
                    'name="current_password" autocomplete="current-password" required',
                    form_html,
                )
                self.assertEqual(form_html.count('autocomplete="new-password"'), 2)
                self.assertEqual(form_html.count('minlength="10"'), 2)
                self.assertNotIn("data-account-password", page_html)

                app_source = Path("app.py").read_text(encoding="utf-8")
                handler_start = app_source.index("    def account_password(self, method):")
                handler_end = app_source.index("\n    def dashboard(self, method):", handler_start)
                handler_source = app_source[handler_start:handler_end]
                self.assertIn("password_verify(current_password", handler_source)
                self.assertIn(
                    '"UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?"',
                    handler_source,
                )
                self.assertIn('"password_changed"', handler_source)
                self.assertIn('"password_change_failed"', handler_source)
                self.assertIn('self.flash_redirect("/account/password"', handler_source)
                for protected_function in (
                    "def login(self, method):",
                    "def users(self, method):",
                    "def user_detail(self, method, user_id):",
                ):
                    start = app_source.index(protected_function)
                    next_def = app_source.find("\n    def ", start + len(protected_function))
                    block = app_source[start:next_def if next_def != -1 else None]
                    self.assertNotIn("account-password-page", block)
            finally:
                app_module.db = old_db

    def test_account_password_premium_v2_phase1_css_is_strictly_scoped(self):
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        start_marker = "/* Premium V2 Account Password Visual Map */"
        end_marker = "/* End Premium V2 Account Password Visual Map */"
        self.assertEqual(css.count(start_marker), 1)
        self.assertEqual(css.count(end_marker), 1)
        block = css[css.index(start_marker):css.index(end_marker) + len(end_marker)]
        for selector in (
            ".ui-premium-v2 .account-password-page",
            ".ui-premium-v2 .account-password-page .account-password-card",
            ".ui-premium-v2 .account-password-page .account-password-header",
            ".ui-premium-v2 .account-password-page .account-password-form",
            ".ui-premium-v2 .account-password-page .account-password-field",
            ".ui-premium-v2 .account-password-page .account-password-guidance",
            ".ui-premium-v2 .account-password-page .account-password-actions",
            ".ui-premium-v2 .account-password-page .account-password-primary-action",
            ".ui-premium-v2 .account-password-page .account-password-secondary-action",
        ):
            self.assertIn(selector, block)
        for forbidden in (
            ".school-new-page",
            ".school-radius-search-page",
            ".school-detail-page",
            ".login-page",
            ".user-management-page",
            ".public-shell",
        ):
            self.assertNotIn(forbidden, block)
        for broad_selector in (
            r"(?m)^\s*\.ui-premium-v2\s+form\b",
            r"(?m)^\s*\.ui-premium-v2\s+input\b",
            r"(?m)^\s*\.ui-premium-v2\s+button\b",
            r"(?m)^\s*\.ui-premium-v2\s+\.panel\b",
            r"(?m)^\s*\.ui-premium-v2\s+\.notice\b",
        ):
            self.assertNotRegex(block, broad_selector)
        self.assertIn("@media (max-width: 760px)", block)
        self.assertIn("@media (max-width: 430px)", block)
        self.assertIn("var(--card)", block)
        self.assertIn("var(--foreground)", block)
        self.assertIn("overflow-x: clip", block)
        app_js = Path("assets/app.js").read_text(encoding="utf-8")
        self.assertNotIn("account-password-page", app_js)

