    def test_extract_school_features_from_website_and_pdf(self):
        class FakeResponse:
            def __init__(self, body, content_type):
                self.content = body
                self.text = body.decode("utf-8", errors="ignore") if isinstance(body, bytes) else body
                self.headers = {"Content-Type": content_type}
                self.status_code = 200

            def raise_for_status(self):
                return None

        class FakeSession:
            def __init__(self, pdf_bytes):
                self.pdf_bytes = pdf_bytes

            def get(self, url, timeout=12, headers=None):
                if url.endswith(".pdf"):
                    return FakeResponse(self.pdf_bytes, "application/pdf")
                html = """
                <html><head><title>Brighton Grammar School</title></head>
                <body>
                  <h1>Academic extension and rowing sport program</h1>
                  <p>Students join a strong music ensemble and orchestra.</p>
                  <a href="/brochure.pdf">School brochure</a>
                </body></html>
                """
                return FakeResponse(html, "text/html")

        class FakeTag:
            def __init__(self, value):
                self.value = value

            def get(self, key, default=None):
                return self.value if key == "href" else default

        class FakeSoup:
            def __init__(self, html_text, parser):
                self.html_text = html_text

            def __call__(self, names):
                return []

            def find(self, name):
                if name == "title":
                    match = re.search(r"<title[^>]*>(.*?)</title>", self.html_text, re.I | re.S)
                    return type("FakeTitle", (), {"get_text": lambda _self, sep=" ", strip=True: match.group(1) if match else ""})()
                return None

            def find_all(self, name, href=False):
                if name != "a":
                    return []
                return [FakeTag(value) for value in re.findall(r"<a[^>]+href=['\"]([^'\"]+)['\"]", self.html_text, re.I)]

            def get_text(self, sep=" ", strip=True):
                text = re.sub(r"(?is)<(script|style).*?>.*?</\\1>", " ", self.html_text)
                text = re.sub(r"(?s)<[^>]+>", " ", text)
                return re.sub(r"\s+", " ", text).strip()

        pdf_buffer = io.BytesIO()
        pdf_canvas = canvas.Canvas(pdf_buffer)
        pdf_canvas.drawString(80, 760, "Robotics STEM learning and music production are available.")
        pdf_canvas.save()

        tags = [
            {"tag_name_cn": "学术", "tag_name_en": "Academic", "keywords": ["academic", "extension"]},
            {"tag_name_cn": "体育", "tag_name_en": "Sports", "keywords": ["sport", "rowing"]},
            {"tag_name_cn": "音乐", "tag_name_en": "Music", "keywords": ["music", "orchestra"]},
            {"tag_name_cn": "STEM", "tag_name_en": "STEM", "keywords": ["robotics", "STEM"]},
        ]
        result = app_module.extract_school_features_from_official_url(
            "https://example.edu.au",
            tags=tags,
            requests_session=FakeSession(pdf_buffer.getvalue()),
            soup_factory=FakeSoup,
        )

        self.assertEqual(result["status"], "matched")
        names = {feature["tag_name_cn"] for feature in result["features"]}
        self.assertTrue({"学术", "体育", "音乐", "STEM"}.issubset(names))
        self.assertTrue(any(feature["source_type"] == "official_pdf" for feature in result["features"]))
        self.assertTrue(all(feature["confidence_rate"] >= 50 for feature in result["features"]))
        self.assertIn("https://example.edu.au/brochure.pdf", [item["url"] for item in result["pdfs"]])

