    def test_student_detail_summary_loader_failure_logs_falls_back_and_releases_connection(self):
        from student_detail_summary_cards import (
            SchoolPlanCardSummary,
            StudentDetailCardSummary,
        )

        observations = {}

        def failing_loader(connection, student_id):
            observations["summary_connection"] = connection
            raise RuntimeError("optional summary history unavailable")

        html = self._render_student_detail_summary_fixture(
            StudentDetailCardSummary(
                student_id="260208",
                stage_key="unused",
                stage_label="不应显示",
                created_date="2026-08-07",
                schools=SchoolPlanCardSummary(("不应显示的学校",)),
            ),
            summary_loader=failing_loader,
            observations=observations,
        )

        self.assertIn("阶段暂不可用", html)
        self.assertIn("建档时间：2026-08-07", html)
        self.assertIn("家长尚未确认递交学校", html)
        self.assertIn("暂无待办提醒", html)
        self.assertNotIn("不应显示的学校", html)
        summary_failure_logs = [
            entry
            for entry in observations["service_logs"]
            if entry[0][1] == "student_detail_card_summary_failed"
        ]
        self.assertEqual(
            summary_failure_logs,
            [
                (
                    (
                        "admin",
                        "student_detail_card_summary_failed",
                        "RuntimeError('optional summary history unavailable')",
                    ),
                    {"student_id": "260208"},
                )
            ],
        )
        summary_connection = observations["summary_connection"]
        self.assertIn(summary_connection, observations["released_connections"])
        with self.assertRaises(sqlite3.ProgrammingError):
            summary_connection.execute("SELECT 1")

