    def test_workflow_completion_records_duration_metrics(self):
        old_db = app_module.db
        try:
            with tempfile.TemporaryDirectory() as folder:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json
                    ) VALUES(?,?,?,?,?,?,?)""",
                    ("TEST003", "Student", "Complete", "签证下签或拒签", "2026-01-01", "2026-03-22T10:00:00+11:00", "{}"),
                )
                db.execute(
                    """INSERT INTO workflow_status(
                       student_id,current_stage,contract_signed_at,visa_lodged_at,visa_finalized_at
                    ) VALUES(?,?,?,?,?)""",
                    ("TEST003", "签证下签或拒签", "2026-01-10", "2026-03-01", "2026-03-20"),
                )
                db.execute(
                    """INSERT INTO student_documents(
                       student_id,folder_category,document_type,original_name,stored_name,file_path,version,file_size,uploaded_at,is_active
                    ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "TEST003",
                        "Homestay + Airport Pickup",
                        "Itinerary",
                        "itinerary.pdf",
                        "Itinerary_20260322_V1.pdf",
                        "/tmp/Itinerary_20260322_V1.pdf",
                        1,
                        1,
                        "2026-03-22T09:00:00+11:00",
                        1,
                    ),
                )

                metrics = app_module.refresh_workflow_completion_metrics("TEST003", source="unit_test")
                row = db.one("SELECT * FROM workflow_status WHERE student_id=?", ("TEST003",))
                self.assertEqual(row["contract_to_visa_days"], 69)
                self.assertEqual(row["visa_lodged_to_final_days"], 19)
                self.assertTrue(row["completed_at"])
                self.assertEqual(metrics["contract_to_visa_days"], 69)
                self.assertEqual(metrics["visa_lodged_to_final_days"], 19)

                student = {"source_token": "token", "materials_checked": 1, "current_stage": "签证下签或拒签", **dict(row)}
                html = app_module.student_workflow_overview_html(student, [], [{}], [{}], [{}], [{"folder_category": "Homestay + Airport Pickup"}])
                self.assertIn("周期统计", html)
                self.assertIn("签约 → 下签", html)
                self.assertIn("递签 → 下签", html)
                self.assertIn("69 天", html)
                self.assertIn("19 天", html)
        finally:
            app_module.db = old_db

