    def test_visa_update_edits_existing_record_without_creating_duplicate(self):
        with isolated_upload_review_regression_environment("visa-document-type-update") as env:
            db = env["db"]
            student_id = env["student_id"]
            resolved_paths = env["resolved"]
            path_report = json.dumps(resolved_paths, ensure_ascii=False, sort_keys=True)

            self.assertEqual(
                Path(resolved_paths["database"]).resolve(),
                Path(db.path).resolve(),
                msg=path_report,
            )
            self.assertEqual(
                Path(resolved_paths["storage"]).resolve(),
                env["paths"]["storage_root"].resolve(),
                msg=path_report,
            )
            self.assertEqual(
                Path(resolved_paths["nas"]).resolve(),
                env["paths"]["nas_root"].resolve(),
                msg=path_report,
            )
            self.assertIs(app_module.db, db, msg=path_report)

            file_path = str(env["paths"]["storage_root"] / "original.pdf")
            record_id = db.execute(
                """INSERT INTO visas(
                   student_id,file_path,visa_type,visa_sector,visa_grant_date,visa_start_date,
                   visa_expiry_date,visa_conditions,visa_status,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (
                    student_id, file_path, "Old Visa", "Schools Sector", "2026-06-02", "",
                    "2031-03-15", "", "pending", "2026-06-02T12:00:00+10:00",
                ),
            )
            document_id = db.execute(
                """INSERT INTO student_documents(
                   student_id,folder_category,document_type,original_name,stored_name,file_path,
                   version,file_size,uploaded_by,uploaded_at,document_status,is_active
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    student_id, "VISA", "VisaGrantLetter", "grant.pdf", "grant.pdf",
                    file_path, 1, 128, None, "2026-06-02T12:00:00+10:00",
                    "active", 1,
                ),
            )
            handler = self._upload_review_handler(
                env["admin"],
                form={
                    "visa_type": "Student Visa Subclass 500",
                    "visa_sector": "Schools Sector",
                    "visa_document_type": "s56_request",
                    "visa_grant_date": "03/06/2026",
                    "visa_start_date": "",
                    "visa_expiry_date": "16/03/2031",
                    "visa_conditions": "备注已更新",
                    "visa_status": "granted",
                },
            )
            handler.visa_update("POST", student_id, str(record_id))

            rows = db.all("SELECT * FROM visas WHERE student_id=?", (student_id,))
            self.assertEqual(len(rows), 1)
            row = rows[0]
            self.assertEqual(row["id"], record_id)
            self.assertEqual(row["visa_type"], "Student Visa Subclass 500")
            # Generic metadata edits cannot confirm a decision or its grant date.
            self.assertEqual(row["visa_grant_date"], "2026-06-02")
            self.assertEqual(row["visa_expiry_date"], "2031-03-16")
            self.assertEqual(row["visa_conditions"], "备注已更新")
            self.assertEqual(row["visa_status"], "pending")
            self.assertEqual(handler.redirect_location, f"/students/{student_id}?tab=visa")
            document = db.one("SELECT * FROM student_documents WHERE id=?", (document_id,))
            self.assertEqual(document["document_type"], "VisaS56Request")
            self.assertEqual(
                len(db.all("SELECT * FROM student_documents WHERE student_id=?", (student_id,))),
                1,
            )
            audit = db.one(
                """SELECT * FROM audit_logs
                   WHERE action_type='update' AND module_name='visas' AND record_id=?
                   ORDER BY id DESC LIMIT 1""",
                (str(record_id),),
            )
            audit_payload = json.loads(audit["new_value"])
            self.assertEqual(
                {
                    "visa_document_id": audit_payload.get("visa_document_id"),
                    "visa_document_type_old": audit_payload.get("visa_document_type_old"),
                    "visa_document_type_new": audit_payload.get("visa_document_type_new"),
                    "visa_document_type_changed": audit_payload.get("visa_document_type_changed"),
                    "file_replaced": audit_payload.get("file_replaced"),
                },
                {
                    "visa_document_id": document_id,
                    "visa_document_type_old": "VisaGrantLetter",
                    "visa_document_type_new": "VisaS56Request",
                    "visa_document_type_changed": True,
                    "file_replaced": False,
                },
            )

            row_html, dialog_html = handler.visa_table_rows(student_id, [row])
            self.assertIn("S56 Request / S56 补料信", row_html)
            self.assertIn('<option value="s56_request" selected', dialog_html)

