            self.assertIs(app_module.db, db, msg=path_report)

            file_path = str(env["paths"]["storage_root"] / "invalid-type.pdf")
            record_id = db.execute(
                """INSERT INTO visas(
                   student_id,file_path,visa_type,visa_sector,visa_grant_date,visa_start_date,
                   visa_expiry_date,visa_conditions,visa_status,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (student_id, file_path, "Old Visa", "Schools Sector", "2026-06-02", "", "2031-03-15", "", "pending", "2026-06-02T12:00:00+10:00"),
            )
            document_id = db.execute(
                """INSERT INTO student_documents(
                   student_id,folder_category,document_type,original_name,stored_name,file_path,
                   version,file_size,uploaded_by,uploaded_at,document_status,is_active
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (student_id, "VISA", "VisaGrantLetter", "grant.pdf", "grant.pdf", file_path, 1, 128, None, "2026-06-02T12:00:00+10:00", "active", 1),
            )
            original_visa = dict(db.one("SELECT * FROM visas WHERE id=?", (record_id,)))
            original_document = dict(db.one("SELECT * FROM student_documents WHERE id=?", (document_id,)))
            success_audits_before = db.one(
                "SELECT COUNT(*) total FROM audit_logs WHERE action_type='update' AND module_name='visas'"
            )["total"]
            handler = self._upload_review_handler(
                env["admin"],
                form={
                    "visa_type": "Changed Visa",
                    "visa_sector": "Higher Education",
                    "visa_document_type": "forged_type",
                    "visa_grant_date": "03/06/2026",
                    "visa_start_date": "",
                    "visa_expiry_date": "16/03/2031",
                    "visa_conditions": "should not save",
                    "visa_status": "granted",
                },
            )
            handler.headers["Accept"] = "application/json"

            with mock.patch.object(app_module, "set_workflow_milestone") as set_milestone, \
                 mock.patch.object(app_module, "advance_workflow_stage_to") as advance_stage, \
                 mock.patch.object(app_module, "refresh_workflow_completion_metrics") as refresh_metrics:
                handler.visa_update("POST", student_id, str(record_id))

            updated_visa = dict(db.one("SELECT * FROM visas WHERE id=?", (record_id,)))
            updated_document = dict(db.one("SELECT * FROM student_documents WHERE id=?", (document_id,)))
            self.assertEqual(handler.response_status, 400)
            self.assertIn("请选择有效的 VISA 文件类型", json.loads(handler.wfile.getvalue())["error"])
            self.assertEqual(updated_visa, original_visa)
            self.assertEqual(updated_document, original_document)
            self.assertEqual(updated_visa["visa_type"], original_visa["visa_type"])
            self.assertEqual(updated_document["document_type"], "VisaGrantLetter")
            self.assertEqual(
                db.one("SELECT COUNT(*) total FROM audit_logs WHERE action_type='update' AND module_name='visas'")["total"],
                success_audits_before,
            )
            set_milestone.assert_not_called()
            advance_stage.assert_not_called()
            refresh_metrics.assert_not_called()

