    def test_visa_document_type_change_does_not_mutate_case_checklist_or_workflow(self):
        with isolated_upload_review_regression_environment("visa-update-business-boundary") as env:
            db = env["db"]
            student_id = env["student_id"]
            resolved_paths = env["resolved"]
            path_report = json.dumps(resolved_paths, ensure_ascii=False, sort_keys=True)

            self.assertEqual(Path(resolved_paths["database"]).resolve(), Path(db.path).resolve(), msg=path_report)
            self.assertEqual(Path(resolved_paths["storage"]).resolve(), env["paths"]["storage_root"].resolve(), msg=path_report)
            self.assertEqual(Path(resolved_paths["nas"]).resolve(), env["paths"]["nas_root"].resolve(), msg=path_report)
            self.assertIs(app_module.db, db, msg=path_report)

            stamp = "2026-06-02T12:00:00+10:00"
            file_path = str(env["paths"]["storage_root"] / "business-boundary.pdf")
            record_id = db.execute(
                """INSERT INTO visas(
                   student_id,file_path,visa_type,visa_sector,visa_grant_date,visa_start_date,
                   visa_expiry_date,visa_conditions,visa_status,created_at
                ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (student_id, file_path, "Old Visa", "Schools Sector", "2026-06-02", "", "2031-03-15", "", "pending", stamp),
            )
            document_id = db.execute(
                """INSERT INTO student_documents(
                   student_id,folder_category,document_type,original_name,stored_name,file_path,
                   version,file_size,uploaded_by,uploaded_at,document_status,is_active
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (student_id, "VISA", "VisaGrantLetter", "grant.pdf", "grant.pdf", file_path, 1, 128, None, stamp, "active", 1),
            )
            case_id = db.execute(
                """INSERT INTO visa_cases(
                   student_id,visa_type,application_type,status,result_status,created_at,updated_at
                ) VALUES(?,?,?,?,?,?,?)""",
                (student_id, "500 Student Visa", "Student Only", "Draft", "Pending", stamp, stamp),
            )
            checklist_id = db.execute(
                """INSERT INTO visa_checklist_items(
                   visa_case_id,item_key,title,status,required,created_at,updated_at
                ) VALUES(?,?,?,?,?,?,?)""",
                (case_id, "visa_result", "IMMI Grant Letter / IMMI Refusal Letter", "Missing", 1, stamp, stamp),
            )
            db.execute(
                """INSERT INTO visa_case_document_links(
                   visa_case_id,student_document_id,document_role,status,created_at,updated_at
                ) VALUES(?,?,?,?,?,?)""",
                (case_id, document_id, f"material_item:{checklist_id}", "Linked", stamp, stamp),
            )
            case_before = [dict(row) for row in db.all("SELECT * FROM visa_cases WHERE id=?", (case_id,))]
            checklist_before = [dict(row) for row in db.all("SELECT * FROM visa_checklist_items WHERE visa_case_id=?", (case_id,))]
            links_before = [dict(row) for row in db.all("SELECT * FROM visa_case_document_links WHERE visa_case_id=?", (case_id,))]
            handler = self._upload_review_handler(
                env["admin"],
                form={
                    "visa_type": "Old Visa",
                    "visa_sector": "Schools Sector",
                    "visa_document_type": "s56_request",
                    "visa_grant_date": "02/06/2026",
                    "visa_start_date": "",
                    "visa_expiry_date": "15/03/2031",
                    "visa_conditions": "",
                    "visa_status": "pending",
                },
            )

            with mock.patch.object(app_module, "set_workflow_milestone") as set_milestone, \
                 mock.patch.object(app_module, "advance_workflow_stage_to") as advance_stage, \
                 mock.patch.object(app_module, "refresh_workflow_completion_metrics") as refresh_metrics:
                handler.visa_update("POST", student_id, str(record_id))

            case_after = [dict(row) for row in db.all("SELECT * FROM visa_cases WHERE id=?", (case_id,))]
            checklist_after = [dict(row) for row in db.all("SELECT * FROM visa_checklist_items WHERE visa_case_id=?", (case_id,))]
            links_after = [dict(row) for row in db.all("SELECT * FROM visa_case_document_links WHERE visa_case_id=?", (case_id,))]
            self.assertEqual(case_after, case_before)
            self.assertEqual(checklist_after, checklist_before)
            self.assertEqual(links_after, links_before)
            set_milestone.assert_not_called()
            advance_stage.assert_called_once_with(student_id, "签证递交")
            refresh_metrics.assert_called_once_with(student_id, source="visa_updated")

