    def test_visa_create_blank_date_fields_fall_back_to_inferred_dates(self):
        class FakeNas:
            def status(self):
                return {"ready": True}

            def student_folder(self, student):
                return Path(student["folder_path"]).resolve()

            def category_folder(self, student, category):
                folder = self.student_folder(student) / category
                folder.mkdir(parents=True, exist_ok=True)
                return folder

        old_db = app_module.db
        old_nas = app_module.nas
        try:
            with tempfile.TemporaryDirectory() as folder:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas = FakeNas()
                student_folder = Path(folder) / "Visa Save Fallback"
                student_folder.mkdir()
                stamp = "2026-07-08T09:08:00+10:00"
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,current_status,
                       created_date,updated_at,form_data_json,folder_path,nas_status
                    ) VALUES(?,?,?,?,?,?,?,?,?)""",
                    ("TESTVISA3", "Fallback", "Visa", "签证递交", stamp, stamp, "{}", str(student_folder), "ready"),
                )
                db.execute("INSERT INTO workflow_status(student_id,current_stage) VALUES(?,?)", ("TESTVISA3", "签证递交"))
                install_synthetic_visa_lifecycle_schema(
                    db, "TESTVISA3", cycle_id=31, stamp=stamp
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.csrf = "token"
                handler.user = {"id": 1, "username": "admin", "display_name": "Admin", "role_name": "Admin"}
                handler.form = {
                    "visa_record_purpose": "existing_evidence",
                    "visa_type": "Student Visa Subclass 500",
                    "visa_sector": "",
                    "visa_grant_date": "",
                    "visa_start_date": "",
                    "visa_expiry_date": "",
                    "visa_conditions": "",
                    "visa_status": "",
                }
                text = """Visa grant notification
                Dear Anya SUN
                We have granted you a Student (subclass 500) visa on 01 July 2026.
                Application status
                Student (subclass 500): Granted
                Visa conditions
                8105 - Work limitation
                8202 - Meet course requirements
                8501 - Maintain health insurance
                Visa duration and travel
                Date of grant 01 July 2026
                Must not arrive after 15 March 2031
                Length of stay 15 March 2031
                Visa summary
                Visa Student (subclass 500)
                Sector Schools Sector
                """
                handler.files = [Upload("file", "Visa_500_Anya_SUN_V2.txt", "text/plain", text.encode("utf-8"))]
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {"User-Agent": "unit-test"}
                redirects = []
                handler.flash_redirect = lambda location, message, kind="success": redirects.append((location, message, kind))

                handler.visa_create("POST", "TESTVISA3")

                row = db.one("SELECT * FROM visas WHERE student_id=?", ("TESTVISA3",))
                self.assertIsNotNone(row)
                self.assertEqual(row["visa_status"], "granted")
                self.assertEqual(row["visa_sector"], "Schools Sector")
                self.assertEqual(row["visa_grant_date"], "2026-07-01")
                self.assertEqual(row["visa_start_date"], "2026-07-01")
                self.assertEqual(row["visa_expiry_date"], "2031-03-15")
                self.assertEqual(redirects[0][0], "/students/TESTVISA3?tab=visa")
        finally:
            app_module.db = old_db
            app_module.nas = old_nas

