    def test_workflow_stage_advances_one_step_only(self):
        old_db = app_module.db
        try:
            with tempfile.TemporaryDirectory() as folder:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                db.execute(
                    """INSERT INTO students(
                       student_id,passport_last_name,passport_first_name,created_date,updated_at,form_data_json
                    ) VALUES(?,?,?,?,?,?)""",
                    ("TEST001", "Student", "CRM", "2026-06-21T00:00:00", "2026-06-21T00:00:00", "{}"),
                )
                db.execute("INSERT INTO workflow_status(student_id,current_stage) VALUES(?,?)", ("TEST001", "建档"))
                app_module.set_workflow_stage("TEST001", "COE已出")
                self.assertEqual(db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", ("TEST001",))["current_stage"], "签约")
                self.assertEqual(db.one("SELECT current_status FROM students WHERE student_id=?", ("TEST001",))["current_status"], "签约")
                app_module.set_workflow_stage("TEST001", "签证递交")
                self.assertEqual(db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", ("TEST001",))["current_stage"], "申请材料审核")
                self.assertEqual(db.one("SELECT current_status FROM students WHERE student_id=?", ("TEST001",))["current_status"], "申请材料审核")
                app_module.set_workflow_stage("TEST001", "建档")
                self.assertEqual(db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", ("TEST001",))["current_stage"], "申请材料审核")
        finally:
            app_module.db = old_db

