    def test_master_layout_aaie_signature_and_stamp_stay_inside_left_cell(self):
        import pdfplumber

        old_signature = app_module.SONNY_SIGNATURE_PATH
        old_stamp = app_module.AAIE_COMPANY_STAMP_PATH
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                source = root / "master-parent-signed.pdf"
                final = root / "master-fully-executed.pdf"
                page_width, page_height = app_module.A4
                c = canvas.Canvas(str(source), pagesize=app_module.A4)
                c.setFont(app_module.reportlab_chinese_font(), 10)
                c.drawString(62.7, 520, "十一、签署")
                for y in (300.2, 479.2, 504.2):
                    c.line(62.7, y, 544.6, y)
                for x in (62.7, 303.6, 544.6):
                    c.line(x, 300.2, x, 504.2)
                c.drawString(68.7, 486, "AAIE / 甲方（签字 / 盖章）")
                c.drawString(309.6, 486, "委托方（乙方签字）")
                c.drawString(68.7, 460, "代理方（甲方盖章）：AAIE")
                c.drawString(68.7, 438, "授权代表：Sonny Zhang")
                c.drawString(68.7, 423, "甲方签署日期：")
                c.drawString(309.6, 438, "法定代理人或者监护人（名字）：")
                c.drawString(309.6, 407, "家长/乙方签署日期：")
                c.save()
                signature = root / "sonny_signature.png"
                stamp = root / "aaie_company_stamp.png"
                Image.new("RGBA", (240, 180), (20, 80, 180, 180)).save(signature)
                Image.new("RGBA", (160, 160), (200, 0, 0, 120)).save(stamp)
                app_module.SONNY_SIGNATURE_PATH = signature
                app_module.AAIE_COMPANY_STAMP_PATH = stamp

                with mock.patch.object(
                    app_module,
                    "contract_stamp_placement",
                    return_value={
                        "signature_page": "last", "signature_x": 220,
                        "signature_y": 250, "signature_width": 130,
                        "stamp_page": "last", "stamp_x": 260,
                        "stamp_y": 228, "stamp_width": 90,
                        "company_date_page": "last", "company_date_x": 185,
                        "company_date_y": 185, "company_date_font_size": 10,
                    },
                ):
                    app_module.apply_aaie_signature_and_stamp(
                        source, final, "2026年08月22日"
                    )

                with pdfplumber.open(str(final)) as pdf:
                    page = next(
                        value for value in pdf.pages
                        if "十一、签署" in (value.extract_text() or "")
                    )
                    aaie_word = max(
                        (
                            word for word in page.extract_words()
                            if word.get("text") == "AAIE"
                        ),
                        key=lambda word: float(word["top"]),
                    )
                    anchor_y = page.height - float(aaie_word["bottom"])
                    vertical = [
                        line for line in page.lines
                        if abs(float(line["x0"]) - float(line["x1"])) < 0.5
                        and float(line["y1"]) - float(line["y0"]) > 100
                        and float(line["y0"]) <= anchor_y <= float(line["y1"])
                    ]
                    left = min(vertical, key=lambda line: float(line["x0"]))
                    divider = min(
                        (line for line in vertical if float(line["x0"]) > page.width * 0.4),
                        key=lambda line: float(line["x0"]),
                    )
                    cell = {
                        "x0": float(left["x0"]),
                        "x1": float(divider["x0"]),
                        "y0": max(float(left["y0"]), float(divider["y0"])),
                        "y1": min(float(left["y1"]), float(divider["y1"])),
                    }
                    self.assertEqual(len(page.images), 2)
                    date_words = [
                        word for word in page.extract_words()
                        if "甲方签署日期" in str(word.get("text") or "")
                    ]
                    date_text_bottom = min(
                        page.height - float(word["bottom"])
                        for word in date_words
                    )
                    for image in page.images:
                        with self.subTest(image=image.get("name")):
                            self.assertGreaterEqual(float(image["x0"]), cell["x0"])
                            self.assertLessEqual(float(image["x1"]), cell["x1"])
                            self.assertGreaterEqual(float(image["y0"]), cell["y0"])
                            self.assertLessEqual(float(image["y1"]), cell["y1"])
                            self.assertLessEqual(
                                float(image["y1"]), date_text_bottom - 4
                            )
                    first, second = page.images
                    self.assertGreater(
                        min(float(first["x1"]), float(second["x1"]))
                        - max(float(first["x0"]), float(second["x0"])),
                        0,
                        "AAIE signature and stamp must preserve their overlapping composition",
                    )
                    self.assertGreater(
                        min(float(first["y1"]), float(second["y1"]))
                        - max(float(first["y0"]), float(second["y0"])),
                        0,
                        "AAIE signature and stamp must preserve their overlapping composition",
                    )
                    text = page.extract_text() or ""
                    self.assertIn(
                        "甲方签署日期：2026年08月22日", "".join(text.split())
                    )
                    self.assertIn("委托方（乙方签字）", text)
        finally:
            app_module.SONNY_SIGNATURE_PATH = old_signature
            app_module.AAIE_COMPANY_STAMP_PATH = old_stamp

