    def test_accommodation_and_allergies_required_only_without_parent_accompaniment(self):
        data = {name: "x" for name in (
            "passport_last_name", "passport_first_name", "gender", "date_of_birth", "current_year_level",
            "preferred_intake_year", "preferred_intake_term", "applying_year_level", "visa_status",
            "home_address", "home_postcode", "mobile_phone", "has_sibling_under_6", "photo_permission",
            "can_swim", "has_medical_or_psychological_history", "requires_long_term_medication",
            "has_violent_behavior_history", "has_suspension_or_expulsion_history",
            "student_australia_visa_refusal", "parents_australia_visa_refusal",
            "father_migration_application_status", "mother_migration_application_status",
            "current_school_name", "current_school_year_level", "has_aeas_or_idat", "has_ielts_or_toefl",
            "father_passport_last_name", "father_passport_first_name", "father_date_of_birth",
            "father_mobile", "father_email", "mother_passport_last_name", "mother_passport_first_name",
            "mother_date_of_birth", "mother_mobile", "mother_email", "smoke_allergy", "food_allergy",
            "pet_allergy", "medicine_allergy"
        )}
        data["preferred_cities"] = ["melbourne"]
        data["requires_parent_accompaniment"] = "是"
        data["accompanying_person_relationship"] = "母亲"
        self.assertNotIn("accommodation_preference", missing_student_fields(data))
        for allergy_field in ("smoke_allergy", "food_allergy", "pet_allergy", "medicine_allergy"):
            original = data.pop(allergy_field)
            self.assertNotIn(allergy_field, missing_student_fields(data))
            data[allergy_field] = original
        data["requires_parent_accompaniment"] = "否"
        self.assertIn("accommodation_preference", missing_student_fields(data))
        for allergy_field in ("smoke_allergy", "food_allergy", "pet_allergy", "medicine_allergy"):
            original = data.pop(allergy_field)
            self.assertIn(allergy_field, missing_student_fields(data))
            data[allergy_field] = original

        script = Path("assets/app.js").read_text(encoding="utf-8")
        self.assertIn('show(["smoke_allergy", "food_allergy", "food_allergy_notes", "pet_allergy", "pet_allergy_notes", "medicine_allergy", "medicine_allergy_notes"], !needsParent)', script)

