    def test_offer_upload_review_pdf_preview_uses_full_page_count(self):
        old_db = app_module.db
        old_upload_review_dir = app_module.UPLOAD_REVIEW_DIR
        old_preview_dir = app_module.PREVIEW_DIR
        old_pdf_page_count = app_module.pdf_page_count
        old_make_preview = app_module.make_preview
        old_can_review = app_module.can_review_module_action
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                app_module.db = Database(root / "aaie_crm.db")
                app_module.db.initialize()
                app_module.UPLOAD_REVIEW_DIR = root / "upload_staging"
                app_module.PREVIEW_DIR = root / "previews"
                user = {"id": 1, "username": "admin", "role": "admin"}
                stamp = "2026-07-07T12:00:00+10:00"
                app_module.db.execute("INSERT OR IGNORE INTO roles(id,name,permissions_json) VALUES(1,'Admin','{}')")
                app_module.db.execute(
                    """INSERT OR IGNORE INTO users(id,username,display_name,password_hash,role_id,created_at)
                       VALUES(1,'admin','Admin','hash',1,?)""",
                    (stamp,),
                )
                app_module.db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("TOFFERPAGES", "Sun", "Anya", "New", stamp, stamp, "{}"),
                )
                token = app_module.create_upload_review(
                    "TOFFERPAGES",
                    "Offer",
                    [Upload("files", "Signed Offer Letter-Anya Sun.pdf", "application/pdf", b"%PDF-1.4\nfake")],
                    user,
                    {},
                )

                def fake_pdf_page_count(_data, max_pages=app_module.PREVIEW_MAX_PDF_PAGES):
                    total = 9
                    return total if max_pages is None else min(max_pages, total)

                captured = {}

                def fake_make_preview(document_id_arg, filename, data=None, content_type="", size="thumb", page=1, error_collector=None, **_kwargs):
                    captured["page"] = page
                    target = app_module.preview_target(document_id_arg, size, page)
                    target.parent.mkdir(parents=True, exist_ok=True)
                    Image.new("RGB", (20, 20), "white").save(target)
                    return str(target)

                app_module.pdf_page_count = fake_pdf_page_count
                app_module.make_preview = fake_make_preview
                app_module.can_review_module_action = lambda _user, _module, _action="view": True
                handler = object.__new__(app_module.CRMHandler)
                handler.user = user
                handler.query = {"size": ["large"], "page": ["9"]}
                handler.send_response = lambda status: setattr(handler, "response_status", status)
                handler.headers_sent = []
                handler.send_header = lambda key, value: handler.headers_sent.append((key, value))
                handler.end_headers = lambda: None
                handler.wfile = io.BytesIO()

                handler.upload_review_preview("GET", "TOFFERPAGES", token, "0")

                headers = dict(handler.headers_sent)
                self.assertEqual(handler.response_status, 200)
                self.assertEqual(headers["X-Preview-Page"], "9")
                self.assertEqual(headers["X-Preview-Page-Count"], "9")
                self.assertEqual(captured["page"], 9)
        finally:
            app_module.db = old_db
            app_module.UPLOAD_REVIEW_DIR = old_upload_review_dir
            app_module.PREVIEW_DIR = old_preview_dir
            app_module.pdf_page_count = old_pdf_page_count
            app_module.make_preview = old_make_preview
            app_module.can_review_module_action = old_can_review

