    def test_make_preview_creates_png(self):
        target = PREVIEW_DIR / "999999_thumb.png"
        if target.exists():
            target.unlink()
        preview = Path(make_preview(999999, "Preview_Test.pdf"))
        try:
            self.assertTrue(preview.exists())
            self.assertEqual(preview.suffix, ".png")
            self.assertGreater(preview.stat().st_size, 0)
        finally:
            if preview.exists():
                preview.unlink()

    def test_make_preview_renders_pdf_first_page(self):
        from reportlab.lib.pagesizes import A4
        from reportlab.pdfgen import canvas

        targets = [PREVIEW_DIR / "999998_thumb_p1.png", PREVIEW_DIR / "999998_thumb_p2.png"]
        for target in targets:
            if target.exists():
                target.unlink()
        buffer = io.BytesIO()
        pdf = canvas.Canvas(buffer, pagesize=A4)
        pdf.drawString(72, 760, "FIRST PAGE")
        pdf.showPage()
        pdf.drawString(72, 760, "SECOND PAGE")
        pdf.save()
        preview = Path(make_preview(999998, "Two_Page_Test.pdf", buffer.getvalue(), "application/pdf"))
        preview_page_2 = Path(make_preview(999998, "Two_Page_Test.pdf", buffer.getvalue(), "application/pdf", page=2))
        try:
            self.assertTrue(preview.exists())
            self.assertTrue(preview_page_2.exists())
            self.assertEqual(preview.name, "999998_thumb_p1.png")
            self.assertEqual(preview_page_2.name, "999998_thumb_p2.png")
            self.assertGreater(preview.stat().st_size, 0)
            self.assertGreater(preview_page_2.stat().st_size, 0)
        finally:
            for target in (preview, preview_page_2):
                if target.exists():
                    target.unlink()

