    def test_parse_australian_date_defaults_to_day_month_year_and_flags_ambiguous(self):
        parsed = app_module.parseAustralianDate("05/06/2026")
        self.assertEqual(parsed["normalized_date"], "2026-06-05")
        self.assertEqual(parsed["display_date_au"], "05/06/2026")
        self.assertEqual(parsed["date_format_detected"], "DD/MM/YYYY")
        self.assertTrue(parsed["ambiguous_date"])

        parsed = app_module.parseAustralianDate("13/06/2026")
        self.assertEqual(parsed["normalized_date"], "2026-06-13")
        self.assertEqual(parsed["display_date_au"], "13/06/2026")
        self.assertFalse(parsed["ambiguous_date"])

        parsed = app_module.parseAustralianDate("1 January 2026")
        self.assertEqual(parsed["normalized_date"], "2026-01-01")
        self.assertEqual(parsed["display_date_au"], "01/01/2026")

