    def test_coe_panel_displays_application_dates_in_au_format(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                db.execute(
                    "INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json) VALUES(?,?,?,?,?,?,?)",
                    ("S1", "Zhang", "Wei", "active", "2026-06-30", "2026-06-30T13:50:00", "{}"),
                )
                db.execute(
                    """INSERT INTO coe_oshc(student_id,document_kind,school_name,coe_start_date,coe_end_date,
                       caaw_welfare_start_date,caaw_welfare_end_date,oshc_commencement_date,oshc_expiry_date,created_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ("S1", "COE_CAAW", "Test College", "2026-07-13", "2029-12-21", "2026-07-06", "2029-12-21", "", "", "2026-06-30T13:50:00"),
                )
                records = db.all("SELECT * FROM coe_oshc WHERE student_id=?", ("S1",))
                handler = object.__new__(app_module.CRMHandler)
                handler.csrf = "token"
                html = handler.coe_panel("S1", records)
            finally:
                app_module.db = old_db

        self.assertIn('value="13/07/2026"', html)
        self.assertIn('value="06/07/2026"', html)
        self.assertNotIn('value="2026-07-13"', html)
        self.assertEqual(app_module.coe_date_form_value({"coe_start_date": "13/07/2026"}, "coe_start_date", {}), "2026-07-13")

