    def test_contract_guardian_passport_name_display_handles_missing_name_parts(self):
        cases = (
            ({"father_passport_last_name": "Chen", "father_passport_first_name": ""}, "父亲", "Chen"),
            ({"mother_passport_last_name": "", "mother_passport_first_name": "Hongjuan"}, "母亲", "Hongjuan"),
            ({"father_passport_last_name": "", "father_passport_first_name": ""}, "父亲", ""),
            ({"mother_passport_last_name": "", "mother_passport_first_name": ""}, "母亲", ""),
        )
        for parent_fields, relationship, expected in cases:
            with self.subTest(relationship=relationship, parent_fields=parent_fields):
                old_db = app_module.db
                try:
                    with tempfile.TemporaryDirectory() as folder:
                        db = Database(Path(folder) / "aaie_crm.db")
                        db.initialize()
                        app_module.db = db
                        stamp = "2026-07-15T11:05:00+10:00"
                        values = {
                            "father_passport_last_name": "",
                            "father_passport_first_name": "",
                            "mother_passport_last_name": "",
                            "mother_passport_first_name": "",
                            **parent_fields,
                        }
                        db.execute(
                            """INSERT INTO students(
                               student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,form_data_json
                            ) VALUES(?,?,?,?,?,?,?)""",
                            (
                                "TGUARD002", "Student", "Guardian", "Active", stamp, stamp, json.dumps(values, ensure_ascii=False),
                            ),
                        )
                        handler = object.__new__(app_module.CRMHandler)
                        handler.user = {"id": 1, "username": "admin", "role_name": "Admin", "permissions_json": json.dumps(["*"])}
                        handler.csrf = "token"
                        student = db.one("SELECT * FROM students WHERE student_id=?", ("TGUARD002",))

                        html = handler.contract_panel(student, [], [])

                        attribute = "data-father-guardian-name" if relationship == "父亲" else "data-mother-guardian-name"
                        self.assertIn(f'{attribute}="{expected}"', html)
                finally:
                    app_module.db = old_db

    def test_unsigned_contract_rows_allow_revision_without_manual_sent_status(self):
        app = Path("app.py").read_text(encoding="utf-8")
        student_contract_panel = app.split(
            "def contract_panel(self, student, contracts, refund_templates):", 1
        )[1].split("\n    def upload_review", 1)[0]
        student_revision_block = student_contract_panel.split("if can_revise_contract(self.user):", 1)[1].split(
            "if can_apply_aaie_stamp", 1
        )[0]
        contract_center_table = app.split("def contract_center_table(self, title, status=None):", 1)[1].split(
            "\n    def render_contract_revision_page", 1
        )[0]
        center_revision_block = contract_center_table.split("if can_revise_contract(self.user):", 1)[1].split(
            "common_tail = (", 1
        )[0]

        self.assertNotIn("标记已发送", student_contract_panel)
        self.assertNotIn('contract_status" value="Sent"', student_revision_block)
        self.assertIn('if normalized_status in {"Draft", "Active", "Sent"}:', student_revision_block)
        self.assertIn('if normalized_status in {"Draft", "Active", "Sent"}:', center_revision_block)
        self.assertIn("已签署合同不可直接改", student_revision_block)
        self.assertIn("已签署合同不可直接改", center_revision_block)

