    def test_contract_signing_links_legacy_schema_adds_column_without_backfill(self):
        with tempfile.TemporaryDirectory() as folder:
            db_path = Path(folder) / "aaie_crm.db"
            conn = sqlite3.connect(db_path)
            try:
                conn.executescript(
                    """
                    CREATE TABLE contract_signing_links (
                      id INTEGER PRIMARY KEY, contract_id INTEGER NOT NULL,
                      student_id TEXT, token_hash TEXT NOT NULL UNIQUE,
                      token_last_4 TEXT NOT NULL, signing_url TEXT NOT NULL,
                      status TEXT NOT NULL DEFAULT 'active', expires_at TEXT NOT NULL,
                      created_by_user_id INTEGER, created_by_name TEXT, created_at TEXT NOT NULL,
                      first_viewed_at TEXT, last_viewed_at TEXT, viewed_count INTEGER NOT NULL DEFAULT 0,
                      invalidated_at TEXT, invalidated_reason TEXT, signed_at TEXT,
                      signed_signature_id INTEGER, bound_wechat_openid TEXT,
                      bound_wechat_unionid TEXT, bound_wechat_nickname TEXT,
                      bound_wechat_avatar_url TEXT, bound_wechat_at TEXT, last_login_at TEXT
                    );
                    INSERT INTO contract_signing_links(
                      id,contract_id,student_id,token_hash,token_last_4,signing_url,status,expires_at,created_at
                    ) VALUES(1,18,'20260036','legacyhash','hash','https://form.goabroad.com.au/contract-sign/test','active','2026-07-10T00:00:00+10:00','2026-07-03T23:00:00+10:00');
                    """
                )
                conn.commit()
            finally:
                conn.close()

            db = Database(db_path)
            db.initialize()

            columns = {row["name"] for row in db.all("PRAGMA table_info(contract_signing_links)")}
            self.assertIn("updated_at", columns)
            row = db.one("SELECT updated_at FROM contract_signing_links WHERE id=1")
            self.assertIsNone(row["updated_at"])

