    def test_contract_signature_archives_signed_contract_and_confirmation_page(self):
        old_db = app_module.db
        old_nas = app_module.nas
        old_dir = app_module.CONTRACT_SIGNING_DIR
        old_signature = app_module.SONNY_SIGNATURE_PATH
        old_stamp = app_module.AAIE_COMPANY_STAMP_PATH

        class FakeNas:
            def __init__(self):
                self.readable_paths = []

