    def test_study_contract_cover_draws_chinese_title_lines_in_requested_visual_order(self):
        import student_doc
        from unittest.mock import patch

        text_calls = []

        class RecordingDraw:
            def __init__(self, image, mode=None):
                pass

            def text(self, xy, text, font=None, fill=None):
                text_calls.append((text, xy))

            def textlength(self, text, font=None):
                return len(str(text)) * 10

            def line(self, *args, **kwargs):
                pass

            def polygon(self, *args, **kwargs):
                pass

            def rectangle(self, *args, **kwargs):
                pass

            def rounded_rectangle(self, *args, **kwargs):
                pass

        with patch.object(student_doc.ImageDraw, "Draw", RecordingDraw):
            student_doc.study_contract_cover_image({
                "contract_uid": "CONTRACT-COVER-ORDER-001",
                "contract_date": "2026-07-06",
                "service_type": "留学咨询及签证服务",
                "student_full_name": "Cover Order Student",
            }, pixel_width=420)

        title_positions = {text: xy[1] for text, xy in text_calls if text in {"澳洲留学咨询及", "签证服务委托合同"}}

        self.assertIn("澳洲留学咨询及", title_positions)
        self.assertIn("签证服务委托合同", title_positions)
        self.assertLess(title_positions["澳洲留学咨询及"], title_positions["签证服务委托合同"])

