    def test_active_study_contract_template_replaces_variables_inside_tables(self):
        old_db = app_module.db
        old_template_dir = app_module.TEMPLATE_DIR
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                app_module.TEMPLATE_DIR = root
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                template = root / "active_template.docx"
                doc = Document()
                doc.add_paragraph("合同编号：{{contract_uid}}")
                table = doc.add_table(rows=2, cols=2)
                table.cell(0, 0).text = "甲方"
                table.cell(0, 1).text = "{{company_legal_name}} / {{company_abn_acn}}"
                table.cell(1, 0).text = "乙方"
                table.cell(1, 1).text = "{{parent_signer_name}} / {{student_full_name}}"
                doc.save(template)
                db.execute(
                    """INSERT INTO template_records(template_key,template_name,template_category,contract_type,file_path,
                       version,is_active,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    ("StudyAbroadContract-test", "Active test", "Contract", "StudyAbroadContract", str(template), 7, 1, "2026-07-04", "2026-07-04"),
                )
                target = root / "rendered.docx"
                rendered = app_module.render_study_contract_from_active_template({
                    "contract_uid": "AAIE-TPL-001",
                    "contract_date": "2026-07-04",
                    "company_legal_name": "AAIE Group Pty Ltd",
                    "company_abn_acn": "ABN 11 222 333 444",
                    "parent_signer_name": "Jane Parent",
                    "parent_phone": "+61 400 000 000",
                    "student_full_name": "Alex Student",
                    "service_scope_items": ["澳洲留学规划咨询"],
                    "final_fee_amount": "3200",
                }, target)
                self.assertEqual(rendered, target)
                out = Document(str(target))
                text = "\n".join(
                    [p.text for p in out.paragraphs]
                    + [p.text for table in out.tables for row in table.rows for cell in row.cells for p in cell.paragraphs]
                )
                self.assertIn("AAIE-TPL-001", text)
                self.assertIn("AAIE Group Pty Ltd / ABN 11 222 333 444", text)
                self.assertIn("Jane Parent / Alex Student", text)
                self.assertNotIn("{{", text)
        finally:
            app_module.db = old_db
            app_module.TEMPLATE_DIR = old_template_dir

