    def test_study_contract_docx_embeds_cover_image_relationship(self):
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            docx_path = root / "contract.docx"
            generate_study_abroad_contract({
                "contract_title": STUDY_CONTRACT_TITLE,
                "contract_uid": "CONTRACT-EMBED-COVER-001",
                "contract_date": "2026-07-07",
                "company_legal_name": "AAIE Group Pty Ltd",
                "company_trading_name": "AAIE",
                "company_abn_acn": "ABN 11 222 333 444",
                "company_authorised_person": "AAIE",
                "parent_signer_name": "Test Parent",
                "parent_signer_relationship": "母亲",
                "parent_phone": "0400000000",
                "parent_email": "parent@example.com",
                "student_full_name": "Embedded Cover Student",
                "student_date_of_birth": "2012-01-01",
                "student_id_or_passport_number": "P1234567",
                "student_current_year_level": "Year 8",
                "service_scope_items": ["澳洲留学规划咨询"],
                "service_type": "留学咨询及签证服务",
                "service_fee_currency": "澳洲公户",
                "consulting_and_visa_service_fee": "2400",
                "final_fee_amount": "2400",
                "refund_policy_text": "退款规则测试。",
            }, docx_path)

            with zipfile.ZipFile(docx_path) as archive:
                names = archive.namelist()
                media = [name for name in names if name.startswith("word/media/")]
                rels = archive.read("word/_rels/document.xml.rels").decode("utf-8")
                document_xml = archive.read("word/document.xml").decode("utf-8")

            self.assertTrue(media)
            self.assertRegex(rels, r'Type="[^"]*/image"')
            self.assertNotIn('TargetMode="External"', rels)
            image_rids = re.findall(r'<Relationship Id="([^"]+)"[^>]+Type="[^"]*/image"[^>]+>', rels)
            self.assertTrue(any(f'r:embed="{rid}"' in document_xml for rid in image_rids))
            self.assertNotIn("r:link=", document_xml)

    def test_contract_docx_document_preview_renders_pdf_full_page_count(self):
        class FakeNas:
            def student_folder(self, student):
                return Path(student["folder_path"]).resolve()

        old_db = app_module.db
        old_nas = app_module.nas
        old_preview_dir = app_module.PREVIEW_DIR
        old_convert = app_module.convert_docx_to_pdf_lossless
        old_preview_pdf_page_count = app_module.preview_pdf_page_count
        old_make_preview = app_module.make_preview
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas = FakeNas()
                app_module.PREVIEW_DIR = root / "previews"
                stamp = "2026-07-07T12:00:00+10:00"
                student_folder = root / "Bb Ss"
                forms = student_folder / "Forms"
                forms.mkdir(parents=True)
                docx_path = forms / "StudyAbroadContractRevision_20260707_V10.docx"
                document = Document()
                document.add_paragraph("Cover placeholder")
                document.add_page_break()
                document.add_paragraph("一、合同双方")
                document.save(docx_path)
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,created_date,updated_at,folder_path,form_data_json)
                       VALUES(?,?,?,?,?,?,?,?)""",
                    ("TPREVIEWDOCX", "Ss", "Bb", "Active", stamp, stamp, str(student_folder), "{}"),
                )
                document_id = db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,file_path,version,file_size,uploaded_at,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "TPREVIEWDOCX", "Forms", "StudyAbroadContractRevision",
                        docx_path.name, docx_path.name, str(docx_path), 10, docx_path.stat().st_size, stamp, 1,
                    ),
                )
                captured = {}

                def fake_convert(source, target):
                    captured["converted_source"] = Path(source)
                    Path(target).write_bytes(b"%PDF converted contract docx")
                    return Path(target)

                def fake_preview_pdf_page_count(data, document=None, filename=""):
                    captured["page_count_data"] = data
                    captured["page_count_filename"] = filename
                    return 6

                def fake_make_preview(document_id_arg, filename, data=None, content_type="", size="thumb", page=1, error_collector=None, **_kwargs):
                    captured["filename"] = filename
                    captured["data"] = data
                    captured["content_type"] = content_type
                    captured["size"] = size
                    captured["page"] = page
                    target = app_module.preview_target(document_id_arg, size, page)
                    target.parent.mkdir(parents=True, exist_ok=True)
                    Image.new("RGB", (20, 20), "white").save(target)
                    return str(target)

                app_module.convert_docx_to_pdf_lossless = fake_convert
                app_module.preview_pdf_page_count = fake_preview_pdf_page_count
                app_module.make_preview = fake_make_preview
                handler = object.__new__(app_module.CRMHandler)
                handler.query = {"size": ["large"], "page": ["1"]}
                handler.require = lambda permission: True
                handler.send_response = lambda status: setattr(handler, "response_status", status)
                handler.headers_sent = []
                handler.send_header = lambda key, value: handler.headers_sent.append((key, value))
                handler.end_headers = lambda: None
                handler.wfile = io.BytesIO()
                handler.user = {"id": 1, "username": "admin"}

                handler.document_preview("GET", str(document_id))

                headers = dict(handler.headers_sent)
                self.assertEqual(captured["converted_source"], docx_path.resolve())
                self.assertEqual(captured["filename"], "StudyAbroadContractRevision_20260707_V10.pdf")
                self.assertEqual(captured["data"], b"%PDF converted contract docx")
                self.assertEqual(captured["content_type"], "application/pdf")
                self.assertEqual(headers["X-Preview-Page-Count"], "6")
                self.assertEqual(handler.response_status, 200)
        finally:
            app_module.db = old_db
            app_module.nas = old_nas
            app_module.PREVIEW_DIR = old_preview_dir
            app_module.convert_docx_to_pdf_lossless = old_convert
            app_module.preview_pdf_page_count = old_preview_pdf_page_count
            app_module.make_preview = old_make_preview

