    def test_generated_contract_uses_discounted_final_fee(self):
        with tempfile.TemporaryDirectory() as folder:
            target = Path(folder) / "discounted_contract.docx"
            generate_study_abroad_contract({
                "contract_title": STUDY_CONTRACT_TITLE,
                "contract_uid": "AAIE-20260714-DISCOUNT",
                "contract_date": "2026-07-14",
                "company_legal_name": "AAIE Group Pty Ltd",
                "company_trading_name": "AAIE Education",
                "company_abn_acn": "ABN 11 222 333 444",
                "company_authorised_person": "AAIE",
                "parent_signer_name": "Test Parent",
                "parent_signer_relationship": "父亲",
                "student_full_name": "Discount Student",
                "student_date_of_birth": "2012-01-01",
                "student_id_or_passport_number": "P7654321",
                "student_current_year_level": "Year 8",
                "service_scope_items": ["澳洲留学规划咨询"],
                "service_type": "留学咨询及签证服务",
                "service_fee_currency": "微信",
                "consulting_and_visa_service_fee": "2400",
                "discount_amount": "200",
                "final_fee_amount": "2200",
                "refund_policy_text": "退款规则测试。",
            }, target)
            doc = Document(str(target))
            chunks = [p.text for p in doc.paragraphs]
            for table in doc.tables:
                for row in table.rows:
                    for cell in row.cells:
                        chunks.extend(p.text for p in cell.paragraphs)
            text = "\n".join(chunks)
            self.assertIn("服务费", text)
            self.assertIn("2400澳币", text)
            self.assertIn("最终费用", text)
            self.assertIn("2200澳币", text)

