    def test_xiaohongshu_content_extraction_progress_payload_marks_terminal_statuses(self):
        running = app_module.content_extraction_progress_payload({"process_status": "转写中"})
        self.assertFalse(running["done"])
        self.assertGreater(running["progress"]["percent"] if "progress" in running else running["percent"], 0)

        completed = app_module.content_extraction_progress_payload({"process_status": "已完成"})
        self.assertTrue(completed["done"])
        self.assertEqual(completed["percent"], 100)
        self.assertEqual(completed["steps"][-1]["state"], "done")

        needs_upload = app_module.content_extraction_progress_payload({"process_status": "需要上传文件"})
        self.assertTrue(needs_upload["done"])
        self.assertEqual(needs_upload["steps"][-1]["state"], "warning")

        latest = app_module.content_extraction_progress_payload({
            "source_type": "v2", "process_status": "OCR中",
        })
        self.assertEqual(
            [step["label"] for step in latest["steps"]],
            ["下载视频", "识别字幕和语音", "合并识别结果", "检查疑点", "生成文案"],
        )
        self.assertTrue(next(step for step in latest["steps"] if step["key"] == "recognize")["active"])

    def test_xiaohongshu_image_ocr_prefers_macos_vision_before_paddleocr(self):
        old_ocr = app_module.ocr_image_text
        old_paddle = app_module.run_paddle_ocr_on_image
        calls = []
        try:
            app_module.ocr_image_text = lambda data, suffix=".png": calls.append("vision") or "Vision OCR text"
            app_module.run_paddle_ocr_on_image = lambda image_path: calls.append("paddle") or ("Paddle OCR text", "")

            with tempfile.NamedTemporaryFile(suffix=".jpg") as image_file:
                image_file.write(b"fake-image-bytes")
                image_file.flush()
                text, error = app_module.content_extract_image_ocr(Path(image_file.name))

            self.assertEqual(text, "Vision OCR text")
            self.assertEqual(error, "")
            self.assertEqual(calls, ["vision"])
        finally:
            app_module.ocr_image_text = old_ocr
            app_module.run_paddle_ocr_on_image = old_paddle

    def test_xiaohongshu_recovers_interrupted_processing_jobs_on_startup(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                job_id = db.execute(
                    """INSERT INTO content_extraction_jobs(source_platform,content_type,process_status,status,error_message,
                       created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?)""",
                    (
                        "Xiaohongshu",
                        "image",
                        "OCR中",
                        "已提取",
                        "",
                        "2026-06-27T17:00:00+10:00",
                        "2026-06-27T17:00:00+10:00",
                    ),
                )

                changed = app_module.recover_interrupted_content_extraction_jobs(now_text="2026-06-27T17:30:00+10:00")

                self.assertEqual(changed, 1)
                row = db.one("SELECT process_status,error_message FROM content_extraction_jobs WHERE id=?", (job_id,))
                self.assertEqual(row["process_status"], "失败")
                self.assertIn("上次处理被中断", row["error_message"])
                self.assertIn("重新识别", row["error_message"])
            finally:
                app_module.db = old_db

    def test_xiaohongshu_content_extraction_analysis_generates_fage_script(self):
        merged = app_module.merge_content_extraction_text({
            "note_title": "澳洲低龄留学怎么选学校",
            "note_text": "家长不要只看排名，还要看孩子年级、英文和签证规划。",
            "video_transcript": "590陪读签证和住宿安排要一起看。",
            "ocr_text": "公校 私校 VCE",
            "pasted_text": "K-12申请要提前准备材料。",
        })
        self.assertIn("【标题】", merged["merged_original_text"])
        self.assertIn("590陪读签证", merged["merged_original_text"])

        analysis = app_module.analyze_content_extraction_text(merged["cleaned_text"])
        self.assertIn("澳洲", analysis["final_script"])
        self.assertIn("590", analysis["final_script"])
        self.assertIn("hook_analysis", analysis)
        tags = json.loads(analysis["topic_tags"])
        self.assertIn("590陪读签证", tags)

    def test_xiaohongshu_content_extraction_analysis_follows_adaptation_story(self):
        merged = app_module.merge_content_extraction_text({
            "note_title": "14岁出国读美高，低龄留学生的孤独能懂吗？",
            "note_text": (
                "14岁，一个本该无忧无虑的年纪，我学会了怎么一个人熬夜崩溃。"
                "刚来美高那阵，我一句玩笑都听不懂，同学聊天我只能尴尬地笑。"
                "生病了不敢请假，想家了只能翻相册。"
                "有一次在洗衣房听见隔壁在放周杰伦，忍不住眼泪掉下来。"
                "你知道低龄留学最难的是什么吗？不是英语，也不是GPA，"
                "而是你必须比别人更早面对没人懂我的时刻。"
                "后来我开始主动搭话，习惯一个人吃饭，也学会在presentation里自信发言。"
                "#低龄留学 #美高生活 #文化冲击 #语言障碍 #孤独成长"
            ),
        })

        analysis = app_module.analyze_content_extraction_text(merged["cleaned_text"])

        self.assertIn("14岁", analysis["hook"])
        self.assertNotEqual(analysis["hook"], "【标题】")
        self.assertIn("孤独", analysis["pain_points"])
        self.assertIn("听不懂", analysis["pain_points"])
        self.assertIn("文化", analysis["main_topic"])
        self.assertIn("孤独", analysis["final_script"])
        self.assertIn("听不懂", analysis["final_script"])
        self.assertNotIn("先别急着问哪所学校好", analysis["final_script"])

