        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-06-27T12:00:00"
                job_id = db.execute(
                    """INSERT INTO content_extraction_jobs(source_platform,source_url,content_type,note_title,merged_text,
                       merged_original_text,cleaned_text,hook,pain_points,content_structure,viral_reason,rewrite_direction,
                       rewritten_titles,rewritten_script,rewritten_hook,suggested_tags,key_message,final_script,status,
                       process_status,created_by,updated_by,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "Xiaohongshu", "https://www.xiaohongshu.com/test", "text", "原始标题",
                        "原始文案", "原始文案", "清洗文案", "原始钩子", "家长痛点",
                        "痛点-冲突-拆解-行动", "有明确痛点", "迁移到590陪读签证",
                        json.dumps(["标题1", "标题2"], ensure_ascii=False),
                        "确认前改写稿：590陪读签证和学校选择要一起看。",
                        "改写钩子", json.dumps(["澳洲低龄留学", "590陪读签证"], ensure_ascii=False),
                        "先做规划", "确认前改写稿：590陪读签证和学校选择要一起看。",
                        "待确认", "已完成", 1, 1, stamp, stamp,
                    ),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "role_name": "Admin"}
                handler.form = {
                    "confirmed_title": "确认标题",
                    "confirmed_hook": "确认钩子",
                    "confirmed_script": "确认后的口播稿",
                    "confirmed_tags": "澳洲低龄留学，590陪读签证",
                    "category": "澳洲低龄留学",
                    "planned_recording_date": "2026-06-28",
                    "planned_publish_date": "2026-06-29",
                }
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "unit-test"}
                handler.flash_redirect = lambda location, message, kind="success": (location, message, kind)

                location, message, kind = handler.content_extraction_confirm_library("POST", job_id)

                self.assertEqual(kind, "success")
                self.assertIn("/content/scripts/", location)
                self.assertIn("待录制", message)
                job = db.one("SELECT * FROM content_extraction_jobs WHERE id=?", (job_id,))
                script = db.one("SELECT * FROM content_scripts WHERE id=?", (job["created_script_id"],))
                self.assertEqual(job["status"], "待录制")
                self.assertEqual(job["is_in_script_library"], 1)
                self.assertEqual(script["status"], "PendingRecording")
                self.assertEqual(script["body"], "确认后的口播稿")
                self.assertEqual(script["planned_recording_date"], "2026-06-28")
            finally:
                app_module.db = old_db

