    def test_xiaohongshu_public_adapter_extracts_public_video_url_from_page_json(self):
        old_urlopen = app_module.urllib.request.urlopen

        class FakeResponse:
            headers = {"Content-Type": "text/html; charset=utf-8"}

            def __enter__(self):
                return self

            def __exit__(self, *_args):
                return False

            def geturl(self):
                return "https://www.xiaohongshu.com/discovery/item/video?type=video"

            def read(self, _limit):
                return (
                    b'<html><head><title>AI content system</title>'
                    b'<meta name="description" content="note body"></head>'
                    b'<script>window.__INITIAL_STATE__={"videoUrl":"https:\\\\/\\\\/cdn.example.test\\\\/clip.mp4","nickname":"Fage"}</script>'
                    b"</html>"
                )

        try:
            app_module.urllib.request.urlopen = lambda _request, timeout=8: FakeResponse()

            parsed = app_module.xiaohongshu_public_adapter("https://www.xiaohongshu.com/discovery/item/video?type=video")

            self.assertTrue(parsed["ok"])
            self.assertEqual(parsed["video_url"], "https://cdn.example.test/clip.mp4")
        finally:
            app_module.urllib.request.urlopen = old_urlopen

