    def test_google_drive_expired_token_refresh_and_401_retry_guard(self):
        app = Path("app.py").read_text(encoding="utf-8")
        auth_block = app[app.index("def google_drive_auth_config"):app.index("def google_drive_request")]
        request_block = app[app.index("def google_drive_request"):app.index("def google_drive_list_children")]
        self.assertIn("google_drive_token_is_expired", auth_block)
        self.assertIn("GOOGLE_DRIVE_TOKEN_EXPIRY_SETTING", auth_block)
        self.assertIn("google_drive_refresh_access_token", auth_block)
        self.assertIn("exc.code == 401", request_block)
        self.assertIn("google_drive_auth_error_message", request_block)
        self.assertIn("Reconnect Required", request_block)
        self.assertTrue(app_module.google_drive_token_is_expired(""))
        self.assertTrue(app_module.google_drive_token_is_expired((datetime.now().astimezone() - timedelta(minutes=1)).isoformat()))
        self.assertFalse(app_module.google_drive_token_is_expired((datetime.now().astimezone() + timedelta(hours=2)).isoformat()))

    def test_reminders_page_reuses_rows_and_does_not_repeat_engine(self):
        app = Path("app.py").read_text(encoding="utf-8")
        helper_block = app[app.index("def reminder_rows_for_user"):app.index("def reminder_card_html")]
        page_block = app[app.index("def reminders(self, method)"):app.index("def reminder_action")]

        self.assertIn("def reminder_query_rows", app)
        self.assertNotIn("run_reminder_engine()", helper_block)
        self.assertIn("run_reminder_engine_if_due()", page_block)
        self.assertIn("base_rows = self.reminder_query_rows()", page_block)
        self.assertIn("rows = self.reminder_rows_for_user(tab, base_rows)", page_block)
        self.assertIn("self.reminder_rows_for_user(key, base_rows)", page_block)
        self.assertIn('self.reminder_rows_for_user("today", base_rows)', page_block)

