    def test_student_management_ignores_card_view_query_and_renders_table_only(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-08T11:20:00"
                db.execute(
                    """INSERT INTO students(student_id,passport_first_name,passport_last_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("260099", "Table", "Only", "Active", stamp, stamp, "{}"),
                )
                db.execute(
                    "INSERT INTO workflow_status(student_id,current_stage,materials_checked) VALUES(?,?,?)",
                    ("260099", "建档", 0),
                )
                db.execute("ALTER TABLE offers ADD COLUMN course_start_date TEXT")
                db.execute(
                    "UPDATE students SET applying_year_level=? WHERE student_id=?",
                    ("Year 8", "260099"),
                )
                final_offer_id = db.execute(
                    """INSERT INTO offers(student_id,school_name,offer_status,created_at,course_start_date)
                       VALUES(?,?,?,?,?)""",
                    ("260099", "Final College", "Received", stamp, "2027-02-01"),
                )
                db.execute(
                    """INSERT INTO offers(student_id,school_name,offer_status,created_at,course_start_date)
                       VALUES(?,?,?,?,?)""",
                    ("260099", "Other College", "Received", stamp, "2028-02-01"),
                )
                db.execute(
                    """INSERT INTO student_offer_acceptances(
                         student_id,offer_id,status_before_acceptance,accepted_at,accepted_by_name,updated_at
                       ) VALUES(?,?,?,?,?,?)""",
                    ("260099", final_offer_id, "Received", stamp, "Admin", stamp),
                )
                db.execute(
                    """INSERT INTO visas(student_id,visa_grant_date,visa_status,created_at)
                       VALUES(?,?,?,?)""",
                    ("260099", "2027-03-01", "Granted", stamp),
                )
                admin = dict(db.one("SELECT u.*,r.name role_name,r.permissions_json FROM users u JOIN roles r ON r.id=u.role_id WHERE username='admin'"))
                admin["module_permissions_json"] = app_module.modules_json_for_user(admin["id"])
                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "csrf-token"
                handler.query = {"view": ["card"], "q": ["Table"]}
                handler.client_address = ("127.0.0.1", 12345)
                handler.headers = {}
                handler.require = lambda permission: True
                captured = {}
                handler.send_html = lambda html, status=200, headers=None: captured.update({"html": html, "status": status})
                handler.error_page = lambda message, status=400: captured.update({"error": message, "status": status})

                handler.students("GET")
                html = captured["html"]

                self.assertEqual(captured["status"], 200)
                self.assertIn("student-management-table", html)
                self.assertIn('href="/students/260099"', html)
                self.assertIn("Table Only", html)
                self.assertIn("已下签", html)
                self.assertIn("最终确认学校", html)
                self.assertIn("Offer开学时间", html)
                self.assertIn("Final College", html)
                self.assertNotIn("Other College", html)
                self.assertIn("01/02/2027", html)
                self.assertNotIn("01/02/2028", html)
                self.assertIn("Year 8", html)
                self.assertIn("01/03/2027", html)
                self.assertIn("批量操作", html)
                self.assertIn('name="q"', html)
                self.assertIn('name="view" value="table"', html)
                self.assertNotIn("Card View", html)
                self.assertNotIn("student-view-toggle", html)
                self.assertNotIn("workflow-card-list", html)
                self.assertNotIn("student-management-card", html)
            finally:
                app_module.db = old_db

