    def test_student_followup_tab_renders_note_and_permissions(self):
        from student_followup_notes import create_student_followup_note

        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            with db.transaction() as connection:
                connection.executescript(
                    Path("migrations/20260820_026_unified_reminder_center.sql").read_text(encoding="utf-8")
                )
            try:
                app_module.db = db
                stamp = "2026-08-08T10:00:00"
                db.execute(
                    """INSERT INTO students(student_id,passport_first_name,passport_last_name,current_status,created_date,updated_at,form_data_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    ("260101", "Note", "Student", "Active", stamp, stamp, "{}"),
                )
                admin = dict(db.one("SELECT u.*,r.name role_name,r.permissions_json FROM users u JOIN roles r ON r.id=u.role_id WHERE username='admin'"))
                admin["module_permissions_json"] = app_module.modules_json_for_user(admin["id"])
                connection = db.connect()
                try:
                    note = create_student_followup_note(
                        connection, student_id="260101", content="等待家长回复",
                        reminder_at="2027-08-10T09:15", recipient_id=admin["id"], actor=admin,
                    )
                    connection.commit()
                finally:
                    db._release_connection(connection)
                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "csrf-token"
                html = handler.student_detail_tab_content({"student_id": "260101"}, "reminders")

                self.assertIn("留言与提醒", html)
                self.assertIn("等待家长回复", html)
                self.assertIn("Admin", html)
                self.assertIn(f'/students/260101/followup-notes/{note.id}/edit', html)
                self.assertIn(f'/students/260101/followup-notes/{note.id}/delete', html)
                self.assertIn('value="csrf-token"', html)
                self.assertIn('value="2027-08-10"', html)
                self.assertIn('value="09:15"', html)
                db.execute(
                    "UPDATE reminders SET status='Completed',completed_at=?,completed_by=? WHERE id=?",
                    (stamp, admin["id"], note.id),
                )
                terminal_html = handler.student_detail_tab_content({"student_id": "260101"}, "reminders")
                self.assertNotIn(f'/students/260101/followup-notes/{note.id}/edit', terminal_html)
                self.assertIn("终态留言不可编辑", terminal_html)
            finally:
                app_module.db = old_db

