    def test_student_case_tabs_are_gated_ordered_and_lazy(self):
        self.assertTrue(
            app_module.allowed(
                {"permissions_json": json.dumps(["*"])},
                "offers.manage",
            )
        )
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-28T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(
                         student_id,passport_last_name,passport_first_name,
                         current_status,nas_status,created_date,updated_at,
                         form_data_json
                       ) VALUES(?,?,?,?,?,?,?,?)""",
                    (
                        "STEP6TAB001",
                        "Read",
                        "Only",
                        "New",
                        "pending",
                        stamp,
                        stamp,
                        "{}",
                    ),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {
                    "id": 1,
                    "username": "viewer",
                    "display_name": "Viewer",
                    "role_name": "Admin",
                    "permissions_json": json.dumps(
                        ["*", "student_cases.view", "progression_cases.view"]
                    ),
                    "module_permissions_json": json.dumps([]),
                }
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "unit-test"}
                handler.query = {}
                handler.csrf = "csrf-token"
                handler.require = lambda permission: True
                handler.message = lambda: ("", "")

                def render(flags):
                    handler.student_case_feature_flags = flags
                    captured = {}
                    handler.send_html = (
                        lambda html, *args, **kwargs: captured.setdefault(
                            "html", html
                        )
                    )
                    with mock.patch.object(
                        app_module.nas,
                        "status",
                        return_value={"ready": False, "label": "offline"},
                    ), mock.patch.object(
                        app_module.student_case_views,
                        "render_student_case_tab",
                        side_effect=AssertionError(
                            "initial page must not query Student Case"
                        ),
                    ):
                        handler.student_detail("GET", "STEP6TAB001")
                    return captured["html"]

                enabled = app_module.student_case_views.StudentCaseFeatureFlags(
                    read_enabled=True
                )
                enabled_html = render(enabled)
                expected_order = (
                    'data-tab="profile"',
                    'data-tab="transfer_cases"',
                    'data-tab="progression_cases"',
                    'data-tab="applications"',
                    'data-tab="contracts"',
                    'data-tab="school_plans"',
                    'data-tab="offer"',
                    'data-tab="payments"',
                    'data-tab="coe"',
                    'data-tab="visa"',
                    'data-tab="homestay"',
                    'data-tab="history"',
                    'data-tab="reminders"',
                )
                positions = [
                    enabled_html.index(marker) for marker in expected_order
                ]
                self.assertEqual(positions, sorted(positions))
                self.assertIn(
                    'data-lazy-tab-url="/students/STEP6TAB001/tab/transfer_cases"',
                    enabled_html,
                )
                self.assertIn(
                    'data-lazy-tab-url="/students/STEP6TAB001/tab/progression_cases"',
                    enabled_html,
                )
                self.assertNotIn("该学生目前没有转学记录", enabled_html)
                self.assertNotIn("该学生目前没有升学记录", enabled_html)
                self.assertNotIn("发起转学", enabled_html)
                self.assertNotIn("发起升学", enabled_html)

                handler.user["permissions_json"] = json.dumps(["*"])
                wildcard_only_html = render(enabled)
                self.assertNotIn(
                    'data-tab="transfer_cases"', wildcard_only_html
                )
                self.assertNotIn(
                    'data-tab="progression_cases"', wildcard_only_html
                )

                handler.user["permissions_json"] = json.dumps(
                    ["*", "student_cases.view", "progression_cases.view"]
                )
                closed_html = render(
                    app_module.student_case_views.StudentCaseFeatureFlags()
                )
                self.assertNotIn('data-tab="transfer_cases"', closed_html)
                self.assertNotIn(
                    'data-tab="progression_cases"', closed_html
                )
                original_order = (
                    'data-tab="profile"',
                    'data-tab="applications"',
                    'data-tab="offer"',
                    'data-tab="coe"',
                    'data-tab="visa"',
                    'data-tab="payments"',
                    'data-tab="homestay"',
                    'data-tab="contracts"',
                    'data-tab="history"',
                    'data-tab="reminders"',
                )
                closed_positions = [
                    closed_html.index(marker) for marker in original_order
                ]
                self.assertEqual(closed_positions, sorted(closed_positions))

                db.set_setting("STUDENT_CASES_READ_ENABLED", "true")
                setting_enabled_html = render(None)
                self.assertIn(
                    'data-tab="transfer_cases"', setting_enabled_html
                )
                self.assertIn(
                    'data-tab="progression_cases"', setting_enabled_html
                )
                self.assertNotIn(
                    "该学生目前没有转学记录", setting_enabled_html
                )
                self.assertNotIn(
                    "该学生目前没有升学记录", setting_enabled_html
                )

                db.set_setting("STUDENT_CASES_READ_ENABLED", "false")
                setting_closed_html = render(None)
                self.assertNotIn(
                    'data-tab="transfer_cases"', setting_closed_html
                )
                self.assertNotIn(
                    'data-tab="progression_cases"', setting_closed_html
                )

                with mock.patch.object(
                    db,
                    "setting",
                    side_effect=sqlite3.OperationalError(
                        "database is locked"
                    ),
                ):
                    failed_reader_html = render(None)
                self.assertNotIn(
                    'data-tab="transfer_cases"', failed_reader_html
                )
                self.assertNotIn(
                    'data-tab="progression_cases"', failed_reader_html
                )
                self.assertNotIn("Traceback", failed_reader_html)

                handler.user["permissions_json"] = json.dumps(
                    ["students.view", "student_cases.create"]
                )
                no_view_html = render(enabled)
                self.assertNotIn(
                    'data-tab="transfer_cases"', no_view_html
                )
                self.assertNotIn(
                    'data-tab="progression_cases"', no_view_html
                )
            finally:
                app_module.db = old_db

    def test_student_case_lazy_access_is_gated_and_schema_safe(self):
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            try:
                app_module.db = db
                stamp = "2026-07-28T10:00:00+10:00"
                db.execute(
                    """INSERT INTO students(
                         student_id,passport_last_name,passport_first_name,
                         current_status,nas_status,created_date,updated_at,
                         form_data_json
                       ) VALUES(?,?,?,?,?,?,?,?)""",
                    (
                        "STEP6TAB002",
                        "Schema",
                        "Safe",
                        "New",
                        "pending",
                        stamp,
                        stamp,
                        "{}",
                    ),
                )
                handler = object.__new__(app_module.CRMHandler)
                handler.user = {
                    "id": 1,
                    "username": "viewer",
                    "display_name": "Viewer",
                    "role_name": "Consultant",
                    "permissions_json": json.dumps(
                        ["students.view", "student_cases.view"]
                    ),
                }
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "unit-test"}
                handler.query = {}
                handler.csrf = "csrf-token"
                handler.require = lambda permission: True
                handler.student_case_feature_flags = (
                    app_module.student_case_views.StudentCaseFeatureFlags(
                        read_enabled=True
                    )
                )
                captured = {}
                handler.send_html = (
                    lambda html, *args, **kwargs: captured.setdefault(
                        "html", html
                    )
                )

                handler.student_detail_tab(
                    "GET", "STEP6TAB002", "transfer_cases"
                )
                self.assertIn(
                    "Student Case数据结构尚未启用。", captured["html"]
                )
                self.assertNotIn("Traceback", captured["html"])
                self.assertNotIn("<form", captured["html"])

                denied = []
                handler.deny_module_access = (
                    lambda module: denied.append(module)
                )
                handler.student_case_feature_flags = (
                    app_module.student_case_views.StudentCaseFeatureFlags()
                )
                with mock.patch.object(
                    app_module.student_case_views,
                    "render_student_case_tab",
                    side_effect=AssertionError(
                        "closed read gate must not query Student Case"
                    ),
                ):
                    handler.student_detail_tab(
                        "GET", "STEP6TAB002", "transfer_cases"
                    )
                self.assertEqual(denied, ["students"])

                handler.student_case_feature_flags = (
                    app_module.student_case_views.StudentCaseFeatureFlags(
                        read_enabled=True
                    )
                )
                handler.user["permissions_json"] = json.dumps(["*"])
                handler.student_detail_tab(
                    "GET", "STEP6TAB002", "transfer_cases"
                )
                self.assertEqual(denied, ["students", "students"])

                handler.user["permissions_json"] = json.dumps(
                    ["students.view", "student_cases.create"]
                )
                handler.student_detail_tab(
                    "GET", "STEP6TAB002", "progression_cases"
                )
                self.assertEqual(
                    denied, ["students", "students", "students"]
                )
                handler.student_detail_tab(
                    "GET", "999999", "progression_cases"
                )
                self.assertEqual(
                    denied,
                    ["students", "students", "students", "students"],
                )

                handler.user["permissions_json"] = json.dumps(
                    ["students.view", "student_cases.view"]
                )
                handler.student_case_feature_flags = None
                db.set_setting("STUDENT_CASES_READ_ENABLED", "true")
                captured.clear()
                handler.student_detail_tab(
                    "GET", "STEP6TAB002", "transfer_cases"
                )
                self.assertIn(
                    "Student Case数据结构尚未启用。", captured["html"]
                )

                db.set_setting("STUDENT_CASES_READ_ENABLED", "false")
                with mock.patch.object(
                    app_module.student_case_views,
                    "render_student_case_tab",
                    side_effect=AssertionError(
                        "closed setting must deny before Student Case query"
                    ),
                ):
                    handler.student_detail_tab(
                        "GET", "STEP6TAB002", "transfer_cases"
                    )
                self.assertEqual(
                    denied,
                    [
                        "students",
                        "students",
                        "students",
                        "students",
                        "students",
                    ],
                )

                with mock.patch.object(
                    db,
                    "setting",
                    side_effect=sqlite3.OperationalError(
                        "no such table: system_settings"
                    ),
                ), mock.patch.object(
                    app_module.student_case_views,
                    "render_student_case_tab",
                    side_effect=AssertionError(
                        "failed setting read must deny before Case query"
                    ),
                ):
                    handler.student_detail_tab(
                        "GET", "STEP6TAB002", "transfer_cases"
                    )
                self.assertEqual(
                    denied,
                    [
                        "students",
                        "students",
                        "students",
                        "students",
                        "students",
                        "students",
                    ],
                )
            finally:
                app_module.db = old_db

