    def test_school_area_profile_schema_tracks_history_and_metrics(self):
        with tempfile.TemporaryDirectory() as folder:
            db = Database(Path(folder) / "aaie_crm.db")
            db.initialize()
            profile_columns = {row["name"] for row in db.all("PRAGMA table_info(school_area_profiles)")}
            for column in (
                "school_id", "suburb", "postcode", "state", "latitude", "longitude",
                "sa1_code", "sa2_code", "sa2_name", "sa3_code", "sa3_name",
                "sa4_code", "sa4_name", "lga_code", "lga_name", "data_year",
                "source", "source_url", "last_checked_at", "raw_json",
            ):
                self.assertIn(column, profile_columns)
            metric_columns = {row["name"] for row in db.all("PRAGMA table_info(school_area_profile_metrics)")}
            for column in (
                "profile_id", "metric_key", "metric_label", "metric_value",
                "metric_unit", "data_year", "source", "source_url", "raw_json", "notes",
            ):
                self.assertIn(column, metric_columns)

            school_id = db.one("SELECT id FROM schools ORDER BY id LIMIT 1")["id"]
            first_id = app_module.upsert_school_area_profile(
                db,
                school_id,
                {
                    "suburb": "Balwyn North",
                    "postcode": "3104",
                    "state": "VIC",
                    "latitude": -37.7909,
                    "longitude": 145.0827,
                    "sa2_code": "207011152",
                    "sa2_name": "Balwyn North",
                    "lga_code": "21110",
                    "lga_name": "Boroondara",
                    "data_year": "2021",
                    "source": "ABS Data API",
                    "source_url": "https://data.api.abs.gov.au/rest/",
                    "last_checked_at": "2026-06-28T12:00:00+10:00",
                },
                {
                    "total_population": 12800,
                    "median_age": 43,
                    "mandarin_home_percent": None,
                },
            )
            second_id = app_module.upsert_school_area_profile(
                db,
                school_id,
                {
                    "suburb": "Balwyn North",
                    "postcode": "3104",
                    "state": "VIC",
                    "latitude": -37.7909,
                    "longitude": 145.0827,
                    "sa2_code": "207011152",
                    "sa2_name": "Balwyn North",
                    "lga_code": "21110",
                    "lga_name": "Boroondara",
                    "data_year": "2026",
                    "source": "ABS Data API",
                    "source_url": "https://data.api.abs.gov.au/rest/",
                    "last_checked_at": "2026-06-28T12:05:00+10:00",
                },
                {"total_population": 13100},
            )
            self.assertNotEqual(first_id, second_id)
            self.assertEqual(db.one("SELECT COUNT(*) count FROM school_area_profiles WHERE school_id=?", (school_id,))["count"], 2)
            empty_metric = db.one(
                """SELECT metric_value FROM school_area_profile_metrics
                   WHERE profile_id=? AND metric_key='mandarin_home_percent'""",
                (first_id,),
            )
            self.assertIsNone(empty_metric["metric_value"])

