    def test_abs_census_sdmx_metrics_extracts_sa2_core_indicators(self):
        def payload(dimensions, series):
            return {
                "data": {
                    "structures": [
                        {
                            "dimensions": {
                                "series": dimensions,
                                "observation": [{"id": "TIME_PERIOD", "values": [{"id": "2021", "name": "2021"}]}],
                            }
                        }
                    ],
                    "dataSets": [
                        {
                            "series": {
                                key: {"observations": {"0": [value]}}
                                for key, value in series.items()
                            }
                        }
                    ],
                }
            }

        g01 = payload(
            [
                {"id": "SEXP", "values": [{"id": "3", "name": "Persons"}, {"id": "1", "name": "Males"}, {"id": "2", "name": "Females"}]},
                {"id": "PCHAR", "values": [{"id": "P_1", "name": "Total persons"}, {"id": "B_O", "name": "Birthplace: Elsewhere"}, {"id": "L_O", "name": "Language used at home: Other language"}, {"id": "S_1", "name": "Highest year of school completed: Year 12 or equivalent"}, {"id": "5_14", "name": "Age groups: 5-14 years"}, {"id": "15_19", "name": "Age groups: 15-19 years"}]},
                {"id": "REGION", "values": [{"id": "206071139", "name": "Abbotsford"}]},
                {"id": "REGION_TYPE", "values": [{"id": "SA2", "name": "Statistical Area Level 2"}]},
                {"id": "STATE", "values": [{"id": "2", "name": "Victoria"}]},
            ],
            {
                "0:0:0:0:0": 7019,
                "1:0:0:0:0": 3500,
                "2:0:0:0:0": 3519,
                "0:1:0:0:0": 3090,
                "0:2:0:0:0": 2650,
                "0:3:0:0:0": 4010,
                "0:4:0:0:0": 363,
                "0:5:0:0:0": 334,
            },
        )
        g02 = payload(
            [
                {"id": "MEDAVG", "values": [{"id": "1", "name": "Median age of persons"}, {"id": "2", "name": "Median total personal income ($/weekly)"}, {"id": "3", "name": "Median total family income ($/weekly)"}, {"id": "4", "name": "Median total household income ($/weekly)"}, {"id": "5", "name": "Median mortgage repayment ($/monthly)"}, {"id": "6", "name": "Median rent ($/weekly)"}, {"id": "8", "name": "Average household size"}]},
                {"id": "REGION", "values": [{"id": "206071139", "name": "Abbotsford"}]},
                {"id": "REGION_TYPE", "values": [{"id": "SA2", "name": "Statistical Area Level 2"}]},
                {"id": "STATE", "values": [{"id": "2", "name": "Victoria"}]},
            ],
            {
                "0:0:0:0": 33,
                "1:0:0:0": 1354,
                "2:0:0:0": 3024,
                "3:0:0:0": 2197,
                "4:0:0:0": 2167,
                "5:0:0:0": 425,
                "6:0:0:0": 1.9,
            },
        )
        g33 = payload(
            [
                {"id": "HIND", "values": [{"id": "_T", "name": "Total"}]},
                {"id": "HHCD", "values": [{"id": "1_2", "name": "Family households"}, {"id": "3", "name": "Non-family household"}, {"id": "_T", "name": "Total"}]},
                {"id": "REGION", "values": [{"id": "206071139", "name": "Abbotsford"}]},
                {"id": "REGION_TYPE", "values": [{"id": "SA2", "name": "Statistical Area Level 2"}]},
                {"id": "STATE", "values": [{"id": "2", "name": "Victoria"}]},
            ],
            {
                "0:0:0:0:0": 2108,
                "0:1:0:0:0": 2292,
                "0:2:0:0:0": 4398,
            },
        )
        g08 = payload(
            [
                {"id": "SEXP", "name": "Sex", "values": [{"id": "3", "name": "Persons"}, {"id": "1", "name": "Males"}, {"id": "2", "name": "Females"}]},
                {"id": "ANCP", "name": "Ancestry", "values": [{"id": "1101", "name": "Australian"}, {"id": "6101", "name": "Chinese"}, {"id": "_T", "name": "Total"}]},
                {"id": "BPPP", "name": "Country of birth of parents", "values": [{"id": "_N", "name": "Birthplace for either or both parents not stated"}, {"id": "_T", "name": "Total responses"}, {"id": "1", "name": "Both parents born overseas"}]},
                {"id": "REGION", "values": [{"id": "206071139", "name": "Abbotsford"}]},
                {"id": "REGION_TYPE", "values": [{"id": "SA2", "name": "Statistical Area Level 2"}]},
                {"id": "STATE", "values": [{"id": "2", "name": "Victoria"}]},
            ],
            {
                "0:0:0:0:0:0": 28,
                "0:0:1:0:0:0": 2890,
                "0:1:0:0:0:0": 6,
                "0:1:1:0:0:0": 1168,
                "0:1:2:0:0:0": 900,
            },
        )
        profile = app_module.normalize_abs_census_sa2_profile({"G01": g01, "G02": g02, "G08": g08, "G33": g33}, "206071139")
        self.assertEqual(profile["total_population"], 7019)
        self.assertEqual(profile["population_male"], 3500)
        self.assertEqual(profile["population_female"], 3519)
        self.assertEqual(profile["median_age"], 33)
        self.assertEqual(profile["median_household_income"], 2197)
        self.assertEqual(profile["median_rent"], 425)
        self.assertEqual(profile["household_count"], 4398)
        self.assertEqual(profile["family_household_percent"], 47.9)
        self.assertEqual(profile["school_age_children_count"], 697)
        self.assertEqual(profile["overseas_born_percent"], 44.0)
        self.assertEqual(profile["english_only_home_percent"], 62.2)
        self.assertEqual(profile["australian_ancestry_count"], 2890)
        self.assertEqual(profile["chinese_ancestry_count"], 1168)

