    def test_school_detail_contains_school_area_safety_profile_panel(self):
        app = Path("app.py").read_text(encoding="utf-8")
        self.assertIn("def school_area_safety_profile_panel", app)
        school_area_panel_match = re.search(
            r"def school_area_safety_profile_panel\(self, school\):(?P<body>.*?)def school_area_profile_resolve_coordinates",
            app,
            flags=re.S,
        )
        self.assertIsNotNone(school_area_panel_match)
        panel_body = school_area_panel_match.group("body")
        self.assertIn("学校所在区域安全数据", panel_body)
        self.assertIn("该数据为学校所在区域的官方统计参考，不代表学校本身安全程度。", panel_body)
        self.assertIn("记录犯罪总数", panel_body)
        self.assertIn("每10万人犯罪率", panel_body)
        self.assertIn("刑事事件", panel_body)
        self.assertIn("财产及欺诈类犯罪", panel_body)
        self.assertIn("LGA 口径补齐", panel_body)
        self.assertNotIn("Area safety reference", panel_body)
        self.assertNotIn("Crime data indicator", panel_body)
        self.assertNotIn("学区犯罪率", app)

