    def test_vic_crime_latest_resources_keeps_general_and_lga_for_same_period(self):
        from scripts import import_vic_crime_stats

        package = {
            "resources": [
                {"name": "Recorded offences - Year ending Dec 2025", "format": ".xlsx", "url": "https://example.test/dec.xlsx"},
                {"name": "Recorded offences - Year ending Mar 2026", "format": ".xlsx", "url": "https://example.test/mar.xlsx"},
                {"name": "Recorded offences by LGA - Year Ending Mar 2026", "format": ".xlsx", "url": "https://example.test/mar-lga.xlsx"},
            ]
        }
