    def test_safebox_restore_calendar_view_reads_hourly_dirty_and_skipped_points_safely(self):
        old_app_dir = app_module.APP_DIR
        old_db = app_module.db
        with tempfile.TemporaryDirectory() as folder:
            try:
                root = Path(folder).resolve()
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.APP_DIR = root
                admin = dict(db.one("SELECT u.*,r.name role_name,r.permissions_json FROM users u JOIN roles r ON r.id=u.role_id WHERE username='admin'"))
                admin["module_permissions_json"] = app_module.modules_json_for_user(admin["id"])

                hourly = root / "backups" / "restore-points" / "hourly"
                dirty = root / "backups" / "restore-points" / "dirty"
                stable_0100 = hourly / "20260710_010000"
                stable_0400 = hourly / "20260710_040000"
                skipped_0300 = hourly / "20260710_030000"
                missing_0500 = hourly / "20260710_050000"
                broken_0600 = hourly / "20260710_060000"
                dirty_0200 = dirty / "20260710_020000"
                for path in (stable_0100, stable_0400, skipped_0300, missing_0500, broken_0600, dirty_0200):
                    path.mkdir(parents=True)
                (stable_0100 / "metadata.json").write_text(json.dumps({
                    "created_at": "2026-07-10T01:00:00",
                    "restore_point_type": "stable",
                    "branch": "safebox/example",
                    "commit": "stable0100abcdef",
                    "git_status_clean": True,
                    "modified_files": [],
                    "stash_exists": False,
                    "db_quick_check": "ok",
                    "admin_health": {"ok": True, "status": 200},
                    "parent_health": {"ok": True, "status": 200},
                    "restore_point_status": "created",
                    "latest_stable_tag": "stable-demo",
                    "notes": "stable one",
                }), encoding="utf-8")
                (stable_0400 / "metadata.json").write_text(json.dumps({
                    "created_at": "2026-07-10T04:00:00",
                    "restore_point_type": "stable",
                    "branch": "safebox/example",
                    "commit": "stable0400abcdef",
                    "git_status_clean": True,
                    "modified_files": [],
                    "stash_exists": True,
                    "db_quick_check": "ok",
                    "admin_health": {"ok": True},
                    "parent_health": {"ok": True},
                    "restore_point_status": "created",
                    "latest_stable_tag": "stable-demo",
                    "notes": "stable two",
                }), encoding="utf-8")
                (dirty_0200 / "metadata.json").write_text(json.dumps({
                    "created_at": "2026-07-10T02:00:00",
                    "restore_point_type": "dirty_backup",
                    "not_a_stable_restore_point": True,
                    "branch": "safebox/example",
                    "commit": "dirty0200abcdef",
                    "git_status_clean": False,
                    "modified_files": ["app.py", "tests/test_core.py"],
                    "stash_exists": False,
                    "db_quick_check": "ok",
                    "restore_point_status": "created",
                    "notes": "dirty one",
                }), encoding="utf-8")
                (skipped_0300 / "metadata.json").write_text(json.dumps({
                    "created_at": "2026-07-10T03:00:00",
                    "restore_point_type": "skipped",
                    "branch": "safebox/example",
                    "commit": "skip0300abcdef",
                    "git_status_clean": True,
                    "modified_files": [],
                    "stash_exists": False,
                    "db_quick_check": "database locked",
                    "restore_point_status": "not_created",
                    "skip_reason": "health check failed",
                    "notes": "skipped one",
                }), encoding="utf-8")
                (broken_0600 / "metadata.json").write_text("{bad json", encoding="utf-8")

                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "csrf-token"
                handler.query = {"date": ["2026-07-10"], "point": ["dirty:20260710_020000"]}
                captured = {}
                handler.send_html = lambda html, status=200, headers=None: captured.update({"html": html, "status": status})
                handler.error_page = lambda message, status=400: captured.update({"error": message, "status": status})

                handler.safebox_restore_calendar("GET")
                html = captured["html"]
                self.assertEqual(captured["status"], 200)
                self.assertIn("每小时恢复点日历", html)
                self.assertIn("Restore Points Calendar", html)
                self.assertIn("2026-07-10", html)
                self.assertIn("Stable 2", html)
                self.assertIn("Dirty 1", html)
                self.assertIn("Skipped 1", html)
                self.assertIn("Failed 2", html)
                self.assertLess(html.index("01:00 Stable Restore Point"), html.index("02:00 Dirty Backup"))
                self.assertLess(html.index("02:00 Dirty Backup"), html.index("03:00 Skipped - health check failed"))
                self.assertIn("这不是稳定恢复点，只是未提交工作区备份。不能直接作为系统稳定恢复点。", html)
                self.assertIn("metadata 缺失 / 无法读取", html)
                self.assertIn("health check failed", html)
                self.assertIn("复制恢复前检查命令", html)
                self.assertIn("复制恢复计划", html)
                self.assertIn("复制路径", html)
                self.assertIn("复制 commit hash", html)
                self.assertIn("复制 metadata 摘要", html)
                self.assertIn("cd &quot;/Volumes/Zhang/AAIE CodeX/CRM&quot;", html)
                self.assertIn("sqlite3 database/aaie_crm.db &#x27;PRAGMA quick_check;&#x27;", html)
                self.assertIn("git.diff.patch", html)
                self.assertNotIn("/safebox/restore-calendar/execute", html)
                self.assertNotIn("/safebox/restore-calendar/restore", html)
                self.assertNotIn("git reset --hard", html)
                self.assertNotIn("shutil.copy2(restored_db", html)
                self.assertNotIn("restore_system_backup(", html)

                captured.clear()
                handler.query = {}
                handler.safebox_centre("GET")
                self.assertEqual(captured["status"], 200)
                self.assertIn("SAFEBOX / 恢复记录", captured["html"])
                self.assertIn("/safebox/restore-calendar", captured["html"])
                self.assertIn("/safebox/system-restore-points", captured["html"])

                app_source = Path("app.py").read_text(encoding="utf-8")
                self.assertIn('r"^/safebox/restore-calendar$"', app_source)
                for route in (
                    'r"^/school-plan-reports$"',
                    'r"^/contracts$"',
                    'r"^/visa-management$"',
                    'r"^/data-updates$"',
                    'r"^/api/assistant/query$"',
                ):
                    self.assertIn(route, app_source)
            finally:
                app_module.APP_DIR = old_app_dir
                app_module.db = old_db

    def test_backup_control_centre_page_shows_snapshot_status_controls_and_copy_only_restore_plan(self):
        old_app_dir = app_module.APP_DIR
