    def test_contract_revision_generates_new_version_with_reason_and_audit(self):
        old_db = app_module.db
        old_root = app_module.STANDALONE_CONTRACT_ROOT
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.STANDALONE_CONTRACT_ROOT = root / "standalone"
                user = {"id": 1, "username": "admin", "role_name": "Admin"}
                payload = {
                    "contract_title": STUDY_CONTRACT_TITLE,
                    "company_legal_name": "AAIE Group Pty Ltd",
                    "company_trading_name": "AAIE Education",
                    "company_abn_acn": "ABN 11 222 333 444",
                    "company_address": "Level 8, 123 Collins Street, Melbourne VIC 3000",
                    "company_authorised_person": "AAIE",
                    "company_phone": "+61 3 9000 0000",
                    "company_email": "contracts@example.com",
                    "contract_date": "2026-06-24",
                    "parent_signer_name": "Test Parent",
                    "parent_signer_relationship": "母亲",
                    "parent_phone": "0400000000",
                    "parent_email": "parent@example.com",
                    "student_full_name": "Revision Test Student",
                    "student_date_of_birth": "2012-01-01",
                    "service_scope_items": ["澳洲留学规划咨询"],
                    "service_scope_json": json.dumps(["study_planning_consulting"], ensure_ascii=False),
                    "service_type": "留学咨询及签证服务",
                    "service_fee_currency": "澳洲公户",
                    "consulting_and_visa_service_fee": "2400",
                    "final_fee_amount": "2400",
                    "refund_policy_type": "visa_refusal_no_further_application",
                    "refund_policy_text": "旧退款条款。",
                    "special_terms": "无。",
                }
                initial_folder = app_module.STANDALONE_CONTRACT_ROOT / "CONTRACT-20260624-0001" / "generated"
                initial = initial_folder / "StudyAbroadContract_20260624_V1.docx"
                generate_study_abroad_contract(payload, initial)
                contract_id = db.execute(
                    """INSERT INTO contracts(
                       contract_uid,is_standalone_contract,standalone_data_json,contract_category,contract_type,
                       contract_title,contract_status,contract_date,service_type,service_scope_json,
                       service_fee_currency,consulting_and_visa_service_fee,final_fee_amount,refund_policy_type,
                       refund_policy_text,special_terms,contract_file_path,template_version,generated_by,generated_at,updated_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "CONTRACT-20260624-0001", 1,
                        app_module.standalone_contract_storage_json({}, payload),
                        "留学合同", "StudyAbroadContract", STUDY_CONTRACT_TITLE, "Draft",
                        "2026-06-24", payload["service_type"], payload["service_scope_json"],
                        payload["service_fee_currency"], payload["consulting_and_visa_service_fee"],
                        payload["final_fee_amount"], payload["refund_policy_type"], payload["refund_policy_text"],
                        payload["special_terms"], str(initial), "V1", 1, "2026-06-24T10:00:00", "2026-06-24T10:00:00",
                    ),
                )

                with self.assertRaises(ValueError):
                    app_module.generate_contract_revision_version(
                        contract_id, user, "special_conditions", "新增特别条款。", "", parent_request_text="家长要求修改"
                    )

                result = app_module.generate_contract_revision_version(
                    contract_id,
                    user,
                    "special_conditions",
                    "新增特别条款：第三方费用不包含在服务费内。",
                    "家长要求增加第三方费用说明",
                    parent_request_text="家长微信要求补充第三方费用",
                    revision_instruction="增加特别条款",
                )
                self.assertTrue(initial.exists())
                self.assertTrue(Path(result["file_path_docx"]).exists())
                self.assertNotEqual(str(initial), result["file_path_docx"])
                self.assertEqual(result["version_number"], 2)
                updated = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
                self.assertEqual(updated["special_terms"], "新增特别条款：第三方费用不包含在服务费内。")
                self.assertEqual(updated["contract_file_path"], result["file_path_docx"])
                self.assertEqual(db.one("SELECT COUNT(*) count FROM contract_versions WHERE contract_id=?", (contract_id,))["count"], 2)
                self.assertEqual(db.one("SELECT COUNT(*) count FROM contract_revision_changes WHERE revision_request_id=?", (result["revision_request_id"],))["count"], 1)
                audit_actions = [row["action_type"] for row in db.all("SELECT action_type FROM audit_logs ORDER BY id")]
                self.assertIn("contract_revision_started", audit_actions)
                self.assertIn("contract_revised_version_generated", audit_actions)
        finally:
            app_module.db = old_db
            app_module.STANDALONE_CONTRACT_ROOT = old_root

