    def test_effective_contract_draft_rebuilds_stale_docx_from_latest_sections(self):
        old_db = app_module.db
        old_nas = app_module.nas
        old_dir = app_module.CONTRACT_SIGNING_DIR

        class FakeNas:
            def student_folder(self, student):
                return Path(student["folder_path"]).resolve()

            def category_folder(self, student, category):
                folder = self.student_folder(student) / category
                folder.mkdir(parents=True, exist_ok=True)
                return folder

        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                db = Database(root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas = FakeNas()
                app_module.CONTRACT_SIGNING_DIR = root / "contract_signing"
                db.set_setting("company_abn_acn", "ABN 11 222 333 444", 1)
                stamp = "2026-07-07T02:20:00+10:00"
                student_folder = root / "Latest Version Student"
                (student_folder / "Forms").mkdir(parents=True)
                db.execute(
                    """INSERT INTO students(student_id,passport_last_name,passport_first_name,current_status,date_of_birth,current_year_level,
                       applying_year_level,created_date,updated_at,folder_path,home_address,form_data_json)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                    ("TLATEST001", "Version", "Latest", "Active", "2012-01-01", "Year 8", "Year 9", stamp, stamp, str(student_folder), "10 Parent Street", "{}"),
                )
                form = {
                    "contract_date": "2026-07-07",
                    "parent_signer_name": "Jane Parent",
                    "parent_signer_relationship": "母亲",
                    "parent_phone": "0400000000",
                    "parent_email": "parent@example.com",
                    "service_type": "study_and_visa",
                    "service_scope_submitted": "1",
                    "service_scope": ["study_planning_consulting"],
                    "service_fee_currency": "澳洲公户",
                    "consulting_and_visa_service_fee": "2400",
                    "discount_enabled": "no",
                    "refund_policy_text": "退款规则测试。",
                    "special_terms": "无。",
                }
                payload = app_module.contract_student_payload(db.one("SELECT * FROM students WHERE student_id=?", ("TLATEST001",)), form)
                payload["contract_uid"] = "CONTRACT-LATEST-001"
                stale_docx = student_folder / "Forms" / "StudyAbroadContractRevision_20260707_V3.docx"
                app_module.generate_study_contract_document(payload, stale_docx)
                stale_text = "\n".join(p.text for p in Document(stale_docx).paragraphs)
                self.assertNotIn("qqqqqqqqq", stale_text)
                contract_id = db.execute(
                    """INSERT INTO contracts(student_id,contract_uid,contract_category,contract_type,contract_title,contract_status,
                       contract_date,service_type,service_scope_json,other_service_scope_text,service_fee_currency,
                       consulting_and_visa_service_fee,final_fee_amount,refund_policy_text,special_terms,
                       parent_signer_name,parent_phone,parent_email,contract_file_path,template_version,generated_by,generated_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "TLATEST001", "CONTRACT-LATEST-001", "留学合同", "StudyAbroadContract", STUDY_CONTRACT_TITLE, "Sent",
                        payload["contract_date"], payload["service_type"], payload["service_scope_json"], payload["other_service_scope_text"],
                        payload["service_fee_currency"], payload["consulting_and_visa_service_fee"], payload["final_fee_amount"],
                        payload["refund_policy_text"], payload["special_terms"], payload["parent_signer_name"],
                        payload["parent_phone"], payload["parent_email"], str(stale_docx), "V1", 1, stamp, stamp,
                    ),
                )
                version_id = db.execute(
                    """INSERT INTO contract_versions(contract_id,student_id,version_number,version_label,file_path_docx,status,
                       revision_reason,generated_by,generated_at,created_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (contract_id, "TLATEST001", 3, "V3", str(stale_docx), "Active", "家长要求修改甲方权利义务", 1, stamp, stamp),
                )
                db.execute(
                    """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
                       file_path,version,file_size,uploaded_by,uploaded_at,preview_path,is_active)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,1)""",
                    (
                        "TLATEST001", "Forms", "StudyAbroadContractRevision",
                        stale_docx.name, stale_docx.name, str(stale_docx), "3", stale_docx.stat().st_size, 1, stamp, "",
                    ),
                )
                custom_clause = "qqqqqqqqq甲方有权按照本合同约定向乙方收取留学咨询及签证服务费"
                db.execute(
                    """INSERT INTO contract_sections(contract_id,version_id,section_key,section_title,section_content,
                       source_type,updated_by,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?)""",
                    (contract_id, version_id, "party_a_obligations", "甲方权利义务", custom_clause, "Contract Editor", 1, stamp, stamp),
                )

                doc_before = db.one("SELECT * FROM student_documents WHERE student_id=? AND file_path=? AND is_active=1", ("TLATEST001", str(stale_docx)))
                effective_doc = app_module.effective_contract_document_for_output(doc_before, {"id": 1, "username": "admin", "role_name": "Admin"})
                self.assertEqual(Path(effective_doc["file_path"]).resolve(), stale_docx.resolve())
                helper_text = "\n".join(p.text for p in Document(effective_doc["file_path"]).paragraphs)
                self.assertIn(custom_clause, helper_text)

                contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
                effective_docx = app_module.ensure_contract_effective_draft_file(contract, {"id": 1, "username": "admin", "role_name": "Admin"})
                rebuilt_text = "\n".join(p.text for p in Document(effective_docx).paragraphs)
                self.assertIn(custom_clause, rebuilt_text)
                self.assertEqual(effective_docx.resolve(), stale_docx.resolve())
                doc_row = db.one("SELECT file_size FROM student_documents WHERE student_id=? AND file_path=? AND is_active=1", ("TLATEST001", str(stale_docx)))
                self.assertEqual(int(doc_row["file_size"]), stale_docx.stat().st_size)

                handler = object.__new__(app_module.CRMHandler)
                handler.user = {"id": 1, "username": "admin", "role_name": "Admin"}
                contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
                self.assertEqual(handler.contract_center_file_path(contract, "draft").resolve(), stale_docx.resolve())
                signing_pdf = handler.contract_signing_source_pdf(contract)
                signing_text = "\n".join(page.extract_text() or "" for page in app_module.PdfReader(str(signing_pdf)).pages)
                self.assertIn(custom_clause, signing_text)

                db.execute("UPDATE contracts SET contract_status='ParentSigned' WHERE id=?", (contract_id,))
                payload["standard_clause_texts"]["party_a_obligations"] = app_module.STUDY_CONTRACT_STANDARD_TEXT_DEFAULTS["party_a_obligations"]
                app_module.generate_study_contract_document(payload, stale_docx)
                signed_contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
                app_module.ensure_contract_effective_draft_file(signed_contract, {"id": 1, "username": "admin", "role_name": "Admin"})
                locked_text = "\n".join(p.text for p in Document(stale_docx).paragraphs)
                self.assertNotIn(custom_clause, locked_text)
        finally:
            app_module.db = old_db
            app_module.nas = old_nas
            app_module.CONTRACT_SIGNING_DIR = old_dir

