    def test_system_backup_zip_contains_metadata_not_student_files(self):
        old_backup_dir = app_module.BACKUP_DIR
        old_db_path = app_module.DB_PATH
        old_db = app_module.db
        try:
            with tempfile.TemporaryDirectory() as folder:
                root = Path(folder)
                app_module.BACKUP_DIR = root / "backups"
                app_module.DB_PATH = root / "database" / "aaie_crm.db"
                app_module.db = Database(app_module.DB_PATH)
                app_module.db.initialize()
                target, manifest = app_module.create_system_backup(None, notes="Unit test", audit=False)
                self.assertTrue(target.exists())
                self.assertRegex(target.name, r"^AAIE_CRM_Backup_\d{8}_\d{6}\.zip$")
                with zipfile.ZipFile(target) as zf:
                    names = set(zf.namelist())
                    self.assertIn("database/aaie_crm.db", names)
                    self.assertIn("exports/system_settings.json", names)
                    self.assertIn("backup_manifest.json", names)
                    saved_manifest = json.loads(zf.read("backup_manifest.json").decode("utf-8"))
                    self.assertEqual(saved_manifest["backup_notes"], "Unit test")
                    joined_names = "\n".join(names)
                    self.assertNotIn("/Volumes/Server/Students/2024", joined_names)
                    self.assertNotIn("/Volumes/Server/Students/2025", joined_names)
                    self.assertNotIn("/Volumes/Server/Students/2026", joined_names)
                self.assertIn("/Volumes/Server/Students/2026", manifest["excluded_items"])
        finally:
            app_module.BACKUP_DIR = old_backup_dir
            app_module.DB_PATH = old_db_path
            app_module.db = old_db

