    def test_content_centre_dashboard_premium_v2_preserves_tabs_filters_cards_and_forms(self):
        old_db = app_module.db
        old_nas_status = app_module.nas.status
        with tempfile.TemporaryDirectory() as folder:
            try:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas.status = lambda: {"status": "ok"}
                stamp = "2026-07-21T12:00:00+10:00"
                samples = (
                    ("Imported sample", "Imported", "docx"),
                    ("Draft sample", "Draft", "crm_manual"),
                    ("Published sample", "Published", "google_drive_video"),
                    ("Pending sample", "PendingRecording", "content_extraction"),
                    ("Recorded sample", "Recorded", "docx"),
                )
                for index, (title, status, source_type) in enumerate(samples, start=1):
                    db.execute(
                        """INSERT INTO content_scripts(
                           title,body,category,status,review_status,version_number,source_type,
                           content_year,content_month,content_week,tags_json,created_at,updated_at
                           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (
                            title, f"Sample body {index}", "Test Category", status,
                            "Not Reviewed", 1, source_type, 2026, 7, 30,
                            json.dumps(["tag-a", "tag-b"] if index == 1 else []), stamp, stamp,
                        ),
                    )

                admin = dict(db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = json.dumps(["content_center"])

                def render(tab):
                    handler = object.__new__(app_module.CRMHandler)
                    handler.user = dict(admin)
                    handler.csrf = "content-dashboard-csrf"
                    handler.query = {"tab": [tab]}
                    handler.client_address = ("127.0.0.1", 10000)
                    handler.headers = {"User-Agent": "content-dashboard-test"}
                    handler.message = lambda: ("", "success")
                    captured = {}
                    handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                    handler.content_center("GET")
                    return captured["html"]

                html = render("dashboard")
                page_match = re.search(
                    r'<div class="content-centre-page">(?P<body>.*?)</div>\s*</main>',
                    html,
                    flags=re.S,
                )
                self.assertIsNotNone(page_match)
                page_body = page_match.group("body")
                self.assertEqual(html.count('class="content-centre-page"'), 1)
                self.assertIn('class="link-status-tabs content-tabs content-centre-tabs"', page_body)
                self.assertIn('class="content-workspace content-centre-dashboard"', page_body)
                tab_links = re.findall(r'href="(/content\?tab=[^"]+)"', page_body)
                self.assertEqual(tab_links[:6], [
                    "/content?tab=dashboard", "/content?tab=create", "/content?tab=extract",
                    "/content?tab=sync", "/content?tab=tracking", "/content?tab=analysis",
                ])
                self.assertEqual(page_body.count('class="metric content-metric"'), 3)
                self.assertEqual(page_body.count('method="get" action="/content"'), 1)
                filter_form = page_body.split('class="content-library-filter content-centre-filters"', 1)[1].split("</form>", 1)[0]
                field_names = re.findall(r'<(?:input|select)[^>]*\bname="([^"]+)"', filter_form)
                self.assertEqual(
                    field_names,
                    ["tab", "page", "q", "year", "month", "week", "category", "status", "sort_by", "sort_order"],
                )
                self.assertEqual(page_body.count('class="content-script-card"'), 5)
                self.assertEqual(page_body.count('method="post" action="/content/scripts/'), 10)
                self.assertEqual(page_body.count('name="action" value="set_recorded"'), 5)
                self.assertEqual(page_body.count('name="action" value="mark_published"'), 5)
                self.assertEqual(page_body.count('name="csrf" value="content-dashboard-csrf"'), 10)
                for status_class in (
                    "content-status-imported", "content-status-draft", "content-status-published",
                    "content-status-pending-recording", "content-status-recorded",
                ):
                    self.assertEqual(
                        page_body.count(f'content-script-card-status {status_class}"'),
                        1,
                    )
                self.assertIn("content-centre-empty-state", Path("app.py").read_text(encoding="utf-8"))
                self.assertEqual(render("create").count('class="content-centre-page"'), 0)
            finally:
                app_module.nas.status = old_nas_status
                app_module.db = old_db

