    def test_content_centre_work_tabs_premium_v2_render_contract_is_isolated(self):
        old_db = app_module.db
        old_nas_status = app_module.nas.status
        with tempfile.TemporaryDirectory() as folder:
            try:
                temp_root = Path(folder)
                database_path = temp_root / "database" / "aaie_crm.db"
                storage_root = temp_root / "storage"
                nas_root = temp_root / "nas"
                database_path.parent.mkdir()
                storage_root.mkdir()
                nas_root.mkdir()
                db = Database(database_path)
                db.initialize()
                app_module.db = db
                isolated_paths = assert_isolated_handler_environment(temp_root, storage_root, nas_root)
                self.assertEqual(isolated_paths["database"], str(database_path.resolve()))
                app_module.nas.status = lambda: {
                    "status": "ok",
                    "ready": True,
                    "root": str(nas_root.resolve()),
                }
                stamp = "2026-07-23T12:00:00+10:00"
                for index in range(55):
                    script_id = db.execute(
                        """INSERT INTO content_scripts(
                           title,body,category,status,created_at,updated_at
                           ) VALUES(?,?,?,?,?,?)""",
                        (
                            f"Long synthetic script title {index:02d} 无空格文本ABCDEFGHIJKLMNOPQRSTUVWXYZ",
                            f"Synthetic body {index}",
                            f"Long category {index:02d} 分类",
                            "Published" if index % 2 else "Draft",
                            stamp,
                            stamp,
                        ),
                    )
                    db.execute(
                        """INSERT INTO content_performance_metrics(
                           script_id,checkpoint,views,likes,saves,comments,shares,measured_at,
                           created_at,updated_at
                           ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                        (
                            script_id,
                            "post_day_7" if index % 2 else "post_day_3",
                            1000 + index,
                            100 + index,
                            50 + index,
                            10 + index,
                            5 + index,
                            stamp,
                            stamp,
                            stamp,
                        ),
                    )

                admin = dict(db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = json.dumps(["content_center"])
                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "content-work-tabs-csrf"
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "content-work-tabs-test"}
                handler.message = lambda: ("", "success")

                def render(tab):
                    handler.query = {"tab": [tab]}
                    captured = {}
                    handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                    handler.content_center("GET")
                    return captured["html"]

                def root_body(html, root):
                    match = re.search(
                        rf'<div class="{re.escape(root)}">(?P<body>.*?)</div>\s*</main>',
                        html,
                        flags=re.S,
                    )
                    self.assertIsNotNone(match)
                    return match.group("body")

                create_html = render("create")
                self.assertEqual(create_html.count('class="content-create-page"'), 1)
                create_body = root_body(create_html, "content-create-page")
                self.assertEqual(create_body.count('class="link-status-tabs content-tabs content-worktab-tabs"'), 1)
                self.assertEqual(create_body.count('<form'), 1)
                self.assertEqual(create_body.count('name="csrf" value="content-work-tabs-csrf"'), 1)
                create_form = create_body.split('<form', 1)[1].split('</form>', 1)[0]
                create_fields = re.findall(
                    r'<(?:input|select|textarea)[^>]*\bname="(?!csrf)([^"]+)"',
                    create_form,
                )
                self.assertEqual(create_fields, [
                    "title", "content_date", "planned_publish_date", "status",
                    "tags", "category", "notes", "body",
                ])
                self.assertRegex(create_form, r'<input\s+name="title"\s+required\b')
                self.assertNotIn('type="file"', create_form)
                self.assertNotIn('action="/content/generate"', create_body)
                self.assertNotIn('action="/content/published/', create_body)

                tracking_html = render("tracking")
                self.assertEqual(tracking_html.count('class="content-tracking-page"'), 1)
                tracking_body = root_body(tracking_html, "content-tracking-page")
                self.assertEqual(tracking_body.count('class="link-status-tabs content-tabs content-worktab-tabs"'), 1)
                self.assertEqual(tracking_body.count('<form'), 1)
                self.assertEqual(tracking_body.count('name="csrf" value="content-work-tabs-csrf"'), 1)
                tracking_form = tracking_body.split('<form', 1)[1].split('</form>', 1)[0]
                tracking_fields = re.findall(
                    r'<(?:input|select)[^>]*\bname="(?!csrf)([^"]+)"',
                    tracking_form,
                )
                self.assertEqual(tracking_fields, [
                    "script_ref", "checkpoint", "views", "likes", "saves", "comments", "shares",
                ])
                self.assertEqual(len(re.findall(r'<th(?:\s|>)', tracking_body)), 8)
                tracking_rows = tracking_body.split('<tbody>', 1)[1].split('</tbody>', 1)[0]
                self.assertEqual(tracking_rows.count('<tr>'), 50)

                analysis_html = render("analysis")
                self.assertEqual(analysis_html.count('class="content-analysis-page"'), 1)
                analysis_body = root_body(analysis_html, "content-analysis-page")
                self.assertEqual(analysis_body.count('class="link-status-tabs content-tabs content-worktab-tabs"'), 1)
                self.assertEqual(analysis_body.count('<form'), 0)
                self.assertEqual(analysis_body.count('name="csrf"'), 0)
                self.assertEqual(analysis_body.count('class="metric content-metric"'), 5)
                self.assertEqual(analysis_body.count('<table'), 2)
                analysis_bodies = re.findall(r'<tbody>(.*?)</tbody>', analysis_body, flags=re.S)
                self.assertEqual([body.count('<tr>') for body in analysis_bodies], [30, 20])
            finally:
                app_module.nas.status = old_nas_status
                app_module.db = old_db

