    def test_content_centre_work_tabs_premium_v2_static_business_boundaries(self):
        source = Path("app.py").read_text(encoding="utf-8")
        blocks = {
            "create": source[
                source.index("def content_create_panel(self):"):
                source.index("def content_generator_panel", source.index("def content_create_panel(self):"))
            ],
            "tracking": source[
                source.index("def content_performance_panel(self):"):
                source.index("def content_analysis_report_panel", source.index("def content_performance_panel(self):"))
            ],
            "analysis": source[
                source.index("def content_analysis_report_panel(self):"):
                source.index("def content_materials_panel", source.index("def content_analysis_report_panel(self):"))
            ],
        }
        center_block = source[
            source.index("def content_center(self, method):"):
            source.index("def content_create(self, method):", source.index("def content_center(self, method):"))
        ]
        self.assertEqual(center_block.count('"create": "content-create-page"'), 1)
        self.assertEqual(center_block.count('"tracking": "content-tracking-page"'), 1)
        self.assertEqual(center_block.count('"analysis": "content-analysis-page"'), 1)
        self.assertIn('class="{page_root}"', center_block)
        self.assertIn('method="post" action="/content/create"', blocks["create"])
        self.assertIn('method="post" action="/content/performance/create"', blocks["tracking"])
        self.assertIn("LIMIT 50", blocks["tracking"])
