    def test_file_manager_premium_v2_phase1_scopes_shared_views_and_preserves_navigation(self):
        old_db = app_module.db
        old_resolve = app_module.file_manager_resolve
        old_nas_status = app_module.nas.status
        old_student_lookup = app_module.file_manager_student_for_folder
        with tempfile.TemporaryDirectory() as folder:
            try:
                fixture_root = Path(folder) / "SYNTHETIC_FILE_MANAGER"
                fixture_root.mkdir()
                student_names = [
                    "A Very Long Synthetic Student Directory 20269999",
                    "Li Ming 20268888",
                ]
                for student_name in student_names:
                    student_root = fixture_root / student_name
                    student_root.mkdir()
                    for module_name in app_module.STANDARD_FOLDERS:
                        (student_root / module_name).mkdir()

                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas.status = lambda: {
                    "mounted": True,
                    "mode": "test",
                    "production_enabled": False,
                    "production_locked": True,
                    "root": str(fixture_root),
                    "root_error": "",
                    "ready": True,
                }

                def synthetic_resolve(year="", student="", folder="", file_name=""):
                    target = fixture_root
                    student_name = ""
                    module_name = ""
                    if student:
                        student_name = student
                        target = app_module.ensure_within(fixture_root / student_name, fixture_root)
                    if folder:
                        module_name = folder
                        target = app_module.ensure_within(target / module_name, fixture_root)
                    if file_name:
                        target = app_module.ensure_within(target / file_name, fixture_root)
                    return fixture_root, target, student_name, module_name

                app_module.file_manager_resolve = synthetic_resolve
                app_module.file_manager_student_for_folder = lambda path: {
                    "student_id": "20269999" if Path(path).name == student_names[0] else "20268888"
                }

                admin = dict(db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = json.dumps(["file_manager"])

                def render(query):
                    handler = object.__new__(app_module.CRMHandler)
                    handler.user = dict(admin)
                    handler.csrf = "file-manager-phase1-csrf"
                    handler.query = query
                    handler.client_address = ("127.0.0.1", 10000)
                    handler.headers = {"User-Agent": "file-manager-phase1-test"}
                    handler.message = lambda: ("", "success")
                    captured = {}
                    handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                    handler.file_manager("GET")
                    return captured["html"]

                def page_body(html):
                    self.assertEqual(html.count('class="file-manager-page"'), 1)
                    match = re.search(
                        r'<div class="file-manager-page">(?P<body>.*?)</div>\s*</main>',
                        html,
                        flags=re.S,
                    )
                    self.assertIsNotNone(match)
                    return match.group("body")

                root_body = page_body(render({}))
                self.assertEqual(root_body.count("<form"), 0)
                self.assertIn('class="fm-card-grid file-manager-root-grid"', root_body)
                self.assertIn('class="fm-card file-manager-folder-card"', root_body)
                self.assertIn(
                    f'href="/file-manager?year={fixture_root.name}"',
                    root_body,
                )

                student_body = page_body(render({"year": [fixture_root.name]}))
                self.assertEqual(student_body.count("<form"), 1)
                self.assertIn('class="search file-manager-search"', student_body)
                self.assertIn('class="fm-card-grid file-manager-folder-grid"', student_body)
                self.assertEqual(
                    student_body.count('class="fm-card file-manager-folder-card"'),
                    2,
                )
                student_positions = [
                    student_body.index(
                        f'href="/file-manager?year={fixture_root.name}&student={app_module.quote(student_name)}"'
                    )
                    for student_name in sorted(student_names, key=str.lower)
                ]
                self.assertEqual(student_positions, sorted(student_positions))

                selected_student = student_names[0]
                module_body = page_body(render({
                    "year": [fixture_root.name],
                    "student": [selected_student],
                }))
                self.assertEqual(module_body.count("<form"), 0)
                self.assertIn('class="fm-card-grid file-manager-folder-grid"', module_body)
                self.assertEqual(
                    module_body.count(
                        'class="fm-card file-manager-folder-card file-manager-module-card"'
                    ),
                    8,
                )
                module_links = re.findall(
                    r'href="(/file-manager\?year=[^"]+&student=[^"]+&folder=[^"]+)"',
                    module_body,
                )
                self.assertEqual(len(module_links), 8)
                self.assertEqual(
                    [app_module.unquote(link.rsplit("=", 1)[-1]) for link in module_links],
                    app_module.STANDARD_FOLDERS,
                )

                file_body = page_body(render({
                    "year": [fixture_root.name],
                    "student": [selected_student],
                    "folder": ["Applications"],
                }))
                self.assertEqual(file_body.count('class="file-manager-page"'), 0)
                self.assertIn("<table", file_body)
            finally:
                app_module.file_manager_student_for_folder = old_student_lookup
                app_module.nas.status = old_nas_status
                app_module.file_manager_resolve = old_resolve
                app_module.db = old_db

        app_source = Path("app.py").read_text(encoding="utf-8")
        file_manager_block = app_source[
            app_source.index("def file_manager_breadcrumb(self, year=\"\", student=\"\", folder=\"\"):"):
            app_source.index("def parent_links(self, method):")
        ]
        self.assertIn('(r"^/file-manager$", self.file_manager)', app_source)
        self.assertIn('(r"^/files$", self.file_manager)', app_source)
        self.assertNotIn('href="/files', file_manager_block)
        self.assertIn('class="fm-breadcrumb file-manager-breadcrumbs"', file_manager_block)
        self.assertIn('locked-note file-manager-nas-status', file_manager_block)

