    def test_vic_public_schools_accepting_year_7_plus_require_interview(self):
        handler = object.__new__(app_module.CRMHandler)
        vic_public_year7_plus = {
            "state": "VIC",
            "sector_key": "public",
            "school_type": "Public",
            "accepted_international_year_level_pattern": "Year7Plus",
            "accepted_international_year_levels": "[]",
            "international_year_level_min": "Unknown",
            "international_year_level_max": "Unknown",
            "interview_required": "Unknown",
        }
        vic_public_custom_year11 = {
            **vic_public_year7_plus,
            "accepted_international_year_level_pattern": "Custom",
            "accepted_international_year_levels": json.dumps(["Year 11", "Year 12"]),
        }
        vic_public_primary = {
            **vic_public_year7_plus,
            "accepted_international_year_level_pattern": "PrimaryOnly",
            "accepted_international_year_levels": "[]",
        }
        nsw_public_year7_plus = {**vic_public_year7_plus, "state": "NSW"}
        self.assertEqual(handler.school_effective_interview_required(vic_public_year7_plus), "Yes")
        self.assertEqual(handler.school_effective_interview_required(vic_public_custom_year11), "Yes")
        self.assertEqual(handler.school_effective_interview_required(vic_public_primary), "Unknown")
        self.assertEqual(handler.school_effective_interview_required(nsw_public_year7_plus), "No")

    def test_nsw_sa_qld_public_schools_do_not_require_interview(self):
        handler = object.__new__(app_module.CRMHandler)
        public_school = {
            "sector_key": "public",
            "school_type": "Public",
            "accepted_international_year_level_pattern": "Year7Plus",
            "accepted_international_year_levels": "[]",
            "international_year_level_min": "Unknown",
            "international_year_level_max": "Unknown",
            "interview_required": "Unknown",
        }
        for state in ("NSW", "SA", "QLD"):
            with self.subTest(state=state):
                self.assertEqual(handler.school_effective_interview_required({**public_school, "state": state}), "No")
                self.assertEqual(handler.school_effective_interview_required({**public_school, "state": state, "interview_required": "Yes"}), "No")
        self.assertEqual(
            handler.school_effective_interview_required({**public_school, "state": "NSW", "sector_key": "private", "school_type": "Private", "interview_required": "Yes"}),
            "Yes",
        )

    def test_template_management_premium_v2_preserves_list_page_contract(self):
        old_db = app_module.db
        old_nas_status = app_module.nas.status
        with tempfile.TemporaryDirectory() as folder:
            try:
                fixture_root = Path(folder)
                db = Database(fixture_root / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas.status = lambda: {
                    "mode": "test", "ready": True, "mounted": True,
                }
                admin = dict(db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = json.dumps(["template_management"])
                active_file = fixture_root / (
                    "Synthetic_Study_Abroad_Contract_Template_With_A_Very_Long_File_Name_V6.docx"
                )
                active_file.write_bytes(b"synthetic template fixture")
                missing_file = fixture_root / "Synthetic_Visa_Contract_Template_V5_Missing.docx"
                stamp = "2026-07-22T10:00:00+10:00"
                records = (
                    (
                        "study-v6", "Synthetic Study Abroad Contract Template With A Very Long Name",
                        "StudyAbroadContract", "Long synthetic description for visual wrapping.",
                        str(active_file), active_file.name, 6, 1,
                    ),
                    (
                        "visa-v5", "Synthetic Visa Contract Template", "VisaContract",
                        "Synthetic missing-file presentation sample.", str(missing_file),
                        missing_file.name, 5, 0,
                    ),
                )
                for key, name, contract_type, description, file_path, original_name, version, active in records:
                    db.execute(
                        """INSERT INTO template_records(
                           template_key,template_name,template_category,contract_type,description,
                           file_path,original_name,version,is_active,notes,created_by,created_at,
                           updated_by,updated_at
                           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (
                            key, name, "Contract", contract_type, description, file_path,
                            original_name, version, active, "Synthetic fixture", admin["id"],
                            stamp, admin["id"], stamp,
                        ),
                    )

                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "template-management-csrf"
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "template-management-test"}
                handler.message = lambda: ("", "success")
                captured = {}
                handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                handler.template_management("GET")
                html = captured["html"]

                self.assertEqual(html.count('class="template-management-page"'), 1)
                page_match = re.search(
                    r'<div class="template-management-page">(?P<body>.*?)</div>\s*</main>',
                    html,
                    flags=re.S,
                )
                self.assertIsNotNone(page_match)
                body = page_match.group("body")
                self.assertEqual(body.count('class="template-management-status-card'), 2)
                self.assertEqual(body.count('class="template-management-import-card'), 2)
                tbody_match = re.search(r"<tbody>(?P<body>.*?)</tbody>", body, flags=re.S)
                self.assertIsNotNone(tbody_match)
                self.assertEqual(tbody_match.group("body").count("<tr>"), 2)
                table_match = re.search(
                    r'<div class="table-wrap template-management-table-wrap">\s*<table>(?P<table>.*?)</table>',
                    body,
                    flags=re.S,
                )
                self.assertIsNotNone(table_match)
                self.assertEqual(table_match.group("table").count("<th>"), 8)
                self.assertEqual(body.count('method="post"'), 7)
                self.assertEqual(body.count('name="csrf" value="template-management-csrf"'), 7)
                self.assertEqual(body.count('action="/templates/create"'), 1)
                self.assertEqual(len(re.findall(r'action="/templates/\d+/update"', body)), 2)
                self.assertEqual(len(re.findall(r'action="/templates/\d+/replace"', body)), 2)
                self.assertEqual(len(re.findall(r'action="/templates/\d+/activate"', body)), 2)
                self.assertEqual(body.count('href="/templates/1/download"'), 2)
                self.assertEqual(body.count('href="/templates/1/edit-content"'), 1)
                self.assertIn("template-management-status-active", body)
                self.assertIn("template-management-status-standby", body)
                self.assertIn("template-management-status-coming-soon", body)
                self.assertIn("template-management-missing-file", body)
                self.assertIn(active_file.name, body)
                self.assertIn(missing_file.name, body)
            finally:
                app_module.nas.status = old_nas_status
                app_module.db = old_db

