    def test_template_management_premium_v2_css_is_strictly_scoped(self):
        app_source = Path("app.py").read_text(encoding="utf-8")
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        management_block = app_source[
            app_source.index("def template_management(self, method):"):
            app_source.index("def template_create(self, method):")
        ]
        editor_block = app_source[
            app_source.index("def template_edit_content(self, method, template_id):"):
            app_source.index("def template_edit_content_save(self, method, template_id):")
        ]
        self.assertEqual(management_block.count('class="template-management-page"'), 1)
        self.assertNotIn('class="template-management-page"', editor_block)

        start_marker = "/* Premium V2 Template Management Visual Map */"
        end_marker = "/* End Premium V2 Template Management Visual Map */"
        self.assertIn(start_marker, css)
        self.assertIn(end_marker, css)
        scoped_css = css.split(start_marker, 1)[1].split(end_marker, 1)[0]
        for selector in (
            ".ui-premium-v2 .template-management-page",
            ".ui-premium-v2 .template-management-page .template-management-header",
            ".ui-premium-v2 .template-management-page .template-management-status-grid",
            ".ui-premium-v2 .template-management-page .template-management-status-card",
            ".ui-premium-v2 .template-management-page .template-management-import-card",
            ".ui-premium-v2 .template-management-page .template-management-create-panel",
            ".ui-premium-v2 .template-management-page .template-management-list-panel",
            ".ui-premium-v2 .template-management-page .template-management-table-wrap",
            ".ui-premium-v2 .template-management-page .template-management-template-name",
            ".ui-premium-v2 .template-management-page .template-management-template-status",
            ".ui-premium-v2 .template-management-page .template-management-actions",
            ".ui-premium-v2 .template-management-page .template-management-missing-file",
        ):
            self.assertIn(selector, scoped_css)
        self.assertIn("overflow-x: auto", scoped_css)
        self.assertIn("overflow-wrap: anywhere", scoped_css)
        self.assertIn("@media (max-width: 760px)", scoped_css)
        self.assertIn("@media (max-width: 430px)", scoped_css)
        for selector in (".panel", "table", "form", "button", "input", ".status"):
            self.assertNotRegex(scoped_css, rf"(?m)^\s*{re.escape(selector)}(?:\s|,|\{{)")
        for protected_selector in (
            ".template-online-editor", ".contract-center", ".student-detail-page",
            ".parent-portal", ".contract-manual-placement-page",
            ".school-plan-reports-page", ".backup-control-page", ".file-manager-page",
        ):
            self.assertNotIn(protected_selector, scoped_css)

