    def test_user_detail_permissions_premium_v2_preserves_page_contract(self):
        old_db = app_module.db
        old_nas_status = app_module.nas.status
        with tempfile.TemporaryDirectory(dir="tmp") as folder:
            try:
                db = Database(Path(folder) / "aaie_crm.db")
                db.initialize()
                app_module.db = db
                app_module.nas.status = lambda: {"mode": "test", "ready": True}
                admin = dict(db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                role_id = db.one("SELECT id FROM roles WHERE name='Admin'")["id"]
                target_id = db.execute(
                    """INSERT INTO users(
                       username,display_name,email,password_hash,role_id,is_active,
                       must_change_password,created_at,last_login_at,last_login_ip,created_by
                       ) VALUES(?,?,?,?,?,0,1,?,?,?,?)""",
                    (
                        "detail-user-with-a-long-username", "Detail User With A Long Display Name",
                        "detail.user.with.a.long.email.address@example.test",
                        password_hash("TemporaryPass123!"), role_id,
                        "2026-07-22T12:00:00+10:00", "2026-07-22T12:30:00+10:00",
                        "2001:db8:85a3::8a2e:370:7334", admin["id"],
                    ),
                )
                app_module.save_user_module_permissions(
                    target_id,
                    [key for key, *_ in MODULE_DEFINITIONS],
                    admin["id"],
                    role_name="Admin",
                )
                for index in range(120):
                    db.audit(
                        {"id": target_id, "username": "detail-user-with-a-long-username"},
                        "login_success", "authentication", index,
                        ip="2001:db8:85a3::8a2e:370:7334",
                        device="Long Browser User Agent " + ("segment-" * 12) + str(index),
                    )
                for index in range(120):
                    db.audit(
                        {"id": target_id, "username": "detail-user-with-a-long-username"},
                        "user_detail_fixture_action", "user_management", index,
                        new_value="Long audit summary " + ("value-" * 18) + str(index),
                        ip="127.0.0.1",
                    )

                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "user-detail-csrf"
                handler.client_address = ("127.0.0.1", 10000)
                handler.headers = {"User-Agent": "user-detail-test"}
                handler.message = lambda: ("", "success")
                captured = {}
                handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                handler.user_detail("GET", target_id)
                html = captured["html"]

                self.assertEqual(html.count('class="user-detail-page"'), 1)
                page_match = re.search(
                    r'<div class="user-detail-page">(?P<body>.*?)</div>\s*</main>',
                    html,
                    flags=re.S,
                )
                self.assertIsNotNone(page_match)
                body = page_match.group("body")
                self.assertEqual(
                    re.findall(r'data-tab="([^"]+)"', body),
                    ["basic", "permissions", "logins", "actions"],
                )
                self.assertEqual(
                    re.findall(r'data-panel="([^"]+)"', body),
                    ["basic", "permissions", "logins", "actions"],
                )
                self.assertEqual(body.count('method="post"'), 2)
                self.assertEqual(body.count('name="csrf" value="user-detail-csrf"'), 2)
                self.assertEqual(body.count('type="checkbox" name="modules"'), len(MODULE_DEFINITIONS))
                self.assertIn(f'action="/users/{target_id}/profile"', body)
                self.assertIn(f'action="/users/{target_id}/permissions"', body)
                self.assertIn('href="/users"', body)
                self.assertIn("user-detail-status-disabled", body)
                self.assertIn("user-detail-role", body)

                login_panel = re.search(
                    r'data-panel="logins"(?P<body>.*?)data-panel="actions"', body, flags=re.S
                ).group("body")
                action_panel = re.search(
                    r'data-panel="actions"(?P<body>.*)$', body, flags=re.S
                ).group("body")
                self.assertEqual(login_panel.count("<tr>"), 101)
                self.assertEqual(action_panel.count("<tr>"), 201)
                for css_class in (
                    "user-detail-header", "user-detail-back-link", "user-detail-tabs",
                    "user-detail-tab", "user-detail-tab-panel", "user-detail-profile-panel",
                    "user-detail-profile-form", "user-detail-summary", "user-detail-role",
                    "user-detail-status", "user-detail-permissions-panel",
                    "user-detail-permission-toolbar", "user-detail-permission-matrix",
                    "user-detail-permission-save", "user-detail-login-panel",
                    "user-detail-login-table-wrap", "user-detail-audit-panel",
                    "user-detail-audit-table-wrap",
                ):
                    self.assertIn(css_class, body)
            finally:
                app_module.nas.status = old_nas_status
                app_module.db = old_db

