    def _upload_review_handler(self, user, form=None, query=None):
        handler = object.__new__(app_module.CRMHandler)
        handler.user = user
        handler.csrf = "csrf-119"
        handler.form = form or {}
        handler.files = []
        handler.query = query or {}
        handler.client_address = ("127.0.0.1", 11900)
        handler.headers = {"User-Agent": "safebox-119-isolated-regression"}
        handler.parsed = type("Parsed", (), {"path": "/isolated-upload-review"})()
        handler.response_status = None
        handler.response_headers = []
        handler.wfile = io.BytesIO()
        handler.send_response = lambda status: setattr(handler, "response_status", int(status))
        handler.send_header = lambda key, value: handler.response_headers.append((key, value))
        handler.end_headers = lambda: None
        handler.send_html = lambda content, status=200, headers=None: (
            setattr(handler, "response_status", int(status)),
            setattr(handler, "response_html", content),
        )
        handler.text = lambda value, status=200: (
            setattr(handler, "response_status", int(status)),
            setattr(handler, "response_text", str(value)),
        )
        handler.error_page = lambda message, status=400: (
            setattr(handler, "response_status", int(status)),
            setattr(handler, "response_text", str(message)),
        )
        handler.deny_module_access = lambda _module: handler.error_page("Access denied", 403)
        handler.flash_redirect = lambda location, message, kind="success": (
            setattr(handler, "redirect_location", location),
            setattr(handler, "redirect_message", message),
            setattr(handler, "redirect_kind", kind),
        )
        return handler

    def _create_isolated_review(self, env, module, files, form=None, user=None):
        uploads = [
            Upload("files", filename, content_type, payload)
            for filename, content_type, payload in files
        ]
        return app_module.create_upload_review(
            env["student_id"], module, uploads, user or env["admin"], form or {}
        )

    def _confirm_isolated_review(self, env, token, module, document_types, form=None, user=None):
        payload = dict(form or {})
        for index, document_type in enumerate(document_types):
            payload[f"confirm_item_{index}"] = "1"
            payload[f"document_type_{index}"] = document_type
        handler = self._upload_review_handler(user or env["admin"], payload)
        handler.upload_review_confirm("POST", env["student_id"], token)
        return handler

