    def test_generic_upload_review_behavior_group_1_paths_permissions_csrf_and_tokens(self):
        with isolated_upload_review_regression_environment("group-1") as env:
            for required in (
                "database_path", "storage_root", "staging_root", "preview_cache_root",
                "ocr_work_root", "swift_cache_root", "nas_root", "sessions", "logs",
                "fixtures", "reports",
            ):
                path = Path(env["paths"][required]).resolve()
                self.assertIn(env["root"], path.parents)
            self.assertEqual(Path(app_module.db.path).resolve(), Path(env["paths"]["database_path"]).resolve())

            tokens = {
                self._create_isolated_review(
                    env, "Applications", [(f"token-{index}.pdf", "application/pdf", b"%PDF isolated")]
                )
                for index in range(3)
            }
            self.assertEqual(len(tokens), 3)
            self.assertTrue(all(re.fullmatch(r"[A-Za-z0-9_]+", token) for token in tokens))

            manager = {"id": 2, "username": "manager", "role_name": "Manager", "permissions_json": '["documents.manage"]'}
            consultant = {"id": 3, "username": "consultant", "role_name": "Consultant", "permissions_json": '["offers.manage"]'}
            visa_officer = {"id": 4, "username": "visa", "role_name": "Visa Officer", "permissions_json": '["coe.manage"]'}
            no_access = {"id": 5, "username": "none", "role_name": "View Only", "permissions_json": "[]", "module_permissions_json": "[]"}
            view_only = {"id": 6, "username": "view", "role_name": "View Only", "permissions_json": "[]", "module_permissions_json": '["applications"]'}
            env["db"].execute(
                """INSERT INTO users(id,username,display_name,password_hash,role_id,created_at)
                   VALUES(?,?,?,?,7,?)""",
                (6, "view", "View", "hash", "2026-07-23T10:00:00+10:00"),
            )
            env["db"].execute(
                """INSERT INTO user_module_permissions(user_id,module_key,can_access,can_view,can_confirm_upload_review,created_at,updated_at)
                   VALUES(6,'applications',1,1,0,?,?)""",
                ("2026-07-23T10:00:00+10:00", "2026-07-23T10:00:00+10:00"),
            )
            self.assertTrue(app_module.can_review_module_action(env["admin"], "Applications", "confirm"))
            self.assertTrue(app_module.can_review_module_action(manager, "Applications", "confirm"))
            self.assertTrue(app_module.can_review_module_action(consultant, "Offer", "confirm"))
            self.assertTrue(app_module.can_review_module_action(visa_officer, "COE + OSHC", "confirm"))
            self.assertFalse(app_module.can_review_module_action(no_access, "Applications", "view"))
            self.assertTrue(app_module.can_review_module_action(view_only, "Applications", "view"))
            self.assertFalse(app_module.can_review_module_action(view_only, "Applications", "confirm"))

            for value, expected in (("csrf-119", True), ("wrong", False), ("", False)):
                handler = self._upload_review_handler(env["admin"])
                body = f"csrf={value}".encode("utf-8")
                handler.headers = {
                    "Content-Type": "application/x-www-form-urlencoded",
                    "Content-Length": str(len(body)),
                }
                handler.rfile = io.BytesIO(body)
                self.assertEqual(handler.check_csrf(), expected)

            token = next(iter(tokens))
            for value in ("wrong", ""):
                handler = self._upload_review_handler(env["admin"])
                handler.path = f"/students/{env['student_id']}/upload-review/{token}/confirm"
                handler.server = type("Server", (), {"service_mode": "admin"})()
                handler.current_user = lambda: (env["admin"], "csrf-119")
                body = f"csrf={value}".encode("utf-8")
                handler.headers = {
                    "Content-Type": "application/x-www-form-urlencoded",
                    "Content-Length": str(len(body)),
                }
                handler.rfile = io.BytesIO(body)
                with mock.patch.object(app_module, "maybe_run_auto_backup", return_value=None):
                    handler.dispatch("POST")
                self.assertEqual(handler.response_status, 403)

    def test_generic_upload_review_behavior_group_2_get_preview_download_and_stubs(self):
        with isolated_upload_review_regression_environment("group-2") as env:
            files = [
                ("sample.pdf", "application/pdf", b"%PDF-1.4 isolated"),
                ("sample.docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", b"docx"),
                ("sample.jpg", "image/jpeg", b"jpg"),
                ("sample.jpeg", "image/jpeg", b"jpeg"),
                ("sample.png", "image/png", b"png"),
                ("sample.heic", "image/heic", b"heic"),
                ("sample.doc", "application/msword", b"doc"),
                ("empty.bin", "application/octet-stream", b""),
                ("Unicode-测试-" + "x" * 120 + ".pdf", "application/pdf", b"%PDF long"),
                ("preview-boundary-24mib.pdf", "application/pdf", b"%PDF" + b"0" * (24 * 1024 * 1024 - 4)),
            ]
            token = self._create_isolated_review(env, "Offer", files)
            session_id = env["db"].one("SELECT id FROM upload_sessions WHERE session_token=?", (token,))["id"]
            env["db"].execute(
                """INSERT INTO sessions(token,user_id,csrf_token,expires_at,created_at,last_seen_at)
                   VALUES('session-119',1,'csrf-119','2099-01-01T00:00:00+10:00',?,?)""",
                ("2026-07-23T09:00:00+10:00", "2026-07-23T09:00:00+10:00"),
            )
            user = dict(env["admin"], _session_token="session-119")
            extracted = []

            def extractor_stub(upload, module, doc_type=""):
                extracted.append((upload.filename, module, doc_type))
                return {
                    "text_found": False,
                    "source": "stub OCR unavailable; manual confirmation required",
                    "document_type": doc_type,
                    "detected_document_type": "",
                    "text_extraction": {"extracted_text_available": False, "ocr_fallback_used": True},
                    "matched_keywords": [],
                    "fields": {
                        field: {"value": "", "status": "needs_review", "message": "manual confirmation", "snippet": ""}
                        for field in app_module.OFFER_EXTRACTION_FIELDS
                    },
                    "program_segments": [],
                }

            old_extractor = app_module.extraction_review_data
            old_suggested = app_module.suggested_review_document_type
            old_pdf_count = app_module.pdf_page_count
            try:
                app_module.extraction_review_data = extractor_stub
                app_module.suggested_review_document_type = lambda _upload, _module: "Offer"
                handler = self._upload_review_handler(user)
                before_items = [dict(row) for row in env["db"].all("SELECT * FROM upload_review_items ORDER BY id")]
                handler.touch_current_session()
                handler.upload_review("GET", env["student_id"], token)
                self.assertEqual(handler.response_status, 200)
                self.assertIn("manual confirmation", handler.response_html)
                self.assertEqual(len(extracted), len(files))
                self.assertNotEqual(
                    env["db"].one("SELECT last_seen_at FROM sessions WHERE token='session-119'")["last_seen_at"],
                    "2026-07-23T09:00:00+10:00",
                )
                self.assertEqual(
                    [dict(row) for row in env["db"].all("SELECT * FROM upload_review_items ORDER BY id")],
                    before_items,
                )
                self.assertEqual(env["db"].one(
                    "SELECT COUNT(*) count FROM audit_logs WHERE action_type='upload_review_opened' AND record_id=?",
                    (session_id,),
                )["count"], 1)
                self.assertIn("upload_review_document_type_detected", (env["paths"]["logs"] / "admin.log").read_text(encoding="utf-8"))
                handler.log_message('"%s %s" %s', "GET", handler.parsed.path, 200)
                self.assertIn(
                    '"GET /isolated-upload-review" 200',
                    (env["paths"]["logs"] / "access.log").read_text(encoding="utf-8"),
                )

                app_module.pdf_page_count = lambda _data, max_pages=None: 12
                for index, (_name, _content_type, payload) in enumerate(files):
                    preview = self._upload_review_handler(env["admin"], query={"size": ["large"], "page": ["9"]})
                    preview.upload_review_preview("GET", env["student_id"], token, str(index))
                    self.assertEqual(preview.response_status, 200)
                    self.assertTrue(preview.wfile.getvalue())
                    download = self._upload_review_handler(env["admin"])
                    download.upload_review_download("GET", env["student_id"], token, str(index))
                    self.assertEqual(download.response_status, 200)
                    self.assertEqual(download.wfile.getvalue(), payload)
                self.assertTrue(any(Path(env["paths"]["preview_cache_root"]).iterdir()))

                wrong_student = self._upload_review_handler(env["admin"])
                wrong_student.upload_review_download("GET", "WRONG", token, "0")
                self.assertEqual(wrong_student.response_status, 404)
                with self.assertRaisesRegex(ValueError, "已失效或不存在"):
                    app_module.load_upload_review("missing-token")

                folder, metadata = app_module.load_upload_review(token)
                Path(metadata["files"][0]["blob"] and folder / metadata["files"][0]["blob"]).unlink()
                with self.assertRaises(FileNotFoundError):
                    self._upload_review_handler(env["admin"]).upload_review_download(
                        "GET", env["student_id"], token, "0"
                    )
                outside = env["root"] / "fixtures" / "outside.bin"
                outside.write_bytes(b"outside")
                escaped = folder / metadata["files"][1]["blob"]
                escaped.unlink()
                escaped.symlink_to(outside)
                with self.assertRaises(NasSafetyError):
                    app_module.upload_from_review(folder, metadata["files"][1])
            finally:
                app_module.extraction_review_data = old_extractor
                app_module.suggested_review_document_type = old_suggested
                app_module.pdf_page_count = old_pdf_count

