    def test_school_new_duplicate_warning_requires_existing_confirmation(self):
        with isolated_school_new_regression_environment("duplicate-warning") as env:
            env["db"].execute(
                """UPDATE schools SET school_name='Synthetic Existing Duplicate',
                   school_name_english='Synthetic Existing Duplicate',
                   school_name_display='Synthetic Existing Duplicate',
                   address='1 Duplicate Street, Melbourne VIC 3000',
                   website_url='https://example.invalid/duplicate-school',
                   state='VIC',suburb='Melbourne',postcode='3000',deleted_at=NULL
                   WHERE id=1"""
            )
            form = self._school_new_form(
                env["users"]["admin"]["csrf"],
                "Synthetic Candidate Duplicate",
                "Public",
            )
            form["address"] = "1 Duplicate Street, Melbourne VIC 3000"
            form["website_url"] = "https://example.invalid/duplicate-school"
            before = env["db"].one("SELECT COUNT(*) count FROM schools")["count"]
            with self._school_detail_http_server(env, port=18806):
                conflict = self._school_new_http_request(
                    18806, env["users"]["admin"], "/schools/new", "POST", form
                )
                self.assertEqual(conflict[0], 409)
                self.assertIn("confirm_duplicate", conflict[2].decode("utf-8"))
                self.assertEqual(env["db"].one("SELECT COUNT(*) count FROM schools")["count"], before)
                confirmed = self._school_new_http_request(
                    18806,
                    env["users"]["admin"],
                    "/schools/new",
                    "POST",
                    dict(form, confirm_duplicate="yes"),
                )
            self.assertEqual(confirmed[0], 303)
            self.assertEqual(env["db"].one("SELECT COUNT(*) count FROM schools")["count"], before + 1)

    def test_school_new_valid_logo_stays_inside_synthetic_nas(self):
        with isolated_school_new_regression_environment("valid-logo") as env:
            with self._school_detail_http_server(env, port=18806):
                for extension, image_format, content_type, school_name in (
                    ("png", "PNG", "image/png", "Alpha PNG Logo School New"),
                    ("jpg", "JPEG", "image/jpeg", "Bravo JPG Logo School New"),
                    ("webp", "WEBP", "image/webp", "Charlie WEBP Logo School New"),
                ):
                    with self.subTest(extension=extension):
                        output = io.BytesIO()
                        Image.new("RGB", (80, 60), "#315bef").save(output, format=image_format)
                        form = self._school_new_form(
                            env["users"]["admin"]["csrf"],
                            school_name,
                            "Private",
                        )
                        status, _headers, _payload = self._school_new_http_request(
                            18806,
                            env["users"]["admin"],
                            "/schools/new",
                            "POST",
                            form,
                            [
                                (
                                    "logo_file",
                                    f"synthetic-logo.{extension}",
                                    content_type,
                                    output.getvalue(),
                                )
                            ],
                        )
                        self.assertEqual(status, 303)
                        school = env["db"].one(
                            "SELECT * FROM schools WHERE school_name_english=?",
                            (school_name,),
                        )
                        logo_path = Path(school["logo_file_path"]).resolve()
                        self.assertIn(env["nas"].resolve(), logo_path.parents)
                        self.assertTrue(logo_path.is_file())
                        original_files = [
                            path for path in (logo_path.parent / "Original").glob("*")
                            if not path.name.startswith("._")
                        ]
                        self.assertEqual(len(original_files), 1)
                        self.assertIn(env["nas"].resolve(), original_files[0].resolve().parents)
                        with Image.open(logo_path) as image:
                            self.assertEqual(image.size, (512, 512))

    def test_school_new_csrf_and_role_permissions_remain_unchanged(self):
        with isolated_school_new_regression_environment("csrf-permissions") as env:
            before = env["db"].one("SELECT COUNT(*) count FROM schools")["count"]
            with self._school_detail_http_server(env, port=18806):
                for label, csrf in (("missing", None), ("wrong", "wrong-csrf")):
                    form = self._school_new_form(
                        env["users"]["admin"]["csrf"],
                        f"Synthetic {label.title()} CSRF School",
                    )
                    if csrf is None:
                        form.pop("csrf")
                    else:
                        form["csrf"] = csrf
                    self.assertEqual(
                        self._school_new_http_request(
                            18806, env["users"]["admin"], "/schools/new", "POST", form
                        )[0],
                        403,
                    )
                for role in ("consultant", "visa", "no_access"):
                    user = env["users"][role]
                    form = self._school_new_form(
                        user["csrf"],
                        f"Synthetic Denied {role.title()} School",
                    )
                    self.assertEqual(
                        self._school_new_http_request(
                            18806, user, "/schools/new", "POST", form
                        )[0],
                        403,
                    )
                manager_form = self._school_new_form(
                    env["users"]["manager"]["csrf"],
                    "Synthetic Allowed Manager School",
                )
                manager_result = self._school_new_http_request(
                    18806, env["users"]["manager"], "/schools/new", "POST", manager_form
                )
            self.assertEqual(manager_result[0], 303)
            self.assertEqual(env["db"].one("SELECT COUNT(*) count FROM schools")["count"], before + 1)
            self.assertEqual(
                env["db"].one(
                    "SELECT COUNT(*) count FROM audit_logs WHERE action_type='school_access_denied'"
                )["count"],
                2,
            )
            self.assertEqual(
                env["db"].one(
                    "SELECT COUNT(*) count FROM audit_logs WHERE action_type='access_denied'"
                )["count"],
                1,
            )

    def test_school_new_existing_partial_success_failure_boundaries_are_preserved(self):
        failure_specs = (
            ("city", "INSERT INTO school_cities", "Synthetic Failure City", 0),
            ("school", "INSERT INTO schools(", "Melbourne", 0),
            ("extension", "UPDATE schools SET accommodation_type", "Melbourne", 1),
        )
        for label, needle, city, expected_school_delta in failure_specs:
            with self.subTest(label=label):
                with isolated_school_new_regression_environment(f"failure-{label}") as env:
                    form = self._school_new_form(
                        env["users"]["admin"]["csrf"],
                        f"Synthetic {label.title()} Failure School",
                    )
                    form["city"] = city
                    before = env["db"].one("SELECT COUNT(*) count FROM schools")["count"]
                    original_execute = env["db"].execute

                    def fail_selected(sql, params=(), *, _needle=needle):
                        if _needle.lower() in " ".join(str(sql).split()).lower():
                            raise sqlite3.OperationalError(f"synthetic {_needle} failure")
                        return original_execute(sql, params)

                    with mock.patch.object(env["db"], "execute", side_effect=fail_selected):
                        with self._school_detail_http_server(env, port=18806):
                            result = self._school_new_http_request(
                                18806, env["users"]["admin"], "/schools/new", "POST", form
                            )
                    self.assertEqual(result[0], 500)
                    self.assertEqual(
                        env["db"].one("SELECT COUNT(*) count FROM schools")["count"],
                        before + expected_school_delta,
                    )

        with isolated_school_new_regression_environment("failure-directory") as env:
            form = self._school_new_form(
                env["users"]["admin"]["csrf"], "Synthetic Directory Failure School"
            )
            with mock.patch.object(
                app_module.CRMHandler,
                "school_file_folder",
                side_effect=OSError("synthetic directory failure"),
            ):
                with self._school_detail_http_server(env, port=18806):
                    result = self._school_new_http_request(
                        18806, env["users"]["admin"], "/schools/new", "POST", form
                    )
            self.assertEqual(result[0], 303)
            self.assertEqual(
                env["db"].one(
                    "SELECT COUNT(*) count FROM audit_logs WHERE action_type='school_folder_create_failed'"
                )["count"],
                1,
            )

        with isolated_school_new_regression_environment("failure-logo") as env:
            form = self._school_new_form(
                env["users"]["admin"]["csrf"], "Synthetic Logo Failure School"
            )
            with self._school_detail_http_server(env, port=18806):
                result = self._school_new_http_request(
                    18806,
                    env["users"]["admin"],
                    "/schools/new",
                    "POST",
                    form,
                    [("logo_file", "invalid-logo.png", "image/png", b"not-an-image")],
                )
            self.assertEqual(result[0], 303)
            school = env["db"].one(
                "SELECT * FROM schools WHERE school_name_english='Synthetic Logo Failure School'"
            )
            self.assertIsNotNone(school)
            self.assertIn(school["logo_file_path"], (None, ""))
            self.assertEqual(
                len([
                    path
                    for path in (
                        env["nas"] / "VIC" / "Synthetic Logo Failure School" / "Logo" / "Original"
                    ).glob("*")
                    if not path.name.startswith("._")
                ]),
                1,
            )

        with isolated_school_new_regression_environment("failure-audit") as env:
            form = self._school_new_form(
                env["users"]["admin"]["csrf"], "Synthetic Audit Failure School"
            )
            original_audit = env["db"].audit

            def fail_school_created(user, action, *args, **kwargs):
                if action == "school_created":
                    raise RuntimeError("synthetic school audit failure")
                return original_audit(user, action, *args, **kwargs)

            with mock.patch.object(env["db"], "audit", side_effect=fail_school_created):
                with self._school_detail_http_server(env, port=18806):
                    result = self._school_new_http_request(
                        18806, env["users"]["admin"], "/schools/new", "POST", form
                    )
            self.assertEqual(result[0], 500)
            self.assertIsNotNone(env["db"].one(
                "SELECT id FROM schools WHERE school_name_english='Synthetic Audit Failure School'"
            ))

        with isolated_school_new_regression_environment("failure-source-tracking") as env:
            form = self._school_new_form(
                env["users"]["admin"]["csrf"], "Synthetic Source Failure School"
            )
            with mock.patch.object(
                app_module.CRMHandler,
                "school_record_source",
                side_effect=RuntimeError("synthetic source tracking failure"),
            ):
                with self._school_detail_http_server(env, port=18806):
                    result = self._school_new_http_request(
                        18806, env["users"]["admin"], "/schools/new", "POST", form
                    )
            self.assertEqual(result[0], 500)
            school = env["db"].one(
                "SELECT id FROM schools WHERE school_name_english='Synthetic Source Failure School'"
            )
            self.assertIsNotNone(school)
            self.assertEqual(
                env["db"].one(
                    "SELECT COUNT(*) count FROM school_source_tracking WHERE school_id=?",
                    (school["id"],),
                )["count"],
                0,
            )

    def test_school_detail_premium_v2_phase1_render_contract_is_isolated(self):
        old_db = app_module.db
        old_nas = app_module.nas
        old_school_root = app_module.SCHOOL_LIBRARY_FILE_DIR
        production_db = Path(app_module.DB_PATH).resolve()
        production_school_root = Path("/Volumes/Server/Schools/CRM_Schools").resolve()
        production_student_root = Path("/Volumes/Server/Students").resolve()

        with tempfile.TemporaryDirectory(dir="tmp") as folder:
            root = Path(folder).resolve()
            database_path = root / "database" / "preview.db"
            storage_root = root / "storage"
            nas_root = root / "synthetic_nas"
            database_path.parent.mkdir(parents=True)
            storage_root.mkdir()
            nas_root.mkdir()

            class SyntheticSchoolNas:
                def status(self):
                    return {
                        "mounted": True,
                        "mode": "test",
                        "production_enabled": False,
                        "production_locked": True,
                        "root": str(nas_root),
                        "root_error": "",
                        "ready": True,
                    }

            try:
                app_module.db = Database(database_path)
                app_module.nas = SyntheticSchoolNas()
                app_module.SCHOOL_LIBRARY_FILE_DIR = nas_root

                resolved_paths = {
                    "database": Path(app_module.db.path).resolve(),
                    "storage": storage_root.resolve(),
                    "nas": Path(app_module.SCHOOL_LIBRARY_FILE_DIR).resolve(),
                }
                for resolved in resolved_paths.values():
                    self.assertTrue(resolved == root or root in resolved.parents)
                    self.assertNotEqual(resolved, production_db)
                    self.assertNotEqual(resolved, production_school_root)
                    self.assertNotEqual(resolved, production_student_root)
                    self.assertNotIn(production_school_root, resolved.parents)
                    self.assertNotIn(production_student_root, resolved.parents)

                app_module.db.initialize()
                school_id = 3
                school_folder = nas_root / "VIC" / "Synthetic School"
                document_folder = school_folder / "Documents"
                logo_folder = school_folder / "Logo"
                document_folder.mkdir(parents=True)
                logo_folder.mkdir(parents=True)
                logo_path = logo_folder / "synthetic-logo.png"
                logo_path.write_bytes(b"synthetic-logo")
                document_names = (
                    "Synthetic Prospectus.pdf",
                    "A-very-long-school-document-name-withoutspaces-2026.pdf",
                    "Unicode-学校资料.pdf",
                )
                app_module.db.execute(
                    """UPDATE schools SET
                           school_name=?,school_name_english=?,school_name_display=?,
                           address=?,website_url=?,notes=?,dynamic_tags_json=?,
                           logo_file_path=?,logo_status='manually_uploaded',updated_at=?
                       WHERE id=?""",
                    (
                        "Synthetic International College with an Extended Campus Name",
                        "Synthetic International College with an Extended Campus Name",
                        "Synthetic International College with an Extended Campus Name",
                        "123 A Very Long Synthetic Address, Melbourne VIC 3000, Australia",
                        "https://example.invalid/a/very/long/synthetic/school/path/without/business-effects",
                        "这是一段仅用于隔离视觉验证的长备注。 " * 8,
                        json.dumps(["学术支持", "国际学生", "Performing Arts", "STEM"], ensure_ascii=False),
                        str(logo_path),
                        "2026-07-23T11:00:00+10:00",
                        school_id,
                    ),
                )
                for index, name in enumerate(document_names, start=1):
                    path = document_folder / name
                    path.write_bytes(f"synthetic-{index}".encode("ascii"))
                    app_module.db.execute(
                        """INSERT INTO school_documents(
                               school_id,document_type,original_filename,stored_filename,
                               file_path,file_size,notes,uploaded_by,uploaded_at
                           ) VALUES(?,?,?,?,?,?,?,?,?)""",
                        (
                            school_id, "Brochure", name, name, str(path), path.stat().st_size,
                            "Synthetic visual sample", 1, "2026-07-23T11:00:00+10:00",
                        ),
                    )

                admin = dict(app_module.db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = app_module.modules_json_for_user(admin["id"])

                def render(query):
                    handler = object.__new__(app_module.CRMHandler)
                    handler.user = admin
                    handler.csrf = "school-detail-phase1-csrf"
                    handler.query = query
                    handler.client_address = ("127.0.0.1", 12000)
                    handler.headers = {"User-Agent": "school-detail-phase1-isolated"}
                    handler.message = lambda: ("", "success")
                    captured = {}
                    handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                    handler.school_detail("GET", school_id)
                    return captured["html"]

                view_html = render({})
                edit_html = render({"mode": ["edit"]})
                for html in (view_html, edit_html):
                    self.assertEqual(html.count('class="school-detail-page"'), 1)
                    page_match = re.search(
                        r'<div class="school-detail-page">(?P<body>.*?)</div>\s*</main>',
                        html,
                        flags=re.S,
                    )
                    self.assertIsNotNone(page_match)
                    page_body = page_match.group("body")
                    self.assertIn('href="/schools/library"', page_body)
                    self.assertIn("school-detail-header", page_body)
                    self.assertIn("school-detail-actions", page_body)
                    self.assertIn("school-detail-status", page_body)
                    self.assertIn("school-detail-summary", page_body)
                    self.assertIn("school-detail-title", page_body)
                    self.assertIn("school-detail-grid", page_body)
                    self.assertIn("school-detail-documents", page_body)
                    self.assertIn("school-detail-danger-zone", page_body)
                    self.assertEqual(page_body.count("?download=1"), len(document_names))
                    self.assertEqual(page_body.count('target="_blank"'), len(document_names))
                    self.assertEqual(page_body.count('name="document_ids"'), len(document_names))
                    self.assertNotIn("school-detail-map", page_body)
                    self.assertNotIn("school-detail-chart", page_body)

                view_body = re.search(
                    r'<div class="school-detail-page">(?P<body>.*?)</div>\s*</main>',
                    view_html,
                    flags=re.S,
                ).group("body")
                edit_body = re.search(
                    r'<div class="school-detail-page">(?P<body>.*?)</div>\s*</main>',
                    edit_html,
                    flags=re.S,
                ).group("body")
                self.assertEqual(view_body.count("<form"), 4)
                self.assertEqual(view_body.count('name="csrf"'), 4)
                self.assertEqual(edit_body.count("<form"), 14)
                self.assertEqual(edit_body.count('name="csrf"'), 14)
                self.assertEqual(view_body.count('action="/schools/3/delete"'), 1)
                self.assertEqual(edit_body.count('action="/schools/3/delete"'), 1)
                self.assertEqual(view_body.count('href="/schools/3?mode=edit#basic"'), 1)
                self.assertEqual(edit_body.count('href="/schools/3"'), 1)
            finally:
                app_module.SCHOOL_LIBRARY_FILE_DIR = old_school_root
                app_module.nas = old_nas
                app_module.db = old_db

    def test_school_detail_premium_v2_phase1_css_is_strictly_scoped(self):
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        start_marker = "/* Premium V2 School Detail Phase 1 */"
        end_marker = "/* End Premium V2 School Detail Phase 1 */"
        self.assertIn(start_marker, css)
        self.assertIn(end_marker, css)
        scoped_css = css.split(start_marker, 1)[1].split(end_marker, 1)[0]
        for selector in (
            ".ui-premium-v2 .school-detail-page",
            ".ui-premium-v2 .school-detail-page .school-detail-header",
            ".ui-premium-v2 .school-detail-page .school-detail-actions",
            ".ui-premium-v2 .school-detail-page .school-detail-summary",
            ".ui-premium-v2 .school-detail-page .school-detail-title",
            ".ui-premium-v2 .school-detail-page .school-detail-grid",
            ".ui-premium-v2 .school-detail-page .school-detail-documents",
            ".ui-premium-v2 .school-detail-page .school-detail-danger-zone",
        ):
            self.assertIn(selector, scoped_css)
        self.assertIn("overflow-wrap: anywhere", scoped_css)
        self.assertIn("overflow-x: auto", scoped_css)
        self.assertIn("@media (max-width: 760px)", scoped_css)
        self.assertIn("@media (max-width: 430px)", scoped_css)
        for selector in (
            ".ui-premium-v2 form",
            ".ui-premium-v2 input",
            ".ui-premium-v2 select",
            ".ui-premium-v2 textarea",
            ".ui-premium-v2 button",
            ".ui-premium-v2 table",
            ".ui-premium-v2 .panel",
            ".ui-premium-v2 .school-card",
            ".ui-premium-v2 .school-section",
        ):
            self.assertNotRegex(scoped_css, rf"(?m)^\s*{re.escape(selector)}(?:\s|,|\{{)")
        for protected_selector in (
            ".schools-page", ".school-library-page", ".school-new-page",
            ".school-radius-page", ".school-plan-reports-page",
            ".school-collection-page", ".signedoffer-institution-mapping-review-page",
            ".parent-portal",
        ):
            self.assertNotIn(protected_selector, scoped_css)

    def _school_detail_http_request(self, port, user, path, method="GET", form=None):
        body = urlencode(form or {}, doseq=True).encode("utf-8") if method == "POST" else None
        headers = {
            "Cookie": f"aaie_session={user['token']}",
            "User-Agent": "safebox-120-school-detail-isolated",
        }
        if body is not None:
            headers["Content-Type"] = "application/x-www-form-urlencoded"
            headers["Content-Length"] = str(len(body))
        connection = http.client.HTTPConnection("127.0.0.1", port, timeout=10)
        try:
            connection.request(method, path, body=body, headers=headers)
            response = connection.getresponse()
            return response.status, dict(response.getheaders()), response.read()
        finally:
            connection.close()

    @contextmanager
    def _school_detail_http_server(self, env, port=18804):
        backup_calls = []
        server = app_module.ReusableThreadingHTTPServer(("127.0.0.1", port), app_module.CRMHandler)
        server.service_mode = "admin"
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        with mock.patch.object(
            app_module,
            "maybe_run_auto_backup",
            side_effect=lambda: backup_calls.append("checked"),
        ), mock.patch.object(app_module.urllib.request, "urlopen", side_effect=AssertionError("external URL access blocked")):
            thread.start()
            try:
                yield {"port": port, "backup_calls": backup_calls}
            finally:
                server.shutdown()
                server.server_close()
                thread.join(timeout=5)
                self.assertFalse(thread.is_alive())

