    def test_school_detail_sector_key_save_without_form_field_uses_existing_school_type_mapping(self):
        with isolated_school_detail_regression_environment("sector-save-mapping") as env:
            mapping_path = Path("config/signedoffer_institution_reviewed_mappings_v1.json")
            mapping_before = mapping_path.read_bytes()
            env["db"].execute(
                "UPDATE schools SET sector_key='private',school_type='Private',notes='Preserved existing note' WHERE id=3"
            )
            before_school = dict(env["db"].one("SELECT * FROM schools WHERE id=3"))
            protected_before = {
                table: env["db"].one(f"SELECT COUNT(*) count FROM {table}")["count"]
                for table in (
                    "school_documents", "school_plan_reports", "school_collection_drafts",
                    "school_academic_rankings", "workflow_status", "reminders",
                )
            }
            nas_before = sorted(
                (str(path.relative_to(env["nas"])), path.stat().st_size, hashlib.sha256(path.read_bytes()).hexdigest())
                for path in env["nas"].rglob("*") if path.is_file() and not path.is_symlink()
            )

            with self._school_detail_http_server(env) as server:
                edit_status, _edit_headers, edit_payload = self._school_detail_http_request(
                    server["port"], env["users"]["manager"], "/schools/3?mode=edit"
                )
                self.assertEqual(edit_status, 200)
                basic_form = re.search(
                    r'<form class="stack-form" method="post" action="/schools/3/basic".*?</form>',
                    edit_payload.decode("utf-8"),
                    flags=re.S,
                ).group(0)
                self.assertIn('name="school_type"', basic_form)
                self.assertNotIn('name="sector_key"', basic_form)

                form = self._school_detail_sector_key_save_form(env["users"]["manager"]["csrf"], "Private")
                self.assertNotIn("sector_key", form)
                status, headers, _payload = self._school_detail_http_request(
                    server["port"], env["users"]["manager"], "/schools/3/basic", "POST", form
                )

            saved = dict(env["db"].one("SELECT * FROM schools WHERE id=3"))
            self.assertEqual(status, 303)
            self.assertTrue(headers.get("Location", "").startswith("/schools/3?message="))
            self.assertIn("kind=success", headers["Location"])
            self.assertTrue(headers["Location"].endswith("#basic"))
            self.assertEqual(saved["sector_key"], "private")
            self.assertEqual(saved["school_type"], "Private")
            self.assertEqual(saved["school_name"], form["school_name_english"])
            self.assertEqual(saved["address"], form["address"])
            self.assertEqual(saved["notes"], before_school["notes"])
            self.assertEqual(saved["logo_file_path"], before_school["logo_file_path"])
            self.assertEqual(
                {table: env["db"].one(f"SELECT COUNT(*) count FROM {table}")["count"] for table in protected_before},
                protected_before,
            )
            nas_after = sorted(
                (str(path.relative_to(env["nas"])), path.stat().st_size, hashlib.sha256(path.read_bytes()).hexdigest())
                for path in env["nas"].rglob("*") if path.is_file() and not path.is_symlink()
            )
            self.assertEqual(nas_after, nas_before)
            self.assertEqual(mapping_path.read_bytes(), mapping_before)
            self.assertEqual(
                env["db"].one("SELECT COUNT(*) count FROM audit_logs WHERE action_type='school_updated'")["count"],
                1,
            )

