    def test_school_detail_sector_key_save_keeps_csrf_and_permissions_unchanged(self):
        with isolated_school_detail_regression_environment("sector-save-access") as env:
            original = dict(env["db"].one("SELECT * FROM schools WHERE id=3"))
            valid_form = self._school_detail_sector_key_save_form(env["users"]["admin"]["csrf"], "Public")
            with self._school_detail_http_server(env) as server:
                for bad_csrf in (None, "wrong-csrf"):
                    form = dict(valid_form)
                    if bad_csrf is None:
                        form.pop("csrf")
                    else:
                        form["csrf"] = bad_csrf
                    response = self._school_detail_http_request(
                        server["port"], env["users"]["admin"], "/schools/3/basic", "POST", form
                    )
                    self.assertEqual(response[0], 403)
                    self.assertEqual(dict(env["db"].one("SELECT * FROM schools WHERE id=3")), original)

                for role in ("consultant", "no_access"):
                    form = dict(valid_form, csrf=env["users"][role]["csrf"])
                    response = self._school_detail_http_request(
                        server["port"], env["users"][role], "/schools/3/basic", "POST", form
                    )
                    self.assertEqual(response[0], 403)
                    self.assertEqual(dict(env["db"].one("SELECT * FROM schools WHERE id=3")), original)

                allowed = self._school_detail_http_request(
                    server["port"], env["users"]["admin"], "/schools/3/basic", "POST", valid_form
                )

            self.assertEqual(allowed[0], 303)
            self.assertEqual(env["db"].one("SELECT sector_key FROM schools WHERE id=3")["sector_key"], "public")

    def test_school_document_preview_download_requires_school_ownership_and_preserves_valid_files(self):
        with isolated_school_detail_regression_environment("document-ownership-valid") as env:
            first = env["documents"][0]
            unicode_document = env["documents"][2]
            long_document = env["documents"][3]
            first_relative = first["path"].relative_to(env["nas"])

            handler = object.__new__(app_module.CRMHandler)
            handler.user = env["users"]["admin"]
            handler.csrf = env["users"]["admin"]["csrf"]
            document_panel = handler.school_documents_panel(env["db"].one("SELECT * FROM schools WHERE id=3"))
            expected_prefix = f'/schools/3/files/{quote(str(first_relative))}'
            self.assertIn(expected_prefix, document_panel)
            self.assertNotIn(f'/schools/files/{quote(str(first_relative))}', document_panel)
            self.assertIn(
                f'/schools/3/files/{quote(str(unicode_document["path"].relative_to(env["nas"])))}',
                document_panel,
            )
            audit_before = env["db"].one("SELECT COUNT(*) count FROM audit_logs")["count"]
            documents_before = env["db"].one("SELECT COUNT(*) count FROM school_documents")["count"]

            with self._school_detail_http_server(env, port=18805) as server:
                for role in ("admin", "manager", "consultant", "visa"):
                    preview = self._school_detail_http_request(
                        server["port"], env["users"][role], expected_prefix
                    )
                    self.assertEqual(preview[0], 200)
                    self.assertEqual(preview[2], first["payload"])
                    self.assertIn("inline", preview[1]["Content-Disposition"])

                download = self._school_detail_http_request(
                    server["port"], env["users"]["admin"], f"{expected_prefix}?download=1"
                )
                self.assertEqual(download[0], 200)
                self.assertEqual(download[2], first["payload"])
                self.assertIn("attachment", download[1]["Content-Disposition"])

                for document in (long_document,):
                    relative = document["path"].relative_to(env["nas"])
                    response = self._school_detail_http_request(
                        server["port"], env["users"]["admin"],
                        f"/schools/3/files/{quote(str(relative))}",
                    )
                    self.assertEqual(response[0], 200)
                    self.assertEqual(response[2], document["payload"])

            self.assertEqual(env["db"].one("SELECT COUNT(*) count FROM audit_logs")["count"], audit_before)
            self.assertEqual(
                env["db"].one("SELECT COUNT(*) count FROM school_documents")["count"],
                documents_before,
            )

    def test_school_document_preview_download_rejects_cross_school_and_unregistered_paths(self):
        with isolated_school_detail_regression_environment("document-ownership-reject") as env:
            school_a = env["documents"][0]
            unicode_document = env["documents"][2]
            school_b_path = env["other_document_path"]
            school_b_relative = school_b_path.relative_to(env["nas"])
            legacy_b_url = f"/schools/files/{quote(str(school_b_relative))}"
            cross_school_url = f"/schools/3/files/{quote(str(school_b_relative))}"
            env["db"].execute(
                "UPDATE schools SET logo_file_path=? WHERE id=5",
                (str(school_b_path),),
            )
            unregistered_path = env["nas"] / "VIC" / "Synthetic Rich School" / "Documents" / "Unregistered.pdf"
            unregistered_path.write_bytes(b"unregistered-school-file")
            unregistered_relative = unregistered_path.relative_to(env["nas"])
            removed_path = env["nas"] / "VIC" / "Synthetic Rich School" / "Documents" / "Removed Record.pdf"
            removed_path.write_bytes(b"removed-record-file")
            removed_id = env["db"].execute(
                """INSERT INTO school_documents(
                       school_id,document_type,original_filename,stored_filename,file_path,file_size,uploaded_by,uploaded_at
                   ) VALUES(3,'Brochure',?,?,?,?,901,?)""",
                (removed_path.name, removed_path.name, str(removed_path), removed_path.stat().st_size, "2026-07-23T12:00:00+10:00"),
            )
            env["db"].execute("DELETE FROM school_documents WHERE id=?", (removed_id,))
            missing_path = env["nas"] / "VIC" / "Synthetic Rich School" / "Documents" / "Physically Missing.pdf"
            env["db"].execute(
                """INSERT INTO school_documents(
                       school_id,document_type,original_filename,stored_filename,file_path,file_size,uploaded_by,uploaded_at
                   ) VALUES(3,'Brochure',?,?,?,?,901,?)""",
                (missing_path.name, missing_path.name, str(missing_path), 123, "2026-07-23T12:00:00+10:00"),
            )
            same_name_b = school_b_path.parent / school_a["filename"]
            same_name_b.write_bytes(b"same-name-school-b")
            env["db"].execute(
                """INSERT INTO school_documents(
                       school_id,document_type,original_filename,stored_filename,file_path,file_size,uploaded_by,uploaded_at
                   ) VALUES(5,'Brochure',?,?,?,?,901,?)""",
                (same_name_b.name, same_name_b.name, str(same_name_b), same_name_b.stat().st_size, "2026-07-23T12:00:00+10:00"),
            )

            read_paths = []
            original_read_bytes = Path.read_bytes

            def tracked_read_bytes(path):
                read_paths.append(Path(path).resolve())
                return original_read_bytes(path)

            with mock.patch.object(Path, "read_bytes", tracked_read_bytes):
                with self._school_detail_http_server(env, port=18805) as server:
                    for path in (
                        legacy_b_url,
                        cross_school_url,
                        f"{cross_school_url}?download=1",
                        f"/schools/3/files/{quote(str(unregistered_relative))}",
                        f"/schools/3/files/{quote(str(removed_path.relative_to(env['nas'])))}",
                        f"/schools/3/files/{quote(str(same_name_b.relative_to(env['nas'])))}",
                        f"/schools/5/files/{quote(str(unicode_document['path'].relative_to(env['nas'])))}",
                    ):
                        response = self._school_detail_http_request(
                            server["port"], env["users"]["admin"], path
                        )
                        self.assertEqual(response[0], 404)
                        self.assertNotIn(str(env["nas"]), response[2].decode("utf-8", errors="ignore"))

                    missing = self._school_detail_http_request(
                        server["port"], env["users"]["admin"],
                        f"/schools/3/files/{quote(str(missing_path.relative_to(env['nas'])))}",
                    )
                    self.assertEqual(missing[0], 404)
                    unknown_school = self._school_detail_http_request(
                        server["port"], env["users"]["admin"],
                        f"/schools/999999/files/{quote(str(school_a['path'].relative_to(env['nas'])))}",
                    )
                    self.assertEqual(unknown_school[0], 404)
                    denied = self._school_detail_http_request(
                        server["port"], env["users"]["no_access"],
                        f"/schools/3/files/{quote(str(school_a['path'].relative_to(env['nas'])))}",
                    )
                    self.assertEqual(denied[0], 403)

            self.assertNotIn(school_b_path.resolve(), read_paths)
            self.assertNotIn(unregistered_path.resolve(), read_paths)
            self.assertNotIn(removed_path.resolve(), read_paths)
            self.assertNotIn(same_name_b.resolve(), read_paths)

