    def test_school_detail_phase2_group_3_logo_and_file_boundaries(self):
        with isolated_school_detail_regression_environment("group-3") as env:
            handler = object.__new__(app_module.CRMHandler)
            handler.user = {"id": 901, "username": "school-admin-120", "role_name": "Admin"}
            handler.query = {}
            handler.client_address = ("127.0.0.1", 12003)
            handler.headers = {"User-Agent": "safebox-120-logo-file"}
            handler.response_status = None
            handler.response_headers = []
            handler.wfile = io.BytesIO()
            handler.send_response = lambda status: setattr(handler, "response_status", int(status))
            handler.send_header = lambda key, value: handler.response_headers.append((key, value))
            handler.end_headers = lambda: None
            handler.error_page = lambda message, status=400: (
                setattr(handler, "response_status", int(status)),
                setattr(handler, "response_text", str(message)),
            )

            rich = env["db"].one("SELECT * FROM schools WHERE id=3")
            simple = env["db"].one("SELECT * FROM schools WHERE id=2")
            escaped = env["db"].one("SELECT * FROM schools WHERE id=?", (env["escaped_logo_school_id"],))
            rich_logo = handler.school_logo_html(rich, large=True)
            self.assertIn("/schools/files/", rich_logo)
            self.assertIn("school-logo-image", rich_logo)
            self.assertIn("school-logo-placeholder", handler.school_logo_html(simple, large=True))
            self.assertIn("school-logo-placeholder", handler.school_logo_html(escaped, large=True))
            self.assertNotIn("outside-nas-boundary", handler.school_logo_html(escaped, large=True))

            first = env["documents"][0]
            relative = first["path"].relative_to(env["nas"])
            handler.school_file_download("GET", quote(str(relative)))
            self.assertEqual(handler.response_status, 404)
            self.assertEqual(handler.wfile.getvalue(), b"")

            handler.response_status = None
            handler.response_headers = []
            handler.wfile = io.BytesIO()
            handler.school_file_download("GET", 3, quote(str(relative)))
            self.assertEqual(handler.response_status, 200)
            self.assertEqual(handler.wfile.getvalue(), first["payload"])
            self.assertIn(("Content-Disposition", f'inline; filename="{first["filename"]}"'), handler.response_headers)

            handler.query = {"download": ["1"]}
            handler.response_headers = []
            handler.wfile = io.BytesIO()
            handler.school_file_download("GET", 3, quote(str(relative)))
            self.assertEqual(handler.wfile.getvalue(), first["payload"])
            self.assertIn(("Content-Disposition", f'attachment; filename="{first["filename"]}"'), handler.response_headers)

            handler.query = {}
            handler.response_headers = []
            handler.wfile = io.BytesIO()
            logo_relative = env["logo_path"].relative_to(env["nas"])
            handler.school_file_download("GET", quote(str(logo_relative)))
            self.assertEqual(handler.response_status, 200)
            self.assertEqual(handler.wfile.getvalue(), env["logo_path"].read_bytes())

            with self.assertRaises(NasSafetyError):
                handler.school_file_download("GET", 3, "../../database/aaie_crm.db")
            escaped_relative = env["escaped_file"].relative_to(env["nas"])
            with self.assertRaises(NasSafetyError):
                handler.school_file_download("GET", 3, quote(str(escaped_relative)))

            wrong_school = object.__new__(app_module.CRMHandler)
            wrong_school.user = handler.user
            wrong_school.form = {}
            wrong_school.query = {}
            wrong_school.client_address = handler.client_address
            wrong_school.headers = handler.headers
            wrong_school.error_page = lambda message, status=400: (
                setattr(wrong_school, "response_status", int(status)),
                setattr(wrong_school, "response_text", str(message)),
            )
            wrong_school.school_document_delete("POST", 3, env["other_document_id"])
            self.assertEqual(wrong_school.response_status, 404)
            self.assertTrue(env["other_document_path"].is_file())

