    def test_content_duplicate_script_detail_premium_v2_render_contract_is_isolated(self):
        old_db = app_module.db
        old_nas_status = app_module.nas.status
        with tempfile.TemporaryDirectory(dir="tmp") as folder:
            try:
                temp_root = Path(folder).resolve()
                database_path = temp_root / "database" / "aaie_crm.db"
                storage_root = temp_root / "storage"
                nas_root = temp_root / "synthetic-nas"
                database_path.parent.mkdir()
                storage_root.mkdir()
                nas_root.mkdir()
                temp_db = Database(database_path)
                app_module.db = temp_db
                app_module.nas.status = lambda: {
                    "status": "ok",
                    "ready": True,
                    "root": str(nas_root),
                }
                resolved = assert_isolated_handler_environment(temp_root, storage_root, nas_root)
                self.assertEqual(resolved, {
                    "database": str(database_path),
                    "storage": str(storage_root),
                    "nas": str(nas_root),
                })
                escaped_link = temp_root / "formal-database-link"
                escaped_link.symlink_to(Path("database").resolve(), target_is_directory=True)
                with self.assertRaisesRegex(AssertionError, "outside the temporary root"):
                    assert_isolated_handler_environment(temp_root, storage_root, escaped_link)
                escaped_link.unlink()
                temp_db.initialize()

                stamp = "2026-07-23T17:10:00+10:00"
                duplicate_group = "synthetic-duplicate-unicode"
                for index in range(34):
                    temp_db.execute(
                        """INSERT INTO content_import_staging(
                           import_batch_id,legacy_system_name,legacy_table_name,
                           legacy_record_id,old_title,old_body,old_category,
                           old_status,old_year,old_tags,old_source_type,
                           old_source_path,issue_flags_json,needs_review,
                           duplicate_title,duplicate_group_id,imported_at,
                           review_status
                           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (
                            "synthetic-duplicate-detail",
                            "synthetic",
                            "legacy_content",
                            1000 + index,
                            "Unicode 重复标题：" + "NoBreakTitle" * 8,
                            "" if index == 33 else (
                                "长正文与 Unicode：" + "留学内容比较。" * (20 + index)
                            ),
                            "LongCategoryWithoutSpacesABCDEFGHIJKLMNOPQRSTUVWXYZ",
                            "Legacy Draft",
                            2020 + index % 6,
                            "留学,签证,Unicode",
                            "gdoc" if index == 33 else "url",
                            "" if index == 33 else (
                                "/synthetic/" + "long-path-segment-" * 8 + str(index)
                            ),
                            "{}",
                            1,
                            1,
                            duplicate_group,
                            stamp,
                            "Needs Review",
                        ),
                    )

                script_id = temp_db.execute(
                    """INSERT INTO content_scripts(
                       title,body,category,status,review_status,version_number,
                       source_type,content_year,tags_json,notes,created_at,updated_at
                       ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        "Script Unicode 长标题：" + "NoBreakScriptTitle" * 8,
                        "完整长正文：" + "澳洲留学内容。" * 120,
                        "Planning",
                        "Draft",
                        "Not Reviewed",
                        3,
                        "CRM",
                        2026,
                        json.dumps(["留学", "Unicode"], ensure_ascii=False),
                        "长备注：" + "需要人工复核。" * 20,
                        stamp,
                        stamp,
                    ),
                )
                for version_number in (1, 2, 3):
                    temp_db.execute(
                        """INSERT INTO content_script_versions(
                           script_id,title,body,version_number,version_note,created_at
                           ) VALUES(?,?,?,?,?,?)""",
                        (
                            script_id,
                            f"历史版本 V{version_number}",
                            f"Version {version_number} body",
                            version_number,
                            "Synthetic visual history",
                            stamp,
                        ),
                    )

                admin = dict(temp_db.one(
                    "SELECT u.*,r.name role_name,r.permissions_json "
                    "FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username='admin'"
                ))
                admin["module_permissions_json"] = json.dumps(["content_center"])
                handler = object.__new__(app_module.CRMHandler)
                handler.user = admin
                handler.csrf = "content-duplicate-script-csrf"
                handler.client_address = ("127.0.0.1", 12600)
                handler.headers = {"User-Agent": "safebox-126-content-detail-isolated"}
                handler.message = lambda: ("", "success")

                def render(handler_method, record_id):
                    captured = {}
                    handler.send_html = lambda html, *args, **kwargs: captured.setdefault("html", html)
                    with mock.patch.object(
                        app_module.urllib.request,
                        "urlopen",
                        side_effect=AssertionError("external URL access blocked by SAFEBOX 126"),
                    ), mock.patch.object(
                        app_module.threading,
                        "Thread",
                        side_effect=AssertionError("background threads blocked by SAFEBOX 126"),
                    ):
                        getattr(handler, handler_method)("GET", record_id)
                    return captured["html"]

                def root_body(html, root):
                    match = re.search(
                        rf'<div class="{re.escape(root)}">(?P<body>.*?)</div>\s*</main>',
                        html,
                        flags=re.S,
                    )
                    self.assertIsNotNone(match)
                    return match.group("body")

                duplicate_html = render("content_duplicate_group_detail", duplicate_group)
                self.assertEqual(
                    duplicate_html.count('class="content-duplicate-detail-page"'),
                    1,
                )
                duplicate_body = root_body(
                    duplicate_html,
                    "content-duplicate-detail-page",
                )
                self.assertEqual(duplicate_body.count("<form"), 1)
                self.assertEqual(duplicate_body.count('name="csrf"'), 1)
                self.assertEqual(
                    duplicate_body.count('name="staging_ids"'),
                    34,
                )
                self.assertEqual(
                    duplicate_body.count('name="primary_staging_id"'),
                    33,
                )
                self.assertEqual(
                    re.findall(
                        r'<option value="([^"]+)"',
                        re.search(
                            r'<select name="action" required>(.*?)</select>',
                            duplicate_body,
                            flags=re.S,
                        ).group(1),
                    ),
                    [
                        "keep_separate",
                        "convert_to_versions",
                        "archive_placeholder",
                        "skip",
                        "left_for_later",
                    ],
                )
                self.assertEqual(duplicate_body.count("<button"), 1)
                self.assertIn(
                    "confirm('确认执行这个 Phase 6B 人工处理动作？系统不会删除记录。')",
                    duplicate_body,
                )
                self.assertIn("Unicode 重复标题", duplicate_body)
                self.assertIn("空正文 / 旧占位记录", duplicate_body)
                self.assertEqual(
                    duplicate_body.count('class="content-duplicate-member-card duplicate-compare-card"'),
                    34,
                )

                script_html = render("content_script_detail", script_id)
                self.assertEqual(
                    script_html.count('class="content-script-detail-page"'),
                    1,
                )
                script_body = root_body(script_html, "content-script-detail-page")
                self.assertEqual(script_body.count("<form"), 2)
                self.assertEqual(script_body.count('name="csrf"'), 2)
                for field_name in (
                    "title",
                    "category",
                    "content_year",
                    "status",
                    "review_status",
                    "tags",
                    "notes",
                    "body",
                ):
                    self.assertEqual(
                        len(re.findall(rf'name="{field_name}"', script_body)),
                        1 if field_name != "notes" else 2,
                    )
                for field_name in (
                    "checkpoint",
                    "views",
                    "likes",
                    "saves",
                    "comments",
                    "shares",
                ):
                    self.assertEqual(script_body.count(f'name="{field_name}"'), 1)
                self.assertEqual(
                    script_body.count('class="content-script-performance-section inner-panel"'),
                    1,
                )
                self.assertEqual(
                    script_body.count('class="content-script-version-section"'),
                    1,
                )
                self.assertEqual(script_body.count("<th>"), 3)
                self.assertEqual(script_body.count("<tbody>"), 1)
                self.assertIn("V1", script_body)
                self.assertIn("V2", script_body)
                self.assertIn("V3", script_body)
                self.assertEqual(script_body.count('href="/content"'), 1)
                self.assertNotIn("AI", script_body)
                self.assertNotIn("删除", script_body)
            finally:
                app_module.nas.status = old_nas_status
                app_module.db = old_db

    def test_content_duplicate_script_detail_premium_v2_css_is_strictly_scoped(self):
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        start_marker = "/* Premium V2 Content Duplicate and Script Detail Visual Map */"
        end_marker = "/* End Premium V2 Content Duplicate and Script Detail Visual Map */"
        self.assertIn(start_marker, css)
        self.assertIn(end_marker, css)
        scoped_css = css.split(start_marker, 1)[1].split(end_marker, 1)[0]

        for selector in (
            ".ui-premium-v2 .content-duplicate-detail-page",
            ".ui-premium-v2 .content-script-detail-page",
            ".ui-premium-v2 .content-duplicate-detail-page .content-duplicate-header",
            ".ui-premium-v2 .content-duplicate-detail-page .content-duplicate-members",
            ".ui-premium-v2 .content-duplicate-detail-page .content-duplicate-member-card",
            ".ui-premium-v2 .content-duplicate-detail-page .content-duplicate-actions",
            ".ui-premium-v2 .content-script-detail-page .content-script-header",
            ".ui-premium-v2 .content-script-detail-page .content-script-edit-section",
            ".ui-premium-v2 .content-script-detail-page .content-script-version-section",
            ".ui-premium-v2 .content-script-detail-page .content-script-performance-section",
        ):
            self.assertIn(selector, scoped_css)
        self.assertIn("@media (max-width: 760px)", scoped_css)
        self.assertIn("@media (max-width: 430px)", scoped_css)
        self.assertIn("overflow-wrap: anywhere", scoped_css)

        for selector in (
            ".ui-premium-v2 .content-detail-grid",
            ".ui-premium-v2 .panel",
            ".ui-premium-v2 .hero",
            ".ui-premium-v2 form",
            ".ui-premium-v2 input",
            ".ui-premium-v2 select",
            ".ui-premium-v2 textarea",
            ".ui-premium-v2 button",
            ".ui-premium-v2 table",
        ):
            self.assertNotRegex(
                scoped_css,
                rf"(?m)^\s*{re.escape(selector)}(?:\s|,|\{{)",
            )
        for protected_selector in (
            ".content-centre-page",
            ".content-create-page",
            ".content-extract-page",
            ".content-sync-page",
            ".content-tracking-page",
            ".content-analysis-page",
            ".content-topic-detail-page",
            ".content-staging-detail-page",
            ".agentreach",
            ".xhs-monitor",
        ):
            self.assertNotIn(protected_selector, scoped_css.lower())

    def test_content_duplicate_script_detail_premium_v2_static_business_boundaries(self):
        source = Path("app.py").read_text(encoding="utf-8")
        duplicate_detail = source[
            source.index("    def content_duplicate_group_detail(self, method, group_id):"):
            source.index("    def content_duplicate_group_action(self, method, group_id):")
        ]
        duplicate_action = source[
            source.index("    def content_duplicate_group_action(self, method, group_id):"):
            source.index("    def content_duplicate_batch(self, method):")
        ]
        script_detail = source[
            source.index("    def content_script_detail(self, method, script_id):"):
            source.index("    def content_staging_detail(self, method, staging_id):")
        ]
        self.assertIn('href="/content?tab=import&issue=duplicate_title"', duplicate_detail)
        self.assertIn(
            'action="/content/duplicates/{quote(group_id)}/action"',
            duplicate_detail,
        )
        self.assertIn("onclick=\"return confirm(", duplicate_detail)
        for action in (
            "keep_separate",
            "convert_to_versions",
            "archive_placeholder",
            "skip",
            "left_for_later",
        ):
            self.assertIn(f'value="{action}"', duplicate_detail)
            self.assertIn(f'if action == "{action}":', duplicate_action)
        self.assertIn("with db.transaction() as conn:", duplicate_action)
        self.assertIn("convert_duplicate_group_to_versions(", duplicate_action)
        self.assertIn("db.audit(", duplicate_action)

        self.assertIn(
            'action="/content/scripts/{script_id}/save"',
            script_detail,
        )
        self.assertIn(
            'formaction="/content/scripts/{script_id}/version"',
            script_detail,
        )
        self.assertIn('action="/content/performance/create"', script_detail)
        self.assertIn('href="/content"', script_detail)
        self.assertIn(
            'ORDER BY version_number',
            script_detail,
        )
        self.assertNotIn("urlopen", duplicate_detail)
        self.assertNotIn("urlopen", script_detail)
        self.assertNotIn("thread", duplicate_detail.lower())
        self.assertNotIn("thread", script_detail.lower())

        routes_start = source.index("            routes = [")
        routes = source[routes_start:source.index("            for pattern", routes_start)]
        self.assertIn(r'r"^/content/duplicates/([^/]+)$"', routes)
        self.assertIn(r'r"^/content/scripts/(\d+)$"', routes)
        protected_files = {
            "assets/app.js": "f80fbf21e62f95d15f9a4bdf0def094f2d1f530bb8ea80a05de751dbc2ec1ca4",
            "assets/style.css": "9fc557e471c5b7fd1cc02d64e804d3f087eb9b27f37d2c406a616f217065912e",
            "database.py": "2c67bada74011d366cbe675d20aa081aa5d29c6329bcaffc7870efb8b0823690",
            "nas.py": "1723d94039e447a9b50a0de52e2a024fd36e8ba351970fe7a40ba60bf5616860",
            "ui.py": "448597593921565c04cc17765c93bb3b8cca174683b3f7efcd754c23ef9b9bee",
            "adjustment.md": "64e7259bc3ed990f5231d389303f5dbc6f6f3cdc599ce3eefb42a702b9c29119",
        }
        for path, expected in protected_files.items():
            self.assertEqual(
                hashlib.sha256(Path(path).read_bytes()).hexdigest(),
                expected,
            )

