    def test_final_consistency_phase1a_css_is_strictly_scoped(self):
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        start_marker = "/* Premium V2 Final Consistency Fix Phase 1A */"
        end_marker = "/* End Premium V2 Final Consistency Fix Phase 1A */"
        self.assertEqual(css.count(start_marker), 1)
        self.assertEqual(css.count(end_marker), 1)
        block = css[
            css.index(start_marker):css.index(end_marker) + len(end_marker)
        ]
