    def test_path_containment(self):
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            self.assertEqual(ensure_within(root / "student", root), (root / "student").resolve())
            with self.assertRaises(NasSafetyError):
                ensure_within(root.parent / "outside", root)
            student_folder = root / "student"
            student_folder.mkdir()
            with self.assertRaises(NasSafetyError):
                ensure_within(root / "other-student" / "Passport.pdf", student_folder)

    def test_nas_status_rejects_mounted_but_write_denied_root(self):
        class FakeDB:
            def __init__(self, root):
                self.root = Path(root).resolve()

            def setting(self, key, default=None):
                values = {
                    "mode": "test",
                    "test_root": str(self.root),
                    "production_enabled": "false",
                    "mvp_production_locked": "true",
                }
                return values.get(key, default)

        with tempfile.TemporaryDirectory() as folder:
            mount = Path(folder).resolve()
            root = mount / "CRM_TEST"
            root.mkdir()
            denied = NasAccessStatus(
                root=str(root),
                mounted=True,
                root_exists=True,
                readable=True,
                writable=False,
                ready=False,
                error_code="write_denied",
                message="CRM 当前进程没有 NAS 写入权限。",
            )
            with mock.patch.object(nas_module, "STUDENTS_MOUNT", mount), mock.patch.object(
                nas_module, "TEST_ROOT", root
            ), mock.patch.object(
                nas_module, "inspect_nas_access", return_value=denied
            ):
                status = NasManager(FakeDB(root)).status()

        self.assertFalse(status["ready"])
        self.assertEqual(status["access_error_code"], "write_denied")
        self.assertEqual(status["access_message"], "CRM 当前进程没有 NAS 写入权限。")

