    def test_forms_folder_preflights_write_access(self):
        expected = Path("/synthetic/student/Forms")

        class FakeNas:
            def student_folder(self, student):
                raise AssertionError("Forms must use the shared write-access boundary")

            def require_category_access(self, student, category, *, write=False):
                self.called = (student, category, write)
                return expected

        old_nas = app_module.nas
        try:
            fake = FakeNas()
            app_module.nas = fake
            student = {"student_id": "TNASFORMS001", "folder_path": "/synthetic/student"}

            result = app_module.forms_folder_for_student(student)

            self.assertEqual(result, expected)
            self.assertEqual(fake.called, (student, "Forms", True))
        finally:
            app_module.nas = old_nas

    def test_basic_health_reports_nas_warning_without_taking_service_offline(self):
        denied = {
            "ready": False,
            "root": "/Volumes/Server/Students/CRM_TEST",
            "readable": True,
            "writable": False,
            "access_error_code": "write_denied",
            "access_message": "CRM 当前进程没有 NAS 写入权限。",
        }
        with mock.patch.object(app_module.nas, "status", return_value=denied):
            payload = app_module.basic_health_payload("admin", 8780)

        self.assertEqual(payload["status"], "ok")
        self.assertEqual(payload["dependencies"]["nas"], "warning")
        self.assertEqual(
            payload["nas"],
            {
                "ready": False,
                "root": "/Volumes/Server/Students/CRM_TEST",
                "readable": True,
                "writable": False,
                "error_code": "write_denied",
                "message": "CRM 当前进程没有 NAS 写入权限。",
            },
        )

