class GoogleDriveSafeUpdateIntegrationTests(unittest.TestCase):
    def test_routes_are_registered_with_bounded_preview_id(self):
        source = Path("app.py").read_text(encoding="utf-8")
        routes = source[source.index("            routes = ["):source.index("            for pattern, callback in routes:")]
        for route in (
            r'^/content/google-drive/status$',
            r'^/content/google-drive/scan$',
            r'^/content/google-drive/scan-jobs/([A-Za-z0-9_-]{8,80})$',
            r'^/content/google-drive/previews/([A-Za-z0-9_-]{1,160})$',
            r'^/content/google-drive/previews/([A-Za-z0-9_-]{1,160})/confirm$',
            r'^/content/google-drive/service/start$',
            r'^/content/google-drive/service/pause$',
            r'^/content/google-drive/logs$',
        ):
            self.assertIn(route, routes)

    @staticmethod
    def handler(user=None):
        handler = object.__new__(app_module.CRMHandler)
        handler.user = user or {"id": 7, "username": "sonnyz", "role_name": "Admin"}
        handler.csrf = "csrf-test"
        handler.form = {}
        handler.query = {}
        handler.client_address = ("127.0.0.1", 18780)
        handler.headers = {"User-Agent": "google-drive-safe-test"}
        handler.error_page = lambda message, status=400: (int(status), str(message))
        handler.deny_module_access = lambda module: (403, module)
        handler.flash_redirect = lambda location, message, kind="success": (location, message, kind)
        handler.json_response = lambda value, status=200: (int(status), value)
        return handler

    def test_mutating_handlers_enforce_method_and_backend_permission(self):
        handler = self.handler({"id": 9, "username": "ordinary", "role_name": "View Only"})
        mutating = (
            handler.content_google_drive_scan,
            handler.content_google_drive_service_start,
            handler.content_google_drive_service_pause,
        )
        for callback in mutating:
            self.assertEqual(callback("GET")[0], 405)
        with mock.patch.object(app_module, "can_module_action", return_value=False), mock.patch.object(
            app_module, "is_content_center_allowed_user", return_value=False
        ):
            for callback in mutating:
                self.assertEqual(callback("POST"), (403, "content_center"))
            self.assertEqual(handler.content_google_drive_confirm("POST", "scan-safe"), (403, "content_center"))
            self.assertEqual(handler.content_google_drive_logs("GET"), (403, "content_center"))

