    def test_quick_add_bad_csrf_returns_json_403_through_dispatch(self):
        form = urlencode({
            "csrf": "tampered-token",
            "content": "不应保存",
            "reminder_date": "2099-08-15",
            "reminder_time": "09:00",
            "recipient_id": str(self.admin["id"]),
            "quick_add": "1",
        }).encode("utf-8")
        handler = object.__new__(app_module.CRMHandler)
        handler.path = "/students/260300/followup-notes"
        handler.server = SimpleNamespace(service_mode="admin", server_port=0)
        handler.client_address = ("127.0.0.1", 12345)
        handler.headers = {
            "Content-Type": "application/x-www-form-urlencoded",
            "Content-Length": str(len(form)),
            "Accept": "application/json",
            "X-Requested-With": "fetch",
            "User-Agent": "unit-test",
        }
        handler.rfile = io.BytesIO(form)
        handler.wfile = io.BytesIO()
        handler.response_status = None
        handler.response_headers = []
        handler.send_response = lambda status: setattr(handler, "response_status", int(status))
        handler.send_header = lambda key, value: handler.response_headers.append((key, value))
        handler.end_headers = lambda: None
        handler.current_user = lambda: (self.admin, "valid-token")

        with mock.patch.object(app_module, "maybe_run_auto_backup", return_value=None):
            handler.dispatch("POST")

        self.assertEqual(handler.response_status, 403)
        self.assertIn(
            ("Content-Type", "application/json; charset=utf-8"),
            handler.response_headers,
        )
        self.assertEqual(
            json.loads(handler.wfile.getvalue()),
            {"ok": False, "message": "安全验证已过期，请刷新页面后重试。"},
        )
        self.assertEqual(
            self.database.one(
                "SELECT COUNT(*) total FROM reminders WHERE student_id=?",
                ("260300",),
            )["total"],
            0,
        )

