        selector_markup = source.split("def contract_student_selector_page", 1)[1].split(
            "def contract_student_selector_handoff", 1
        )[0]
        script = Path("assets/app.js").read_text(encoding="utf-8")
        self.assertIn("const initContractStudentSelector", script)
        selector_script = script.split("const initContractStudentSelector", 1)[1].split(
            "initContractStudentSelector();", 1
        )[0]
        css = Path("assets/ui-premium-v2.css").read_text(encoding="utf-8")
        selector_css = css.split("Premium V2 Contract Student Selector Visual Map", 1)[1]

        self.assertIn('autocomplete="off"', html)
