        self.assertIn('data-contract-student-results', html)
        self.assertIn('role="option"', search_html)
        self.assertNotIn('role="option"', recommendation_html)
        self.assertNotIn('aria-selected=', recommendation_html)
        self.assertLessEqual(search_html.count("data-contract-student-option"), 8)
        self.assertNotIn("<select", selector_markup)
